\section{Stochastic wave equations driven by finite-jump Lévy processes}
In this section, we analyze the direct problem of a stochastic wave equation driven by a finite-jump Lévy process and obtain stability estimates for its mild solutions. Subsequently, we discuss the inverse problem and reconstruct the source terms $f(x)$ and $g(x)$ based on a spectral decomposition method using global modes.

\subsection{Direct problem}
\begin{theorem}
	If $f,g\in L^2(D)$ and $\|g\|_{L^2(D)}\neq 0$, under the condition that the support of the non-negative function $h\in L^{\infty}(0,T)$ is a positive measure, the mild solution $(\ref{mild})$ will satisfy certain stability estimate
	\begin{equation}
		\begin{aligned}
			E \left[ \left\| u \right\|^2_{L^2(D \times [0,T])} \right] &\leq \frac{2T^4}{3} \| h \|^2_{L^\infty} \| f \|^2_{L^2(D)} + \left( \frac{2T^4 b^2 + T^3 \cdot \sigma^2 + T^3 \lambda_p \sigma_j^2}{3} \right) \| g \|^2_{L^2(D)}\\
			&\leq C \left( \| f \|^2_{L^2(D)} + \| g \|^2_{L^2(D)} \right).
		\end{aligned}
	\end{equation}
	where $C>0$ depends on time $T$, drift coefficient $b$, diffusion coefficient $\sigma$, and jump parameters $\lambda_{p}$ and $\sigma_{j}^2$.
\end{theorem}

\begin{proof}
	$a)$ In the stability estimate, $u_{\text{det}}(x,t)$ is expanded in terms of the characteristic function system of the Laplace operator
	\[ u_{\text{det}}(x,t) = \sum_{k=1}^{\infty} \left( \int_0^t \frac{\sin\left( (t-\tau)\sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} \left( f_k h(\tau) + g_k b \right) d\tau \right) \varphi_k(x). \]
	where $f_k=\langle f,\varphi_{k}\rangle$ and $g_k=\langle g,\varphi_{k}\rangle$.
	The $L^2(D)$-norm of the solution is the sum of the squares of the contributions from each mode
	\[ \left\| u_{\text{det}} \right\|^2_{L^2(D)} = \sum_{k=1}^{\infty} \left( \int_0^t \frac{\sin\left( (t-\tau)\sqrt{\lambda_k} \right)} {\sqrt{\lambda_k}} \left( f_k h(\tau) + g_k b \right) d\tau \right)^2. \]

	Apply the Cauchy-Schwarz inequality to the integral for each mode
	\[ \left( \int_0^t \frac{\sin\left( (t-\tau)\sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} \left( f_k h(\tau) + g_k b \right) d\tau \right)^2 \leq \left( \int_0^t \frac{\sin^2\left( (t-\tau)\sqrt{\lambda_k} \right)}{\lambda_ k} d\tau \right) \left( \int_0^t \left( f_k h(\tau) + g_k b \right)^2 d\tau \right). \]
	Estimating the first term on the right-hand side of the inequality, since for any real number $x$, $\sin^2(x) \leq x^2$, we get
	\[ \int_0^t \frac{\sin^2\left( (t-\tau)\sqrt{\lambda_k} \right)}{\lambda_k} d\tau \leq \int_0^t (t-\tau)^2 d\tau = \frac{t^3}{3}. \]
	Estimating the second term, since $(a+b)^2\leq 2(a^2+b^2)$, we have
	\[ \int_0^t \left( f_k h(\tau) + g_k b \right)^2 d\tau \leq 2 \left( f_k^2 \| h \|_{L^\infty}^2 \int_0^t d\tau + g_k^2 b^2 \int_0^t d\tau \right) = 2t \left( f_k^2 \| h \|_{ L^\infty}^2 + g_k^2 b^2 \right). \]
	Substituting this gives the estimate for each mode
	\[ \left( \int_0^t \frac{\sin\left( \cdot \right)}{\lambda_k} \left( f_k h + g_k b \right) d\tau \right)^2 \leq \frac{t^3}{3} \cdot 2t \left( f_k^2 \| h \|_{L^\infty}^2 + g_k^2 b^2 \right) = \frac{ 2t^4}{3} \left( f_k^2 \| h \|_{L^\infty}^2 + g_k^2 b^2 \right). \]
	Take the summation over all modes
	\[ \left\| u_{\text{det}} \right\|^2_{L^2(D)} \leq \frac{2t^4}{3} \sum_{k=1}^{\infty} \left( \| h \|_{L^\infty}^2 f_k^2 + b^2 g_k^2 \right). \]
	Furthermore,
	\[ \left\| u_{\text{det}} \right\|^2_{L^2(D)} \leq \frac{2t^4}{3} \left( \| h \|_{L^\infty}^2 \sum_{k=1}^{\infty} f_k^2 + b^2 \sum_{k=1}^{\infty} g_k^2 \right). \]
	and
	\[ \sum_{k=1}^{\infty} f_k^2 = \| f \|^2_{L^2(D)}, \quad \sum_{k=1}^{\infty} g_k^2 = \| g \|^2_{L^2(D)}. \]
	Finally, we obtain
	\[ \left\| u_{\text{det}} \right\|^2_{L^2(D)} \leq \frac{2t^4}{3} \left( \| h \|_{L^\infty}^2 \| f \|^2_{L^2(D)} + b^2 \| g \|^2_{L^2(D)} \right). \]
	Let \(C_1(T) = \frac{2t^4}{3} \max \left( \| h \|_{L^\infty}^2, b^2 \right)\), then we obtain
	\[ \left\| u_{\text{det}} \right\|^2_{L^2(D)} \leq C_1(T) \left( \| f \|^2_{L^2(D)} + \| g \|^2_{L^2(D)} \right). \]
	$b)$ The solution to the diffusion part is $u_{\text{diff}}(x, t) = \sigma \int_0^t K(x,t-\tau) g(x) dW_\tau$, where the kernel function is \[ K(x,t-\tau) = \sum_{\substack{k=1}}^{\infty} \frac{\sin \left( (t-\tau) \sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} \varphi_k(x). \]
	\[ \| u_{\text{diff}} \|^2_{L^2(D)} = \int_D \left( \sigma \left( \int_0^t K(x,t-\tau) g(x) dW_{\tau} \right)^2 \right) dx. \]
	Using Fubini's theorem, we have
	\[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] = \sigma^2 \int_D E\left[ \left( \int_0^t K(x,t-\tau) g(x) dW_{\tau} \right)^2 \right] dx. \]
	Since $E\left[ \left( \int_0^t H_{\tau} dW_{\tau} \right)^2 \right] = E\left[ \int_0^t H_{\tau}^2 d\tau \right]$, where $H_{\tau} = K(x,t-\tau) g(x)$, we have
	\[ E\left[ \left( \int_0^t K(x,t-\tau) g(x) dW_{\tau} \right)^2 \right] = E\left[ \int_0^t K(x,t-\tau)^2 g(x)^2 d\tau \right]. \]
	Since $K(x,t-\tau)^2 g(x)^2$ is deterministic, we get
	\[ E\left[ \int_0^t K(x,t-\tau)^2 g(x)^2 d\tau \right] = \int_0^t K(x,t-\tau)^2 g(x)^2 d\tau. \]
	Thus, \[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] = \sigma^2 \int_D \int_0^t K(x,t-\tau)^2 g(x)^2 d\tau dx. \]
	By interchanging the order of integration, we have
	\[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] = \sigma^2 \int_0^t \int_D K(x,t-\tau)^2 g(x)^2 dx d\tau. \]
	The inner integral is the square of the $L^2(D)$-norm of the kernel function and $g(x)$
	\[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] = \sigma^2 \int_0^t \| K(\cdot,t-\tau) g(\cdot) \|^2_{L^2(D)} d\tau. \]
	Expanding $g(x)$ in terms of the characteristic function system, we have
	\[ g(x) = \sum_{k=1}^{\infty} g_k \varphi_k(x), \quad g_k = \langle g, \varphi_k \rangle_{L^2(D)}. \]
	Then the product of the kernel function and $g(x)$ is
	\[ K(x,t-\tau)g(x) = \sum_{k=1}^{\infty} \frac{\sin\left((t-\tau)\sqrt{\lambda_k}\right)}{\sqrt{\lambda_k}} g_k \varphi_k(x). \]
	Using the orthogonality $\langle \varphi_k, \varphi_l \rangle = \delta_{kl}$, we obtain
	\[ \left\| K(\cdot, t - \tau)g(\cdot) \right\|^2_{L^2(D)} = \sum_{k=1}^{\infty} \left( \frac{\sin\left( (t - \tau) \sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} g_k \right)^2. \]
	Substituting the expected expression, we obtain
	\[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] = \sigma^2 \int_0^t \sum_{k=1}^{\infty} \frac{\sin^2\left( (t - \tau) \sqrt{\lambda_k} \right)}{\lambda_k} g_k^2 \, d\tau. \]
	An upper bound estimate is obtained for each k term
	\[ \int_0^t \frac{\sin^2\left( (t - \tau) \sqrt{\lambda_k} \right)}{\lambda_k} \, d\tau \leq \int_0^t (t - \tau)^2 \, d\tau = \frac{t^3}{3}. \]
	Therefore, \[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] \leq \frac{t^3 \cdot \sigma^2}{3} \sum_{k=1}^{\infty} g_k^2 = \frac{t^3 \cdot \sigma^2}{3} \| g \|^2_{L^2(D)}. \]
	In summary, there exists a constant $C_2$ related to $\sigma$ and $t$ such that
	\[ E\left[ \| u_{\text{diff}} \|^2_{L^2(D)} \right] \leq C_2 \| g \|^2_{L^2(D)}. \]

	For convenience, the following assumptions are needed.
	\begin{Assumption}
		Assume that the jump amplitude $J_s$ of the finite-jump Lévy process $L_t$ follows a normal distribution, and the jump time interval $s_j$ follows a Poisson distribution. i.e.,
		\begin{itemize}[left=5pt]
			\item The jump magnitudes $\left\{ J_{S_j} \right\}_{j=1}^{N_T}$ are independent and identically distributed, following $N(0,\sigma_{j}^2)$.
			\item The jump times $\left\{ S_j \right\}_{j=1}^{N_T}$ are spaced according to a Poisson distribution with parameter $\lambda_p$. (i.e., the expected number of jumps per unit time is $\lambda_p$)
		\end{itemize}
		At this point, the Lévy process decomposes into
		\[ L_t = bt + \sigma W_t + \sum_{j=1}^{N_t} J_{S_j}. \]
		where $N_t \sim \text{Poisson}(\lambda_p t)$ and $J_{S_j} \overset{\text{i.i.d.}}{\sim} N(0, \sigma_j^2)$.\\
		\label{assum:2}
	\end{Assumption}\noindent
	$c)$ Since the jump times are a random point process, the solution requires integration over the Poisson process, and equation (\ref{jump}) becomes
	\[ u_{\text{jump}}(x,t) = \sum_{j=1}^{N_t} K(x,t - s_j) g(x) J_{s_j} = \int_0^t K(x,t - \tau) g(x) \sum_{j=1}^{N_\tau} J_{s_j} \delta_{s_j} (d\tau). \]
	Thus, \[ \| u_{\text{jump}} \|^2_{L^2(D)} = \int_D \left( \sum_{j=1}^{N_t} \sum_{k=1}^{\infty} \frac{\sin\left( (T - s_j) \sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} g_k J_{s_j} \varphi_k(x) \right)^2 dx. \]
	Since the characteristic functions $\{\varphi_k\}$ are orthogonal, the cross terms integrate to zero, simplifying to
	\[ \left\| u_{\text{jump}} \right\|^2_{L^2(D)} = \sum_{k=1}^{\infty} \sum_{j=1}^{N_l} \left( \frac{\sin \left( \left( T - s_j \right) \sqrt{\lambda_k} \right)}{\sqrt{\lambda_k}} g_k J_{s_j} \right)^2. \]
	Taking the expectation and expanding the square
	\[ E\left[ \left\| u_{\text{jump}} \right\|^2_{L^2(D)} \right] = \sum_{k=1}^{\infty} E \left[ \sum_{j=1}^{N_l} \frac{\sin^2 \left( \left( T - s_j \right) \sqrt{\lambda_k} \right)}{\lambda_k} g_k^2 J_{s_j }^2 \right]. \]
	For the Poisson process $N_t$, by Campbell's theorem, the stochastic sum is converted to an integral
	\[ E \left[ \sum_{j=1}^{N_t} F(s_j) \right] = \lambda_p \int_0^t F(s) \, ds. \]
	where $F(s) = \frac{\sin^2 \left( (T - s_j) \sqrt{\lambda_k} \right)}{\lambda_k} g_k^2 E[J_{s_j}^2]$, substituting gives
	\[ E \left[ \left\| u_{\text{jump}} \right\|^2_{L^2(D)} \right] = \sum_{k=1}^{\infty} \lambda_p \sigma_j^2 \int_0^t \frac{\sin^2 \left( (T - s_j) \sqrt{\lambda_k} \right)}{\lambda_k} g_k^2 \, ds. \]
	Since $\int_0^t \frac{\sin^2 \left( (t-s) \sqrt{\lambda_k} \right)}{\lambda_k} \, ds \leq \int_0^t (t-s)^2 \, ds = \frac{t^3}{3}$, we obtain
	\[ E\left[ \left\| u_{\text{jump}} \right\|^2_{L^2(D)} \right] \leq \frac{t^3}{3} \lambda_p \sigma_j^2 \| g \|^2_{L^2(D)}. \]
	Namely, there exist constants $C_3$ related to $\sigma_{j}^2$, $\lambda_{p}$, and $t$ such that
	\[ E\left[ \left\| u_{\text{jump}} \right\|^2_{L^2(D)} \right] \leq C_3 \| g \|^2_{L^2(D)}. \]
	By (a), (b), and (c), we have
	Under the assumptions that $f,g\in L^2(D) $ and $b,\sigma\in \mathbb{R}$, the mild solution satisfies the following stability estimate
	\begin{align*}
		E \left[ \left\| u \right\|^2_{L^2(D \times [0,T])} \right] &\leq \frac{2T^4}{3} \| h \|^2_{L^\infty} \| f \|^2_{L^2(D)} + \left( \frac{2T^4 b^2 + T^3 \cdot \sigma^2 + T^3 \lambda_p \sigma_j^2}{3} \right) \| g \|^2_{L^2(D)}\\
		&\leq C \left( \| f \|^2_{L^2(D)} + \| g \|^2_{L^2(D)} \right).
	\end{align*}	
\end{proof}

In the following subsection, we will discuss the inverse problem.
\subsection{Inverse Problem}
For the ill-posedness of the inverse problem of a stochastic wave equation driven by a finite-jump Lévy process, it is necessary to design a regularization method. Currently, we consider handling the deterministic part by observing the mean (expectation) of the final-time data and handling the random source term by observing the covariance of the final-time data. This section analyzes the reconstruction of the deterministic term $f(x)$ and the random source term $g(x)$.

\subsubsection{Reconstruction of the deterministic term $f(x)$}
Expand the deterministic part into a set of eigenfunctions of the Laplace operator
\[ u_{\text{det}}(x,T) = \sum_{k=1}^{\infty} \left( f_k \int_0^T h(\tau) \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau + g_k b \int_0^T \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau \right) \varphi_k(x). \]
Using the uniqueness of the linear part: if $h(t)$ satisfies the non-degenerate condition (e.g., $h(t)$ is not zero everywhere on $[0,T]$), the reconstruction equation for the spectral coefficients
\[ E[u_k(T)] = f_k \int_0^T h(\tau) \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau + g_k b \int_0^T \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau. \]
If \(b = 0\) (i.e., there is no drift term in the Lévy process), then
\[ E[u_k(T)] = f_k \cdot \int_0^T h(\tau) \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau. \]
So we directly recover
\begin{equation}
	f_k = \frac{E[u_k(T)]}{\int_0^T h(\tau) \frac{\sin((T-\tau)\sqrt{\lambda_k})}{\sqrt{\lambda_k}} d\tau}.
	\label{f}
\end{equation}

\subsubsection{Reconstruction of random source term $g(x)$}
The linear property of the covariance function indicates that
\begin{equation*}
	\text{Cov}(u(x,T),u(y,T))=E\left[ (u-E[u])(u-E[u])^T \right].
\end{equation*}
Substituting the decomposed solution
\begin{align*}
	\text{Cov}(u(x,T), u(y,T)) &= E\left[(u_{\text{diff}} + u_{\text{jump}})(u_{\text{diff}} + u_{\text{jump}}) \right] \\
	&= E[u_{\text{diff}}(x,T) u_{\text{diff}}(y,T)] + E[u_{\text{jump}}(x,T) u_{\text{jump}}(y,T)].
\end{align*}

In fact, the cross term $E[u_{\text{diff}} u_{\text{jump}}]$
is zero, since the diffusion term $u_{\text{diff}}$ is driven by Brownian motion and the jump term $u_{\text{jump}}$ is driven by a jump process, and the two random sources are independent. Furthermore, the increments of Brownian motion and the jump process both have zero mean (even if the jump amplitude $J_{s}$ is non-zero, it is canceled out by centralization when calculating the covariance).

Assuming that the diffusion coefficient $\sigma $ and jump parameter $J_{s}$ are known, and by the properties of the Itô integral, the increments of Brownian motion at different time points are independent and orthogonal, then the covariance structure of the diffusion component
\begin{equation*}
	E\left[u_{\text{diff},k}(T) u_{\text{diff},l}(T)\right] = \sigma^2 E\left[\int_0^T \dfrac{\sin\left((T-\tau) \sqrt{\lambda_k}\right)}{\sqrt{\lambda_k}}   g_k dW_{\tau} \cdot \int_0^T \dfrac{\sin\left((T-\tau) \sqrt{\lambda_l}\right)}{\sqrt{\lambda_l}} g_l dW_{\tau}\right].
\end{equation*}
By the Itô equidistality and the independent incrementality of Brownian motion, the right-hand side of the above equation will be equal to
\begin{equation*}
	\sigma^2 g_k g_l \dfrac{1}{\sqrt{\lambda_k \lambda_l}}  \int_0^T \sin\left((T-\tau) \sqrt{\lambda_k}\right) \sin\left((T-\tau) \sqrt{\lambda_l}\right) d\tau.
\end{equation*}
Covariance structure of the jump part
\begin{align*}
	E[u_{\text{jump},k}(T) u_{\text{jump},l}(T)] &= \sum_{j=1}^{N_T} E\left[J_{s_j}^2 \frac{\sin((T - s_j) \sqrt{\lambda_k})}{\sqrt{\lambda_k}} \cdot \frac{\sin((T - s_j) \sqrt{\lambda_l})}{\sqrt{\lambda_l}} \right] g_k \cdot g_l \\ 
	&= \lambda_p E[J^2] \int_0^T \frac{\sin((T - \tau) \sqrt{\lambda_k})}{\sqrt{\lambda_k}} \cdot \frac{\sin((T - \tau) \sqrt{\lambda_l})}{\sqrt{\lambda_l}} g_k g_l d\tau.  
\end{align*}
Consequently,
\begin{align*}
	&\text{Cov}(u_k, u_l)\\ &= \sigma^2 g_k g_l \int_0^T \frac{\sin\left((T-\tau) \sqrt{\lambda_k}\right) \cdot \sin\left((T-\tau) \sqrt{\lambda_l}\right)}{\sqrt{\lambda_k \lambda_l}} d\tau + \lambda_p \sigma_j^2 \int_0^T \frac{\sin\left((T-\tau) \sqrt{\lambda_k}\right) \cdot \sin\left((T-\tau) \sqrt{\lambda_l}\right)}{\sqrt{\lambda_k \lambda_l}} g_k g_l d\tau \\
	&= g_k g_l \cdot (\sigma^2 + \lambda_p \sigma_j^2) \cdot I_{kl}.
\end{align*}
where $I_{kl}=\int_0^T \dfrac{\sin\left((T-\tau) \sqrt{\lambda_k}\right)\cdot \sin\left((T-\tau)\sqrt{\lambda_l}\right)}{\sqrt{\lambda_k \lambda_l}} d\tau$, thus
\begin{equation}
	g_k g_l = \frac{\text{Cov}(u_k, u_l)}{(\sigma^2 + \lambda_p \sigma_j^2) \cdot I_{kl}}
	\label{g}.
\end{equation}
The following theorem discusses the uniqueness of the inverse source problem.

\begin{theorem}
	Assume that Assumption $\ref{assum:2}$ holds. \\
	$(1)$ If $h(t)$ is a monotonically increasing function and $T$ is a rational number, or if $h(t)$ is a strictly monotonically increasing function and $T$ is a real number. then $f$ is uniquely determined by $\{E[u_k(T)]; k\in \mathbb{N}\}$. \\
	$(2)$ If $T$ is an arbitrary algebraic number, then the source term $g$ is uniquely determined by $\text{Cov}(u_k(T), u_l(T)); k,l\in \mathbb{N}$.
\end{theorem}
\begin{proof}
	The proof process for \textbf{(1)} is similar to the discussion of equation $(4.1)$ in Section 4.1 of \cite{feng2021inverse}, so it will not be repeated here. For the discussion of case \textbf{(2)}, we know that the eigenvalues and eigenvectors of the Laplace operator $-\Delta$
	\[ \lambda_k = k^2, \quad \varphi_k = \sqrt{\frac{2}{\pi}} \sin(kx), \quad k = 1, 2, \dots \]

	Considering the integral definition
	\begin{equation*}
		I_{kl} = \int_0^T \dfrac{\sin\left(k(T - \tau)\right)}{k}  \cdot \dfrac{\sin\left(l(T - \tau)\right)}{l} d\tau.
	\end{equation*}
	The simplified equivalent form (using the substitution $s=T - \tau $, $ds= -d\tau$)
	\begin{equation*}
		I_{kl} = \frac{1}{kl} \int_0^T \sin(ks) \cdot \sin(ls) \, ds.
	\end{equation*}
	when $k=l$, the integral simplifies to
	\begin{equation*}
		I_{kk} =\dfrac{1}{k^2}  \int_0^T \sin^2(ks) \, ds = \dfrac{1}{k^2} \left[ \frac{T}{2} - \frac{\sin(2kT)}{4k}  \right].
	\end{equation*}
	when $k \neq l$, using the trigonometric identity $\sin A \sin B = \frac{1}{2} \left[ \cos(A - B) - \cos(A + B) \right]$, the integral becomes
	\begin{equation*}
		I_{kl} =\dfrac{1}{2kl}  \int_0^T \left[ \cos((k-l)s) - \cos((k+l)s) \right] \, ds.
	\end{equation*}
	After calculating, we obtain
	\begin{equation}
		I_{kl} =\dfrac{1}{2kl} \left[ \frac{\sin\left((k-l)T\right)}{k-l} - \frac{\sin\left((k+l)T\right)}{k+l} \right].
		\label{ikl}
	\end{equation}
	If $k>l$, it is clear that for any algebraic $T$, $I_{kl}\neq 0$. If $I_{kl}=0$, then
	\[ \frac{\sin\left((k-l)T\right)}{k-l} - \frac{\sin\left((k+l)T\right)}{k+l}=0. \]
	From $\sin \theta = \frac{e^{i\theta}-e^{-i\theta}}{2i}$, we have
	\[ (k + l) e^{i(k - l)T} - (k + l) e^{-i(k - l)T} - (k - l) e^{i(k + l)T} + (k - l) e^{-i(k + l)T} = 0 .\]
	Let there be a set of distinct integers $\{k_1,k_2,\dots,k_n\}$ and a set of distinct real parameters $\{T_1,T_2,\dots,T_n\}$ such that $T_j$ is an algebraically independent number (satisfying the conditions of the Lindemann–Weierstrass theorem, see [\cite{baker2022transcendental}]). Define the matrix
	\[ M = \left( e^{i k_j T_l} \right)_{1 \leq j,l \leq n} .\]
	by expanding
	\[M = 
	\begin{pmatrix}
		e^{i k_1 T_1} & e^{i k_1 T_2} & \cdots & e^{i k_1 T_n} \\
		e^{i k_2 T_1} & e^{i k_2 T_2} & \cdots & e^{i k_2 T_n} \\
		\vdots       & \vdots       & \ddots & \vdots \\
		e^{i k_n T_1} & e^{i k_n T_2} & \cdots & e^{i k_n T_n}
	\end{pmatrix}
	\]
	Let
	\[
	z_l := e^{i T_l} \quad (1 \leq l \leq n).
	\]
	then
	\[
	M_{jl} = z_l^{k_j}.
	\]
	Assume that $k_j=k_1+(j-1)$, i.e., a set of consecutive increasing integers. Under this assumption, $M$ can be written as
	\[
	M = D \cdot V, \quad \text{where} \quad D = \mathrm{diag}(z_1^{k_1}, z_2^{k_1}, \ldots, z_n^{k_1}), \quad V_{jl} = z_l^{j-1}.
	\]
	$V$ is the classical Vandermonde matrix
	\[
	V = 
	\begin{pmatrix}
		1 & 1 & \cdots & 1 \\
		z_1 & z_2 & \cdots & z_n \\
		z_1^2 & z_2^2 & \cdots & z_n^2 \\
		\vdots & \vdots & \ddots & \vdots \\
		z_1^{n-1} & z_2^{n-1} & \cdots & z_n^{n-1}
	\end{pmatrix}
	\]
	and vandermonde determinant formula
	\[
	\det(V) = \prod_{1 \leq i < j \leq n} (z_j - z_i).
	\]
	Therefore,
	\[
	\det(M) = \det(D) \cdot \det(V) = \left( \prod_{l=1}^{n} z_l^{k_1} \right) \cdot \prod_{1 \leq i < j \leq n} (z_j - z_i).
	\]
	Since $z_l = e^{i T_l}$ and $T_l$ are distinct, $z_l$ are also distinct. The Lindemann–Weierstrass theorem guarantees the independence of $T_l$, so there are no repeated terms in $z_j$. Therefore, the Vandermonde determinant $\prod_{i<j} (z_j - z_i) \ne 0$. And since each $z_l^{k_1} \ne 0$, the overall determinant $\det(M) \ne 0$, which contradicts $I_{kl}=0$. Finally, for any $k,l\in \mathbb{N}$ and any algebraic $T$, we have $I_{kl}\neq 0$.
	In fact, when $k\approx l$, the denominator $k - l$ causes numerical instability. To address this, consider using the complex exponential method:
	Using Euler's formula $\cos(\theta) = \Re\left[e^{i\theta}\right]$, the integral can be transformed into
	\begin{equation*}
		\int_0^T \cos(ms) \, ds = \Re\left[\int_0^T e^{ims} \, ds \right].
	\end{equation*}
	Calculating the complex integral, we obtain
	\begin{equation*}
		\int_0^T e^{ims} \, ds = \frac{e^{imT} - 1}{im}.
	\end{equation*}
	Expanding into real and imaginary parts
	\begin{equation*}
		\dfrac{e^{imT} - 1}{im} = \dfrac{\cos(mT) + i \sin(mT) - 1}{im} = \dfrac{\sin(mT)}{m} + \dfrac{1 - \cos(mT)}{m}i.
	\end{equation*}
	Thus,
	\begin{equation*}
		I_{kl} = \dfrac{1}{2kl} \left[ \dfrac{\text{Im}(z_1)}{k-l} - \dfrac{\text{Im}(z_2)}{k+l}  \right].
	\end{equation*}
	where $z_1 = e^{i(k-l)T} - 1, \quad z_2 = e^{i(k+l)T} - 1$, hence equation (\ref{ikl}) is proven.
\end{proof}

\begin{remark}
	This optimization essentially suppresses high-frequency errors by analyzing the integral expression and avoiding direct calculation of the difference of oscillatory terms, thereby improving the accuracy of covariance kernel calculations in the inverse problem and ultimately improving the recovery effect of random source terms.
\end{remark}
The following theorem illustrates the stability of the reconstruction process for $f$ and $g$.

\begin{theorem}
	The recovery of source functions $f$ and $g$ in the inverse source problem is unstable, and the following estimate holds
	\[ \left| \int_0^T \frac{h(\tau) \sin \left( \sqrt{\lambda_k} (T - \tau) \right)}{\sqrt{\lambda_k}} \, d\tau \right| \leq \frac{1}{\sqrt{\lambda_k}} \int_0^T h(\tau) \, d\tau \to 0 \quad \text{as} \quad  k \to \infty,
	\]
	\[ E\left[\int_0^T \frac{\sin^2\left( (T - \tau) \sqrt{\lambda_k} \right)}{\lambda_k} \, d\tau\right] \leq \frac{T}{\lambda_{k}}. \]
\end{theorem}

\subsubsection{Numerical experimental design}
In this subsubsection, we will implement a numerical experiment design for simulating the forward problem of a stochastic wave equation driven by a finite-jump Lévy process and reconstructing the source function in one dimension. In the space-time domain, we set $x \in [0, L], \, t \in [0, T], \, L = \pi, \, T = 1$. Specifically, we first define the spatial grid and time grid
\[x_i = i \Delta x, \quad i = 0, 1, 2, \dots, N_x, \quad \Delta x = \frac{L}{N_x}, \quad N_x = 100. \]
\[t_j = j \Delta t, \quad j = 0, 1, 2, \dots, N_t, \quad \Delta t = \frac{T}{N_t}, \quad N_t = 1000. \]

Before simulating the direct problem, we need to discretize the kernel function and define the calculation method for its integral weights. Firstly, we discretize the eigenfunctions. Since we are studying a one-dimensional wave equation (with a Lévy driving term) with Dirichlet boundary conditions in the spatial segment, a set of orthogonal eigenfunctions of the $Laplace$ operator can be taken as
$\varphi_k(x_i) = \sqrt{\frac{2}{L}} \sin(k x_i), \, k = 1, \dots, K, \, i = 0, \dots, N_x.$ satisfying\[ -\frac{d^2}{dx^2} \varphi_k(x) = k^2 \varphi_k(x), \quad \varphi_k(0) = \varphi_k(L) = 0. \]
Define the kernel function $A_k(t_j) = \frac{\sin(k (T - t_j))}{k}, \, j = 0, \dots, N_t$. The product-of-integrals weights (matrix $I_{kl}$) can be written as
\[I_{kl} = \frac{1}{T} \int_0^T A_k(\tau) A_l(\tau) d\tau \approx \frac{1}{T} \sum_{j=0}^{N_t-1} A_k(t_j) A_l(t_j) \Delta t, \quad k, l = 1, \dots, K.\]
We then use spectral decomposition to expand the solution and source term in terms of a set of orthogonal eigenfunctions, projecting the original PDE onto these eigenmodes
\[ u(x,t) = \sum_{k=1}^{K} u_k(t) \varphi_k(x), \quad f(x) = \sum_{k=1}^{K} f_k \varphi_k(x), \quad g(x) = \sum_{k=1}^{K} g_k \varphi_k(x).
\]
When calculating the modal coefficients of the true value source terms, we need to perform numerical integration on $f_k$, $g_k$, and $u_k(T)$\\
\[
f_k = \sum_{i=0}^{N_x} f_{\text{true}}(x_i) \varphi_k(x_i) \Delta x, \quad g_k = \sum_{i=0}^{N_x} g_{\text{true}}(x_i) \varphi_k(x_i) \Delta x.
\]
\[
u_k(T) = (f_k + b g_k) \int_0^T A_k(\tau) \, d\tau + \sigma g_k \int_0^T A_k(\tau) \, dW(\tau) + g_k \sum_{s_j \leq T} A_k(s_j) J_j.
\]
The selection rules for the parameters of the finite Lévy jump process are: a) The number of jumps $N_J^{(n)} \sim \text{Poisson}(\lambda T)$. b) The jump times $\{s_j^{(n)}\}_{j=1}^{N_J^{(n)}}$ are uniformly sampled from $[0, T]$. c) The jump magnitudes $\{J_j^{(n)}\}_{j=1}^{N_J^{(n)}} \sim \mathcal{N}(0, \ sigma_J^2)$. The Brownian increments satisfy: $\text{For each time step } j = 1, \dots, N_t, \, \Delta W_j \sim \mathcal{N}(0, \Delta t). $
For the discrete treatment of each modal contribution in $u_k^{(n)}$, the deterministic time integral is discretized using the equidistant rectangular method, the random Brownian term is discretized using the classical Euler–Maruyama method, and the jump term is directly calculated using the continuous jump time obtained from sampling to compute $A_k(s_m)$
\[
u_k^{(n)} \approx \left( f_k + b g_k \right) \sum_{j=0}^{N_t-1} A_k(t_j) \Delta t + \sigma g_k \sum_{j=1}^{N_t} A_k(t_{j-1}) \Delta W_j + g_k \sum_{m=1}^{N_J^{(n)}} A_k( s_m) J_m.
\]
Next, spatial reconstruction and noise addition are performed, with noise selected as the commonly used Gaussian noise
\[
u_k^{(n)}(x_i, T) = \sum_{k=1}^{K} u_k^{(n)} \varphi_k(x_i), \quad u_{\text{obs}}(x_i) = u^{(n)}(x_i, T) + \epsilon_i^{(n)}, \quad \epsilon_i^{(n)} \sim \mathcal{N}(0, \sigma_\epsilon^2).
\]
Then, the overall mean and covariance are obtained through data statistics and projection.
\begin{itemize}[left=5pt]
	\item \textbf{Modal projection}
	\[
	U_k^{(n)} = \sum_{i=0}^{N_x} u_{\text{obs}}^{(n)}(x_i) \varphi_k(x_i) \Delta x, \quad k = 1, \dots, K, \quad n = 1, \dots, N_{\text{samples}}.
	\]

	\item \textbf{Sample mean}
	\[
	\bar{U}_k = \frac{1}{N_{\text{samples}}} \sum_{n=1}^{N_{\text{samples}}} U_k^{(n)}.
	\]

	\item \textbf{Sample covariance}
	\[
	C_{kl} = \frac{1}{N_{\text{samples}} - 1} \sum_{n=1}^{N_{\text{samples}}} (U_k^{(n)} - \bar{U}_k)(U_l^{(n)} - \bar{U}_l), \quad k, l = 1, \dots, K.
	\]
\end{itemize}

The handling of the reverse source problem is mainly achieved by reconstructing $f$ and $g$ using $(\ref{f})$ and $(\ref{g})$\\
\textbf{Deterministic source $f$}
The theoretical relationship
\[
\bar{U}_k = f_k = \sum_{j=0}^{N_t-1} A_k(t_j) \Delta t \quad \Rightarrow \quad f_k^{\text{rec}} = \bar{U}_k = \sum_{j=0}^{N_t-1} A_k(t_j) \Delta t.
\]
Spatial reconstruction formula
\[
f_{\text{rec}}(x_i) = \sum_{k=1}^{K} f_k^{\text{rec}} \varphi_k(x_i).
\]
\textbf{Random source $g$}
The model covariance is discretized as
\[
\hat{C}_{kl}(g) = \gamma g_k g_l I_{kl} + \sigma_\epsilon^2 \delta_{kl}.
\]
The objective function is expressed as follows
\[
J(g_1, \dots, g_K) = \sum_{k=1}^{K} \sum_{l=1}^{K} (C_{kl} - \hat{C}_{kl}(g))^2 + \alpha \sum_{k=1}^{K} g_k^2.
\]
where $\alpha$ is the regularization parameter.
Optimization yields $\{g_k^{\text{rec}}\}$, so that
\[
g_{\text{rec}}(x_i) = \sum_{k=1}^{K} g_k^{\text{rec}} \varphi_k(x_i).
\]
Finally, the $L^2$ error estimate is given by the following formula
\[
\epsilon_f = \frac{\sqrt{\sum_{i=0}^{N_x} \left(f_{\text{true}}(x_i) - f_{\text{rec}}(x_i)\right)^2 \Delta x}}{\sqrt{\sum_{i=0}^{N_x} f_{\text{true}}(x_i)^2 \Delta x}},
\]
\[
\epsilon_g = \frac{\sqrt{\sum_{i=0}^{N_x} \left(g_{\text{true}}(x_i) - g_{\text{rec}}(x_i)\right)^2 \Delta x}}{\sqrt{\sum_{i=0}^{N_x} g_{\text{true}}(x_i)^2 \Delta x}}.
\]

\begin{remark}
	In the random source term reconstruction process, we reconstruct $g$ rather than $g^2$. It should be noted that since the covariance of the observed data is insensitive to the sign of $g(x)$, the sign of its modal coefficient $g_k$ is ambiguous. Therefore, we perform phase correction in the code to obtain results that are more consistent with the actual situation, but this usually requires additional prior information. However, in practical applications, since the true sign is unknown, such direct correction is often infeasible, necessitating the reconstruction of $g^2$ or the use of other methods to address the issue of sign uncertainty.  
\end{remark}

