The normalized channel estimation and interpolation \ac{MSE} is represented by
\begin{equation} 
    \mathrm{NMSE} = \frac{1}{L_r N^{\left( \rm m \right)}}
    \sum_{l=1}^{L_r} \sum_{n=1}^{N^{\left( \rm m \right)}} 
    \frac{
    \norm{
    \mathbf{H}_l^{\left( {\rm m} \right)} [n]
    - \overline{\mathbf{H}}_l^{ \left( {\rm m} \right)} [n]
    }_{F}^2}
    {\norm{\mathbf{H}_l^{ \left( {\rm m} \right)} [n]}_{F}^2},
\label{eq:mse}
\end{equation}
where $L_r$ denotes the number of realizations and $l$ indicates a specific channel~realization.
The achievable \ac{SE}, averaged over $N^{\left( \rm m \right)}$ subcarriers and expressed in bits$/$s$/$Hz, is defined by
\begin{equation} 
    \mathrm{SE}= 
    \frac{1}{N^{\left( \rm m \right)}} 
    \sum_{n=1}^{N^{\left( \rm m \right)}} 
    \sum\limits_{\mu=1}^{\ell_{\rm max}} 
    \log_2 \left( 1 + \mathrm{SINR}_{\rm \mu} [n] \right),
    \label{eq:se}
\end{equation}
where the effective \ac{SINR} for the stream ${\rm \mu}$ is given by~\cite{Pasic2024_TCOM}
\begin{equation} 
    \mathrm{SINR}_{\rm \mu} [n] = \frac{ 
    \left| \overline{\mathrm{G}}_{\rm \mu,\mu}^{\left( {\rm m} \right)} [n] \right|^2 }
    { \sum\limits_{\substack{\nu=1 \\ \nu \neq \mu}}^{\ell_{\rm max}} 
    \left| \overline{\mathrm{G}}_{\rm \mu, \nu}^{\left( {\rm m} \right)} [n] \right|^2
    + \left( \sigma_{\rm \mu}^2 [n] + \sigma_{w^{\left( \rm m \right)}}^2 \right) 
    \norm{ \overline{\mathrm{Q}}_{\rm :,\mu}^{\left( {\rm m} \right)} [n] }^2 }.    
    \label{eq:sinr}
\end{equation}
In~\cref{eq:sinr}, $\overline{\mathrm{G}}_{\rm \mu,\nu}^{\left( {\rm m} \right)} [n]$ with $\mu, \nu \in \{ 1, \ldots, \ell_{\rm max} \} $ represents the elements of the channel gain matrix $\overline{\mathbf{G}}^{\left( {\rm m} \right)} [n] \in \mathbb{C}^{\ell_{\rm max} \times \ell_{\rm max}}$ for the $n$-th subcarrier, defined as
\begin{equation}
    \overline{\mathbf{G}}^{\left( {\rm m} \right)} [n]= 
    \left( \overline{\mathbf{Q}}^{\left( {\rm m} \right)} [n] \right) ^ {\rm H} 
    \mathbf{H}^{\left( {\rm m} \right)} [n]
    \overline{\mathbf{F}}^{\left( {\rm m} \right)} [n] 
    \left( \overline{\mathbf{P}}^{\left( \rm m \right)} [n] \right)^{1/2}.
    \label{eq:chgain}
\end{equation}
Moreover, $ \sigma_{\rm \mu}^2 [n]$ denotes the diagonal entries (variance) of the estimation error covariance 
$    \overline{\mathbf{C}}_{\varepsilon}^{\left( {\rm m} \right)} [n] = 
    \frac{1}{\ell_{\rm max}}
    \overline{\boldsymbol{\varepsilon}}^{\left( {\rm m} \right)} [n] 
    \left( \overline{\boldsymbol{\varepsilon}}^{\left( {\rm m} \right)} [n] \right)^{\rm H}
$
for the $n$-th subcarrier.
The error $\overline{\boldsymbol{\varepsilon}}^{\left( {\rm m} \right)} [n]$ quantifies the difference between the channel gain matrix computed with the estimated precoder/combiner
$\overline{\mathbf{G}}^{\left( {\rm m} \right)} [n]$, and the channel gain matrix obtained using the ideal precoder/combiner $\mathbf{G}^{\left( {\rm m} \right)} [n]$.

