In order to analytically investigate the distribution of the \ac{CD} and \ac{CFA} probabilities, we need to characterize higher order moments of the point processes. One such result is the second order Campbell-Mecke theorem stated below.

\begin{lemma}~\cite{chiu2013stochastic}
Let $\Phi$ be a simple and locally finite point process on $\mathbb{R}^d$, and let 
$f: \mathbb{R}^d \times \mathbb{R}^d \times \mathcal{N} \to [0, \infty)$ be a measurable function, 
where $\mathcal{N}$ denotes the space of locally finite counting measures on $\mathbb{R}^d$. 
Then the following identity holds:
\begin{align}
&\mathbb{E} \left[ \sum_{x \in \Phi} \sum_{\substack{y \in \Phi \\ y \neq x}} f(x, y, \Phi) \right] \nonumber \\
&= \iint_{\mathbb{R}^d \times \mathbb{R}^d} \mathbb{E} \left[ f(x, y, \Phi \cup \{x, y\}) \right] 
\rho^{(2)}(x, y) \, dx \, dy,
\end{align}
where $\rho^{(2)}(x, y)$ denotes the second-order product density of $\Phi$. The function $f$ 
may depend on the configuration $\Phi$, and the expectation on the right-hand side is taken with 
respect to the law of $\Phi$. In addition, if $\Phi$ is a stationary \ac{PPP} with intensity $\lambda > 0$, then 
$\rho^{(2)}(x, y) = \lambda^2$, and the identity simplifies to:
\begin{align}
\mathbb{E} \left[ \sum_{x \in \Phi} \sum_{\substack{y \in \Phi \\ y \neq x}} f(x, y) \right]
= \lambda^2 \iint_{\mathbb{R}^d \times \mathbb{R}^d} f(x, y) \, dx \, dy.
\end{align}
\end{lemma}


\section{Distribution Bound for the \ac{CFA} Probability}
\label{sec:CFA}
In this section we derive bounds and an accurate approximation for the distribution of the \ac{CFA} probability. The random \ac{CFA} probability is derived as
\begin{align}
    P_{\rm FA_\Phi} &=  \mathbb{P}\left(\sum_{i \in \Phi} w_i h_i + N_0 \geq \gamma \mid \Phi\right) \nonumber \\
    &=\mathbb{P}\left(\sum_{i \in \Phi} w_i h_i \geq \gamma  - N_0 \mid \Phi\right) \nonumber \\
    &= \sum_{i \in \Phi}\left(\prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - r_i ^\alpha}\right)\exp\left(-\frac{\gamma - N_0}{KPr_i^{-\alpha}}\right).
\end{align}
The above follows from the fact that since $\{h_i\}$ are iid exponentially distributed with parameter 1, the addition of the weights $w_i$ results in $\sum w_ih_i$ being a hypoexponential random variable with phase-type distribution with the above \ac{CCDF}~\cite{o1990characterization}. Note that the first term inside the summation, i.e., the product term does not contain the transmit power $P$ as a constituent since we assume that the power to be the same across all nodes. To simplify the notation, let us denote
\begin{align}
    f(x) = \exp\left(-\frac{\gamma - N_0}{KPx^{-\alpha}}\right); \qquad g(x,y) = \frac{y^\alpha}{x^\alpha - y^\alpha}. \label{eq:fg_approximation}
\end{align}
Accordingly, the \ac{CFA} probability is a special form of sum-product functional:
\begin{align}
F = \sum_{x \in \Phi} f(x) \prod_{\substack{y \in \Phi \\ y \neq x}} g(x, y),
\end{align}
where \( f: \mathbb{R}^d \to [0, \infty) \) and \( g: \mathbb{R}^d \times \mathbb{R}^d \to [0, \infty) \) are measurable functions. Contrary to other stochastic geometry based analysis that characterize the distribution of the \ac{SINR}, we cannot employ inversion theorems (e.g., Gil-Pelaez theorem) to the quantity above. This is precisely due to the fact that the characteristic function of the \ac{CFA} probability is intractable. In this regard, we rely on higher order Campbell-Mecke formulae to derive bounds of the distribution of $P_{{\rm FA}_\Phi}$.
\begin{theorem}
    The mean of the \ac{CFA} probability is the probability of false-alarm across all network realizations, and is given by
    \begin{align}
       p_{\rm FA}= \lambda\int_{\mathbb{R}^d} \exp\left(-\frac{\gamma - N_0}{KPx^{-\alpha}}\right) \exp\left(-\lambda \int_{\mathbb{R}^d} \frac{x^\alpha}{y^\alpha - x ^\alpha} {\rm d} y\right) {\rm d}x.
    \end{align}
    Furthermore, the variance of the \ac{CFA} probability across different network realizations is
    \begin{align}
        \mathbb{V}(P_{{\rm FA}_\Phi}) = T_1 + T_2 - p_{\rm FA}^2,
    \end{align}
    where 
    \begin{align}
        T_1 &= \lambda\int_{\mathbb{R}^d} f^2(x)\exp\left(-\lambda\int_{\mathbb{R}^d}\left(1 - g^2(x,y)\right){\rm d}y\right){\rm d}x \nonumber \\
    T_2 &= \lambda^2\iint f(x)f(x')g(x,x')g(x',x) \cdot\nonumber \\
    & \exp\left(-\lambda \right. \int_{\mathbb{R}^d} 1 -\left.g(x,y)g(x',y) {\rm d}y{\rm d}x{\rm d}x'\right) \nonumber 
    \end{align}
    and the functions $f(\cdot)$ and $g(\cdot,\cdot)$ are defined in \eqref{eq:fg_approximation}.

\end{theorem}
\begin{IEEEproof}
The mean of $P_{{\rm FA}_\Phi}$ is evaluated as
    \begin{align}
       &p_{\rm FA} =  \mathbb{E}\left[\sum_{i \in \Phi}\left(\prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - r_i ^\alpha}\right)\exp\left(-\frac{\gamma - N_0}{KPr_i^{-\alpha}}\right)\right] \nonumber \\
       & \overset{(a)}{=}\lambda \int_{\mathbb{R}^d} \mathbb{E}^{!x}\left[\exp\left(-\frac{\gamma - N_0}{KPx^{-\alpha}}\right)\prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - x ^\alpha}\right] {\rm d}x \nonumber \\
       & \overset{(b)}{=} \lambda \int_{\mathbb{R}^d} \exp\left(-\frac{\gamma - N_0}{KPx^{-\alpha}}\right) \mathbb{E}\left[\prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - x ^\alpha}\right] {\rm d}x \nonumber \\
       & \overset{(c)}{=}\lambda\int_{\mathbb{R}^d} \exp\left(-\frac{\gamma - N_0}{KPx^{-\alpha}}\right) \exp\left(-\lambda \int_{\mathbb{R}^d} \frac{x^\alpha}{y^\alpha - x ^\alpha} {\rm d} y\right) {\rm d}x.
       \label{eq:EF}
    \end{align}
The step $(a)$ follows from Campbell's theorem of homogeneous \ac{PPP}, i.e., $\mathbb{E}_{x\in \Phi}\left[f(x)\right] = \lambda\int_{\mathbb{R}^d} f(x)dx$. However the term inside consists of the product over the process $\Phi\backslash\{x\}$ which is taken care by considering the reduced Palm expectation $\mathbb{E}^{!x}[\cdot]$. The reduced Palm expectation is a tool of Palm calculus that evaluates the expectation by conditioning the existence of a point of $\Phi$ at $x$ and then removing it to take the expectation. Thanks to Slivnyak's theorem this is equal in probability law to the distribution of $\Phi$, as shown in step $(b)$. Finally, the step $(c)$ follows from the \ac{PGFL} of a \ac{PPP}.

Next, we turn our focus on the variance of $P_{{\rm FA}_\Phi}$ defined as
\begin{align}
    &\mathbb{V}(P_{{\rm FA}_\Phi}) = \mathbb{E}\left[P^2_{{\rm FA}_\Phi}\right] - \left(\mathbb{E}\left[P_{{\rm FA}_\Phi}\right]\right)^2. 
    \label{eq:var}
\end{align}
The second moment can be expressed as
\begin{align}
    P^2_{{\rm FA}_\Phi} &= \left(\sum_{i \in \Phi}\left(\prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - r_i ^\alpha}\right)\exp\left(-\frac{\gamma - N_0}{KPr_i^{-\alpha}}\right)\right)^2 \nonumber \\
    &= \sum_{i \in \Phi}\sum_{k \in \Phi} \exp\left(-\frac{\gamma - N_0}{KPr_i^{-\alpha}}\right)\exp\left(-\frac{\gamma - N_0}{KPr_k^{-\alpha}}\right)  \nonumber \\
    &\qquad \qquad \prod_{j \in \Phi\backslash i} \frac{r_j^\alpha}{r_j^\alpha - r_i ^\alpha} \prod_{l \in \Phi\backslash k} \frac{r_l^\alpha}{r_l^\alpha - r_k ^\alpha}.
\end{align}
The above includes both the diagonal terms, i.e., $i = k$ and the off-diagonal terms, i.e., $i \neq k$. Let us now consider the notation introduced in \eqref{eq:fg_approximation}, and apply the second order Campbell-Mecke theorem to get
\begin{align}
    \mathbb{E}\left[P^2_{{\rm FA}_\Phi}\right]   = \lambda \int_{\mathbb{R}^d} \mathbb{E}\left[f^2(x)\prod g^2(x,y)\right] {\rm d}x +\lambda^2\iint_{\mathbb{R}^d \times\mathbb{R}^d}  \nonumber \\
    \mathbb{E}\left[f(x)f(x') \prod_{y \in \Phi}g(x,y) g(x',y)g(x,x')g(x',x)\right] {\rm d}x {\rm d}x'.
\end{align}
The first term is the contribution for $i = k$ while the second term is for $i \neq k$. Using reduced Palm expectations at two points (which for \ac{PPP} is again the same as the original law), we get
\begin{align}
   \mathbb{E}\left[P^2_{{\rm FA}_\Phi}\right]  &= \lambda\int_{\mathbb{R}^d} f^2(x)\exp\left(-\lambda\int_{\mathbb{R}^d}\left(1 - g^2(x,y)\right){\rm d}y\right){\rm d}x \nonumber \\
    &+\lambda^2\iint f(x)f(x')g(x,x')g(x',x) \cdot\nonumber \\
    & \exp\left(-\lambda \right. \int_{\mathbb{R}^d} 1 -\left.g(x,y)g(x',y) {\rm d}y{\rm d}x{\rm d}x'\right) 
    \label{eq:EF_square}
\end{align}
Substituting \eqref{eq:EF_square} and \eqref{eq:EF} in \eqref{eq:var} completes the proof.
\end{IEEEproof}

Leveraging the mean and the variance of the \ac{CFA} probability, we derive a bound on its \ac{CCDF} that is much tighter than the Chebyshev bound.
\begin{theorem}
    Using Cantelli's bound,
    \begin{align}
        \mathbb{P}\left(P_{\rm{FA}_\Phi} \geq t\right) \leq \frac{\mathbb{V}(P_{\rm{FA}_\Phi})}{\mathbb{V}(P_{\rm{FA}_\Phi}) + \left(t - p_{\rm FA}\right)^2}, \quad t \geq p_{\rm FA}.
    \end{align}
    \label{theo:Cant_FA}
\end{theorem}


\begin{remark}
    A relatively simple but loose bound follows from Markov's inequality
    \begin{align}
        \mathbb{P}\left(P_{\rm{FA}_\Phi} \geq t\right) \leq \frac{p_{\rm FA}}{t}.
    \end{align}
    Since we are mostly interested in the tail bounds of $P_{{\rm FA}_\Phi}$ for $t \geq p_{\rm FA}$ in order to derive performance guarantees on the radar performance, the above results in a valid probability bound (i.e., the right hand side is lower than 1).
\end{remark}

\subsection{Approximation using Beta Functions}
Next we provide a simple yet accurate approximation of the distribution of $P_{{\rm FA}_\Phi}$ using the beta distribution. This approximation arises naturally as the support of $P_{{\rm FA}_\Phi}$ is $[0, 1]$. The corresponding distribution can be approximated as the beta distribution by matching the first moment $M_1$ and the second moment $M_2$. Specifically, the MD can be approximately expressed as
\begin{align*}
    \bar{F}(\beta, t) \approx 1 - I_{\varepsilon}\left(\frac{k_1 k_2}{1-k_1}, k_2\right),
\end{align*}
where $I_{\varepsilon}(x,y) = \int_0^{1-\varepsilon} z^{x-1}(1-z)^{y-1}\mathrm{d}z/B(x,y)$ is the regularized incomplete beta function with $B(\cdot, \cdot)$ the beta function, $k_1 = P_{\rm FA}$, and 
$$k_2 = \left(p_{\rm FA} - \mathbb{E}\left[P^2_{{\rm FA}_\Phi}\right]\right)\left(1-p_{\rm FA}\right)/\left(\mathbb{E}\left[P^2_{{\rm FA}_\Phi}\right] - p_{\rm FA}^2\right).$$ The accuracy of the beta approximation is confirmed in Fig.~\ref{fig:bound}.


