    "Conciseness": \{
      "Score": 3,
      "Explanation": "Keywords are clear, with no stopwords or meaningless terms, and no redundancy detected."
    \},

    "Informativity": \{
      "Score": 2,
      "Explanation": "The topic only covers the main aspects of financial investment but lacks detailed descriptions of specific markets or investment tools."
    \}
  \}
\}



