		\subsection{Punctured codes}
	Let $\boldsymbol{x} \in \mathbb{F}_q^n$ and $I=\left\{i_1, \ldots, i_m\right\} \subseteq [n]$ with $1 \leq i_1<\cdots<i_m \leq n$, we define $\boldsymbol{x}_I=\left(x_{i_1}, \ldots, x_{i_m}\right) \in \mathbb{F}_q^m$, namely, $\boldsymbol{x}$ is restricted to the coordinates indexed by $I$. Let $\bar{I}=[n] \backslash I$ be the complement set of $I$ in $[n]$. The punctured code is defined as the following. For more details, see \cite{A11}.

	\begin{definition}\label{D_2}
		{\rm({\rm\cite{A11}}, Punctured code)} Let $\mathcal{C}$ be an $[n, k, d]_q$ linear code and $I=\left\{i_1, \ldots, i_m\right\} \subseteq [n]$. The punctured code of $\mathcal{C}$ is defined as
		$$
		\mathcal{C}_I=\left\{c_{\bar{I}} \mid c \in \mathcal{C}\right\}, 
		$$
		which is an $\left[n-m, k\left(\mathcal{C}_I\right), d\left(\mathcal{C}_I\right)\right]_q$ linear code with $d-m \leq d\left(\mathcal{C}_I\right) \leq d$ and $k-m \leq k\left(\mathcal{C}_I\right) \leq k$. Moreover, if $m<d$, then $k\left(\mathcal{C}_I\right)=k$.
	\end{definition}

	The following lemma is necessary for the proof of Remark \ref{R_21}.

	\begin{lemma}\label{L_1}{\rm(\cite{A6}, Lemma 5.3)}
		Let $\mathcal{C}$ be an $[n, k]_q $ MDS linear code and $I$ be a subset of $[n]$ with $m$ elements such that $n-m \geq k$. Then $\mathcal{C}_I$ is also an MDS linear code with parameters $[n-m, k]_q$.
	\end{lemma}


	\subsection{GRS codes and TGRS codes}
	Now, let us recall the definitions of the GRS and the TGRS code, for more details, see [\citealp{A7},\citealp{A9},\citealp{A11},\citealp{A8}].%,\citealp{A10}].

	\begin{definition}{\rm(\cite{A11})}
		Let $\boldsymbol{\alpha}=\left(\alpha_1, \ldots, \alpha_n\right) \in \mathbb{F}_q^n$ with $\alpha_i \neq \alpha_j(i \neq j)$ and $\boldsymbol{v}=\left(v_1, \ldots, v_n\right) \in$ $\left(\mathbb{F}_q^*\right)^n$. The GRS code with length $n$ and dimension $k$ is defined as
		$$
		G R S_k(\boldsymbol{\alpha}, \boldsymbol{v})=\left\{\left(v_1 f\left(\alpha_1\right), \ldots, v_n f\left(\alpha_n\right)\right) \mid f(x) \in \mathbb{F}_q[x],~\operatorname{deg}(f(x)) \leq k-1\right\}.
		$$
		The $n$-tuple $\boldsymbol{\alpha}$ is called the evaluation-point sequence. It is well-known that $G R S_k(\boldsymbol{\alpha}, \boldsymbol{v})$ is an MDS linear code with parameters $[n, k, n-k+1]_q$ and the corresponding dual code is also a GRS code with the same evaluation-point sequence.
	\end{definition} 

	\begin{definition}{\rm(\cite{A7})}
		Let $k, t \in \mathbb{Z}^{+}, h \in \mathbb{N}$ with $0 \leq h<k \leq q$, and $\eta \in \mathbb{F}_q^*$. Define the set of $(k, \eta, t, h)$-twisted polynomials by
		$$
		\mathcal{V}_{k, \eta, t, h}=\left\{f(x)=\sum_{i=0}^{k-1} a_i x^i+\eta a_h x^{k-1+t} \mid a_i \in \mathbb{F}_q,~0 \leq i \leq k-1\right\},
		$$
		which is a $k$-dimensional $q$-ary linear subspace. We call $t$ the twist and $h$ the hook, if $(t,h)=(1,k-1)$, then we abbreviate $\mathcal{V}_{k, \eta, t, h}$ as $(+)-\mathcal{V}_{k, \eta}$.
	\end{definition}

	\begin{definition}\label{D_4}{\rm(\cite{A7})}
		Let $\boldsymbol{\alpha}=\left(\alpha_1, \ldots, \alpha_n\right) \in \mathbb{F}_q^n$ with $\alpha_i \neq \alpha_j(i \neq j)$ and $\boldsymbol{v}=\left(v_1, \ldots, v_n\right) \in$ $\left(\mathbb{F}_q^*\right)^n$. The TGRS code with length $n$ and dimension $k$ is defined as
		$$
		\mathcal{C}_k(\boldsymbol{\alpha}, \boldsymbol{v}, \eta, t, h)=\left\{\left(v_1 f\left(\alpha_1\right), \ldots, v_n f\left(\alpha_n\right)\right) \mid f(x) \in \mathcal{V}_{k, \eta, t, h}\right\} .
		$$
		If $(t,h)=(1,k-1)$, then we abbreviate the TGRS code $\mathcal{C}_k(\boldsymbol{\alpha}, \boldsymbol{v}, \eta, t, h)$ as $(+)-\mathcal{C}_k(\boldsymbol{\alpha}, \boldsymbol{v}, \eta)$.

	\end{definition}

	\begin{lemma}{\rm(\cite{A9}, Lemma 2.6)}\label{L_29}
		For $\eta \in \mathbb{F}_q^*$, $\boldsymbol{\alpha}=\left(\alpha_1, \ldots, \alpha_n\right) \in \mathbb{F}_q^n$ with $\alpha_i \neq \alpha_j(i \neq j)$ and $\boldsymbol{v}=\left(v_1, \ldots, v_n\right) \in$ $\left(\mathbb{F}_q^*\right)^n$. Let
		$$S_{k,+}\left ( \alpha \right )=\left \{ \sum_{i\in I}\alpha _{i}\mid \forall I\subsetneq [n]~and ~\left | I \right |=k \right \},$$
		then we have

		$(1)$ $(+)-\mathcal{C}_k(\boldsymbol{\alpha}, \boldsymbol{v}, \eta)$ is MDS if and only if $-\eta ^{-1}\in \mathbb{F}_{q}^{*}\setminus S_{k,+}\left ( \alpha \right )$;

		$(2)$ $(+)-\mathcal{C}_k(\boldsymbol{\alpha}, \boldsymbol{v}, \eta)$ is NMDS if and only if $-\eta ^{-1}\in S_{k,+}\left ( \alpha \right )$.
	\end{lemma}


	\subsection{The Schur product of linear codes}
	For convenience, in this section, we suppose that $\mathcal{A}, \mathcal{B} \subseteq \mathbb{F}_{q^m}^n$ are linear codes.
	\begin{lemma}\label{L_22}{\rm(\cite{A3}, Proposition 2.3)}
		If $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{C}$ are linear codes of length $n$ over $\mathbb{F}_q$ such that $\mathcal{A} * \mathcal{B} \subseteq \mathcal{C}^{\perp}$, $d\left(\mathcal{A}^{\perp} \right)>a>0$ and $d\left(\mathcal{B}^{\perp} \right)>b>0$, then $$d\left(\mathcal{C}\right) \geq a+b.$$
	\end{lemma}

	\begin{proposition}\label{P_2}{\rm({\rm\cite{A23}}, Product Singleton Bound)}
		Let $\mathcal{A}$ and $\mathcal{B}$ be linear codes, then
		$$
		d(\mathcal{A} * \mathcal{B}) \leq \max \{1, n-(k(\mathcal{A})+k(\mathcal{B}))+2\}.
		$$
	\end{proposition}

	Recall that the pair $(\mathcal{A}, \mathcal{B})$ of  $q^m$-linear codes is a Product  MDS (in short, PMDS) pair \cite{A22} if
	$$
	2 \leq d(\mathcal{A} * \mathcal{B})=n-k(\mathcal{A})-k(\mathcal{B})+2.
	$$

	\begin{lemma}\label{L_20}{\rm(\cite{A6}, Proposition 7.3)}
		Let $(\mathcal{A}, \mathcal{B})$ be a PMDS pair of $\mathbb{F}_{q}$-linear codes in $\mathbb{F}_{q}^n$. Futher assume that $$k(\mathcal{A})+k(\mathcal{B})<n,$$ then $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{A*B}$ are MDS codes.
	\end{lemma}

	\begin{lemma}\label{L_21}{\rm(\cite{A6}, Proposition 7.4)}
		Let $(\mathcal{A}, \mathcal{B})$ be a PMDS pair of $\mathbb{F}_{q}$-linear codes in $\mathbb{F}_{q}^n$. Futher assume that $$k(\mathcal{A})+k(\mathcal{B})<n,$$ and $k(\mathcal{A}), k(\mathcal{B}) \geq 2$. Then, $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{A*B}$ are GRS codes with the common evaluation-point sequence.
	\end{lemma}

	%\begin{lemma}\label{L_9}{\rm(\cite{A22}, Corollary 31)}
	%	If the pair $(\mathcal{A}, \mathcal{B})$ is PMDS, then either $\mathcal{A} * \mathcal{B}$ is  MDS  or $d(\mathcal{A} * \mathcal{B})=2$.
%	\end{lemma}

	\begin{proposition}\label{P_3}{\rm(\cite{A22}, Theorem 7)}
		Let $\mathcal{A}$ and $\mathcal{B}$ be full-support codes. If (at least) one of $\mathcal{A}$ and $\mathcal{B}$ is MDS, then
		$$
		k(\mathcal{A} * \mathcal{B}) \geq \min \{n, k(\mathcal{A}) + k(\mathcal{B})-1\} .
		$$
	\end{proposition}

	\begin{remark}\label{R_21}
	If $\mathcal{C}$ is an MDS linear code with minimal distance $d \geq 2$, then $\mathcal{C}$ is a full-support code.
	\end{remark}

	{\bf Proof.} Suppose that $\mathcal{C}=[n,k,n-k+1]$ is an MDS linear code with $d=n-k+1 \geq2$. Note that $n-1 \geq k$, thus for any $I\subseteq [n] $ with $|I|=1$, $C_I$ is also an MDS linear code with parameters $[n-1,k,n-k]$ by Lemma \ref{L_1}.

	If $C$ is not a full-support code, then there exists some $I\subseteq [n]$  with $|I|=1$ and $C_I=[n-1,k,n-k+1]$, which is a contradiction.  $\hfill\Box$\\

	%Especially, the following lemma was given in \cite{A22}.

	\begin{lemma}\label{L_10}{\rm(\cite{A22}, Lemma 8)}
		Let $\mathcal{A}$ and $\mathcal{B}$ be MDS codes with
		$$
		k(\mathcal{A} * \mathcal{B})=k(\mathcal{A}) + k(\mathcal{B})-1,
		$$
		then $\mathcal{A} * \mathcal{B}$ is MDS.
	\end{lemma}


		\section{ The $\ell$-error-correcting pair of the  NMDS linear code with minimal distance $2\ell+1$}
		It is well-known that if an NMDS linear code $\mathcal{C}$ with minimal distance $2\ell+1$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$, then the paramaters of $\mathcal{A}$ have 6 cases given in the following Lemma \ref{L_31}. Firstly, we give an example for that the parameters of $\mathcal{A}$ is the 1st case. Moreover, basing on Product Singleton Bound, we give several necessary conditions for that the parameters of $\mathcal{A}$ is the 4th, 2nd, 5th or 1st case, respectively. 

		%we give  the only possible parameters of $\mathcal{C}$ when $\mathcal{A}$ is the 4th, 2nd or 5th. Finally, we give the possible cases for the parameter of $\mathcal{B}^{\perp}$ and $\mathcal{A*B}$ in the $\ell$-error-correcting pairs when $\mathcal{A}$ is the 1st.

		\begin{lemma}\label{L_31}{\rm(\cite{A31}, Theorem 3.5)}
		Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n}{2}-1$. If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-1, 2 \ell+1]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$, then the parameters of $\mathcal{A}$ are the following $6$ possibilities, 
		\begin{align}
	&(A.1) ~[n, \ell+1, n-\ell]; \qquad \quad \notag 
	&&(A.2) ~[n, \ell+2, n-\ell-1]; \quad \notag 
	&&&(A.3)~ [n, \ell+1, n-\ell-1]; \notag \\
	&(A.4) ~[n, \ell+3, n-\ell-2]; \quad \notag 
	&&(A.5) ~[n, \ell+2, n-\ell-2]; \quad \notag 
	&&&(A.6) ~[n, \ell+1, n-\ell-2].  \notag
		\end{align}
	\end{lemma}

	$\bullet$ For the case $(A.1)$ of Lemma \ref{L_31}, the example is as follows.
	\begin{example}
		Let $q=37$, $\alpha=(0,1,2,\cdots,8,9)\in \mathbb{F}_{37}^{10}$ and $\mathcal{C}$ be the TGRS code over $\mathbb{F}_{37}$ with the generator matix 
		$$G_{\mathcal{C}}= \begin{pmatrix}
			\mathbf{1} \\
			\alpha  \\
			\alpha^2+6\alpha^3
		\end{pmatrix}_{3\times 10},$$
		then we have $k=3$, $\eta=6$ and $S_{3,+}\left ( \alpha  \right ) =\left \{ 3,4,\cdots ,24 \right \}  $, i.e., $-\eta^{-1}=-6^{-1}=6\in S_{3,+}\left ( \alpha  \right )$. Thus $\mathcal{C}$ is an NMDS linear code with parameters $[10, 3, 7]_{37}$ by Lemma \ref{L_29}.

		By taking $\mathcal{A}$ and $\mathcal{B}$ be MDS codes over $\mathbb{F}_{37}$ with the parity check matrix and generator matrix as follows, respectively,
		$$H_{\mathcal{A}}=\begin{pmatrix}
			\mathbf{1} \\
			\alpha  \\
			\alpha^2 \\
			\alpha^3 \\
			\alpha^4 \\
			\alpha^5
