			\mathbf{1} \\
			\alpha \\
			\alpha^2
		\end{pmatrix}_{3\times 10}. $$
		It's easy to show that $(\mathcal{A}, \mathcal{B})$ is a $3$-error-correcting pair for $\mathcal{C}$ and $\mathcal{A}=[10, 4, 7]_{37}.$ 
	\end{example}


