		The following theorem demonstrates that the case $(A.4)$ of Lemma \ref{L_31} can not be satisfied when $2 \leq \ell <\frac{n-3}{2}$.


		%(情况A.4)
		\begin{theorem}
			Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n}{2}-1$. If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-1, 2 \ell+1]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with $\mathcal{A}=[n, \ell+3, n-\ell-2]_{q^m}$, then $n$ is odd and  
			$\mathcal{C}=[n, 2, n-2]$.
		\end{theorem}

		{\bf Proof.}  Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n-3}{2}$. %If $\mathcal{C}$ is an $[n, n-2 \ell-$ $1, 2 \ell+1]$ code over $\mathbb{F}_q$ and $\mathcal{C}$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ over $\mathbb{F}_{q^m}$ with $\mathcal{A}=[n, \ell+3, n-\ell-2]$. 
		Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+4 >\ell+3>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell-1 > n-2\ell-2>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell+1$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell$. Hence 
		$k(\mathcal{B})= \ell$.

		 Since $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\bot}$ and $\mathcal{C}$ is NMDS, thus $d(\mathcal{A}*\mathcal{B})\geq d(\mathcal{C}^{\bot})=n-2\ell-1 \geq 2$. Note that $d(\mathcal{A}*\mathcal{B})\leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\}=n-2\ell-1 $, therefore we have
		$$2 \leq d(\mathcal{A}*\mathcal{B})=n-2\ell-1 =  n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2,$$ hence 
		$(\mathcal{A}, \mathcal{B})$ is a PMDS pair by Proposition \ref{P_2}.
		 %Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\bot}$ and $\mathcal{C}$ is NMDS, so $d(\mathcal{C}^{\bot})=n-2\ell-1$. Therefore we have$$d(\mathcal{A}*\mathcal{B})\geq d(\mathcal{C}^{\bot})=n-2\ell-1 = max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$ since $\ell < \frac{n-3}{2}$, hence $(\mathcal{A}, \mathcal{B})$ is a PMDS pair by Proposition \ref{P_2}.

		Note that $2\leq \ell < \frac{n-3}{2}$, thus $k(\mathcal{A})+k(\mathcal{B})=2\ell+3<n$, i.e., $\mathcal{A}*\mathcal{B}$ is an MDS linear code with minimal distance $n-2\ell-1$ by Lemma \ref{L_20}.
		%$\bullet$ Note that $k(\mathcal{A}), k(\mathcal{B})\geq 2$, we conclude that $\mathcal{A}, \mathcal{B}$ and $\mathcal{A*B}$ are GRS codes with a common evaluation-point sequence by Lemma \ref{L_21}. 
		Hence $$k(\mathcal{A}*\mathcal{B})=2\ell+2>2\ell+1=k(\mathcal{C}^{\perp}),$$ which contradicts with $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$.

		From the above, $\ell=\frac{n-3}{2}$, i.e., the parameters of $\mathcal{C}$ is $[n, 2, n-2]$. Furthermore, note that $d(\mathcal{C})=2 \ell+1$ is odd, thus $n$ is odd.
		$\hfill\Box$\\

		The following theorem demonstrates that the case ($A.2)$ of Lemma \ref{L_31} also can not be satisfied when $2 \leq \ell <\frac{n-3}{2}$.

		%(情况A.2)
		\begin{theorem}
		Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n}{2}-1$. If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-1, 2 \ell+1]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with $\mathcal{A}=[n, \ell+2, n-\ell-1]_{q^m}$, then $n$ is odd and $\mathcal{C}=[n, 2, n-2]$.
		\end{theorem}

		{\bf Proof.} 	Let $\ell \in \mathbb{Z}^{+}$ with $2 \leq \ell<\frac{n-3}{2}$. Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$. Now by Proposition \ref{P_2}, we have
		$$ 2 < n-2\ell-1=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$
		note that $k(\mathcal{A})=\ell+2$, thus 
		\begin{equation}\label{eqn_31}
			n-2\ell-1 \leq d(\mathcal{A}*\mathcal{B}) \leq
			 max \left\{1, n-\ell-k(\mathcal{B}) \right\}.
		\end{equation}

		Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+3 >\ell+2>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell-1 > n-2\ell-2>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell+1$. Hence
		$$ \ell \leq k(\mathcal{B}) \leq \ell+1.$$
		Namely, $k(\mathcal{B})= \ell+1$ or $\ell$.

		{\bf Case I.} If $ k(\mathcal{B})=\ell+1$, then $ d(\mathcal{A}*\mathcal{B})=n-2\ell-1=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2>2 $ from (\ref{eqn_31}). By Proposition \ref{P_2}, $(\mathcal{A}, \mathcal{B})$ is a PMDS pair, moreover, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with dimension $2\ell +2$ by Lemma \ref{L_20}. Hence $$k(\mathcal{A}*\mathcal{B})=2\ell+2>2\ell+1=k(\mathcal{C}^{\perp}),$$ which contradicts with $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$.

		{\bf Case II.} If $ k(\mathcal{B})=\ell $, then $n-2\ell-1 \leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_31}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell$ or $n-2\ell-1$. Moreover, $\mathcal{B}^{\perp}=[n,n- \ell,\ell+1]$ and so $\mathcal{B}$ is a full-support code by Remark \ref{R_21}.

		 For $d(\mathcal{A}*\mathcal{B})=n-2\ell$, we know that $\mathcal{A}*\mathcal{B}$ is a PMDS pair by Proposition \ref{P_2}. Moreover, $\mathcal{A}*\mathcal{B}$ is an MDS linear code by Lemma \ref{L_20}, i.e., $k(\mathcal{A}*\mathcal{B})=2\ell+1=k(\mathcal{C}^{\perp})$, note that $\mathcal{A}*\mathcal{B} \subseteq \mathcal{C}^{\perp}$, thus 
		$$\mathcal{A}*\mathcal{B} = \mathcal{C}^{\perp}=[n, 2\ell+1, n-2\ell-1],$$ 
		which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell$. 	

		 For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, since $\mathcal{A}$ and $\mathcal{B}$ are both full-support codes, by Proposition \ref{P_3} we have $ k(\mathcal{A}*\mathcal{B}) \geq 2\ell+1$. Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, thus $k(\mathcal{A*B}) \leq 2\ell+1$, hence we have $$k(\mathcal{A*B})=2\ell+1=k(\mathcal{A})+k(\mathcal{B})-1,$$ which means that $\mathcal{A*B}$ is an MDS linear code by Lemma \ref{L_10}, i.e., $d(\mathcal{A*B})=n-2\ell$, which contradicts with $k(\mathcal{A}*\mathcal{B})=n-2\ell-1$.

		From the above, $\ell=\frac{n-3}{2}$, i.e., the parameters of $\mathcal{C}$ is $[n, 2, n-2]$. Furthermore, note that $d(\mathcal{C})=2 \ell+1$ is odd, thus $n$ is odd.	$\hfill\Box$\\

		%\begin{remark}
		%In Theorem 3.2, if $\mathcal{A}=[n, \ell+2, n-\ell-2]_{q^m}$, then from $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$, we have$$ 2 \leq n-2\ell-1=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}),$$  moreover, by Proposition \ref{P_2}, we can get$$d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\}.$$From the above, we know that $n-2\ell-1 \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\}$, i.e., $$n-2\ell-1 \leq n-\ell-k(\mathcal{B}),$$which means that $k(\mathcal{B})\leq \ell+1$. Note that $k(\mathcal{B}) \geq \ell$, hence $k(\mathcal{B})= \ell+1$ or $\ell$.\end{remark}


