		\begin{theorem}
			Let $\ell \in \mathbb{Z}^{+}$ with $2 \leq \ell<\frac{n-3}{2}$.
			If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-1, 2 \ell+1]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with
			 %and the NMDS linear code $\mathcal{C}=[n, n-2 \ell-$ $1, 2 \ell+1]_q$. If $\mathcal{C}$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ over $\mathbb{F}_{q^m}$ with 
			 $\mathcal{A}=[n, \ell+1, n-\ell]_{q^m}$, then the parameters of both $\mathcal{B}^{\perp}$ and $\mathcal{A}*\mathcal{B}$ are three possibilities as follows,

			$(1)$ $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1]$;

			$(2)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A}*\mathcal{B}=[n,2\ell,n-2\ell+1]$;

			$(3)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}$.
		\end{theorem}

		{\bf Proof.} Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$. Now by Proposition \ref{P_2}, we have
		$$ 2 < n-2\ell-1=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$
		note that $k(\mathcal{A})=\ell+1$, thus 
		\begin{equation}\label{eqn_32}
			n-2\ell-1 \leq d(\mathcal{A}*\mathcal{B}) \leq
			max \left\{1, n-\ell+1-k(\mathcal{B} )\right\}.
		\end{equation}

		Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so  $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+2 >\ell+1>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell-1 > n-2\ell-2>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell-1$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell+2$. Hence
		$$ \ell \leq k(\mathcal{B}) \leq \ell+2.$$
		Namely, $k(\mathcal{B})= \ell+2$ or $\ell+1$ or $\ell$.

		{\bf Case I.} If $ k(\mathcal{B})=\ell+2$, then $ d(\mathcal{A}*\mathcal{B})=n-2\ell-1=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 >2$ from (\ref{eqn_32}). By Proposition \ref{P_2}, $(\mathcal{A}, \mathcal{B})$ is a PMDS pair, moreover, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with dimension $2\ell +2$ by Lemma \ref{L_20}. Hence $$k(\mathcal{A}*\mathcal{B})=2\ell+2>2\ell+1=k(\mathcal{C}^{\perp}),$$ which contradicts with $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$.

		{\bf Case II.} If $ k(\mathcal{B})=\ell+1 $, then $n-2\ell-1\leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_32}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell$ or $n-2\ell-1$. Moreover, it is easy to know that $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+2]$ or $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1]$. 

		For $d(\mathcal{A}*\mathcal{B})=n-2\ell$, by Proposition \ref{P_2} and Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an MDS linear code, i.e., $\mathcal{A*B}=[n, 2\ell+1, n-2\ell]$, hence $k(\mathcal{A*B})=2\ell+1=k(\mathcal{C}^{\perp})$, we have
		$$\mathcal{A*B}=\mathcal{C}^{\perp}=[n, 2\ell+1, n-2\ell-1],$$
		which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell$. 

		For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, if $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+2]$, then $\mathcal{B}$ is a full-support code by Remark \ref{R_21}, now
		 by Proposition \ref{P_3} we have $ k(\mathcal{A}*\mathcal{B}) \geq 2\ell+1$. Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, thus $k(\mathcal{A*B}) \leq 2\ell+1$, hence we have $$k(\mathcal{A*B})=2\ell+1=k(\mathcal{A})+k(\mathcal{B})-1,$$ 
		which means that 
		$\mathcal{A}*\mathcal{B}$ is an MDS linear code from Lemma \ref{L_10}, i.e., $d(\mathcal{A*B})=n-2\ell$, which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$. Hence $\mathcal{B}^{\perp} \ne [n, n-\ell-1, \ell+2]$, i.e.,  $$\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1].$$ 
		Thus we complete the proof of $(1)$.


		{\bf Case III.} If $ k(\mathcal{B})=\ell $, then $n-2\ell-1 \leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell+1=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_32}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell+1$ or $n-2\ell$ or $n-2\ell-1$. Moreover, $\mathcal{B}^{\perp}=[n,n- \ell,\ell+1]$ and so $\mathcal{B}$ is a full-suppport code by Remark \ref{R_21}.

		For $d(\mathcal{A}*\mathcal{B})=n-2\ell+1$, by Proposition \ref{P_2} and  Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with 
		$$\mathcal{A*B}=[n,2\ell,n-2\ell+1] \quad \text{and} \quad \mathcal{B}^{\perp}=[n,n- \ell,\ell+1].$$
		Thus we complete the proof of $(2)$.

		For $d(\mathcal{A}*\mathcal{B})=n-2\ell$, by Proposition \ref{P_3} and $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, we have
		$$ 2\ell \leq k(\mathcal{A}*\mathcal{B}) \leq 2\ell+1,$$
		i.e., $k(\mathcal{A}*\mathcal{B})=2\ell$ or $2\ell+1$. If $k(\mathcal{A}*\mathcal{B})=2\ell=k(\mathcal{A})+k(\mathcal{B})-1$, by Lemma $\ref{L_10}$, we know that $\mathcal{A*B}$ is an MDS linear code with minimal distance $n-2\ell+1$, which contradicts with $d(\mathcal{A*B})=n-2\ell$.
		If $k(\mathcal{A*B})=2\ell+1=k(\mathcal{C}^{\perp})$, then $\mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}=[n, 2\ell+1,n-2\ell-1]$, which contradicts with $d(\mathcal{A*B})=n-2\ell$.

		For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, by  Proposition \ref{P_3} and $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, we have
		$$ 2\ell \leq k(\mathcal{A}*\mathcal{B}) \leq 2\ell+1 .$$
		i.e., $k(\mathcal{A}*\mathcal{B})=2\ell$ or $2\ell+1$. By Lemma $\ref{L_10}$, we know that $k(\mathcal{A}*\mathcal{B})=2\ell+1$, and then we can get
		$$\mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}\quad \text{and} \quad \mathcal{B}^{\perp}=[n, n-\ell, \ell+1].$$
		Thus we complete the proof of $(3)$.
		$\hfill\Box$


