	\section{ The $\ell$-error-correcting pair of the NMDS linear code with minimal distance $2\ell+2$}

		It is well-known that if an NMDS linear code $\mathcal{C}$ with minimal distance $2\ell+2$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$, 
		then the paramaters of $\mathcal{A}$ have 10 cases given in the following Lemma \ref{L_41}. Firstly, we give an example for that the parameters of $\mathcal{A}$ is the 1st or 2nd case, respectively. Moreover, basing on Product Singleton Bound, we give several necessary conditions for that the parameters of $\mathcal{A}$ is the 7th, 4th, 8th or 2nd case, respectively. 

		%Then, based on the product singleton bound, we give the only possible parameters of $\mathcal{C}$ when $\mathcal{A}$ is the 7th, 4th or 8th. Finally, we give the possible cases for the parameter of $\mathcal{B}^{\perp}$ and $\mathcal{A*B}$ in the $\ell$-error-correcting pairs when $\mathcal{A}$ is the 2nd.


			\begin{lemma}\label{L_41}{\rm(\cite{A31}, Theorem 3.7)}
		Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n-3}{2}$. If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-2, 2 \ell+2]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$, then the parameters of $\mathcal{A}$ have the following $10$ possibilities, 
		\begin{align}
			&(D.1)~ [n, \ell+1, n-\ell]; ~~\notag 
			&&(D.2)~ [n, \ell+2, n-\ell-1];~~  \notag 
			&&&(D.3) ~[n, \ell+1, n-\ell-1]; \notag \\
			&(D.4)~ [n, \ell+3, n-\ell-2]; ~~ \notag 
			&&(D.5) ~[n, \ell+2, n-\ell-2];  ~~\notag 
			&&&(D.6)~ [n, \ell+1, n-\ell-2];  \\ \notag
			&(D.7)~ [n, \ell+4, n-\ell-3]; ~~\notag 
			&&(D.8) ~[n, \ell+3, n-\ell-3]; ~~\notag 
			&&&(D.9) ~[n, \ell+2, n-\ell-3];  \\ \notag
			&(D.10)~ [n, \ell+1, n-\ell-3].  \notag
		\end{align}
	\end{lemma}

	$\bullet$ For the cases $(D.1)$-$(D.2)$ of Lemma \ref{L_41}, the corresponding examples are as follows.
	 \begin{example}
	 	Let $q=37$, $\alpha=(0,1,2,\cdots,8,9)\in \mathbb{F}_{37}^{10}$ and $\mathcal{C}$ be the TGRS code over $\mathbb{F}_{37}$ with the generator matix 
	 	$$G_{\mathcal{C}}= \begin{pmatrix}
	 		\mathbf{1} \\
	 		\alpha  \\
	 		\alpha^2 \\
	 		\alpha^3+6\alpha^4
	 	\end{pmatrix}_{4\times 10} ,$$
	 	then we have $k=4$, $\eta=6$ and $S_{4,+}\left ( \alpha  \right ) =\left \{ 6,\cdots,30 \right \}  $, i.e., $-\eta^{-1}=-6^{-1}=6\in S_{4,+}\left ( \alpha  \right )$. Thus $\mathcal{C}$ is an NMDS linear code with parameters $[10, 4, 6]_{37}$ by Lemma \ref{L_29}.

	 	By taking $\mathcal{A}$ and $\mathcal{B}$ be MDS codes over $\mathbb{F}_{37}$ with the parity check matrix and the generator matrix, respectively,
	 	 $$H_{\mathcal{A}}=\begin{pmatrix}
	 		\mathbf{1} \\
	 		\alpha  \\
	 		\alpha^2 \\
	 		\alpha^3 \\
	 		\alpha^4 \\
	 		\alpha^5 \\
	 		\alpha^6
	 	\end{pmatrix}_{7\times 10} ~~~~~~~~\text{and}~~~~~~~~G_{\mathcal{B}}=\begin{pmatrix}
	 	\mathbf{1} \\
	 	\alpha \\
	 	\alpha^2 
	 	\end{pmatrix}_{3\times 10}. $$
	 	It's easy to show that $(\mathcal{A}, \mathcal{B})$ is a $2$-error-correcting pair for $\mathcal{C}$ and $\mathcal{A}=[10, 3, 8]_{37}$, which is an example for the case $(D.1)$ of Lemma \ref{L_41}. 

	 	By taking $\mathcal{A}$ and $\mathcal{B}$ be MDS codes over $\mathbb{F}_{37}$ with the parity check matrix and the generator matrix, respectively,
	 	$$H_{\mathcal{A}}=\begin{pmatrix}
	 		\mathbf{1} \\
	 		\alpha  \\
	 		\alpha^2 \\
	 		\alpha^3 \\
	 		\alpha^4 \\
	 		\alpha^5 
	 	\end{pmatrix}_{6\times 10} ~~~~~~~~\text{and}~~~~~~~~G_{\mathcal{B}}=\begin{pmatrix}
	 		\mathbf{1} \\
	 		\alpha 
	 	\end{pmatrix}_{2\times 10}. $$
	 	It's easy to show that $(\mathcal{A}, \mathcal{B})$ is a $2$-error-correcting pair for $\mathcal{C}$ and $\mathcal{A}=[10, 4, 7]_{37}$, which is an example for the case $(D.2)$ of Lemma \ref{L_41}.  
	 \end{example}


