	The following theorem demonstrates that the case $(D.4)$ of Lemma \ref{L_41} also can not be satisfied when $2 \leq \ell <\frac{n}{2}-2$.

	%(情况D.4)
	\begin{theorem}
		Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n-3}{2}$. If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-2, 2 \ell+2]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with $\mathcal{A}=[n, \ell+3, n-\ell-2]_{q^m}$, then $n$ is even and  
		$\mathcal{C}=[n, 2, n-2]$.
	\end{theorem}

	{\bf Proof.} Let $\ell \in \mathbb{Z}^+$ with $2\leq \ell < \frac{n}{2}-2$. 
	From $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$ and Proposition \ref{P_2}, we have
	$$ 2 < n-2\ell-2=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$
	note that $k(\mathcal{A})=\ell+3$, thus 
	\begin{equation}\label{eqn_41}
		n-2\ell-2 \leq d(\mathcal{A}*\mathcal{B}) \leq
		max \left\{1, n-\ell-1-k(\mathcal{B}) \right\}.
	\end{equation}

	Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+4 >\ell+3>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell-2 > n-2\ell-3>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell+1$. Hence 
	$$ \ell \leq k(\mathcal{B}) \leq \ell+1.$$
	Namely, $k(\mathcal{B})= \ell+1$ or $\ell$.


	{\bf Case I.} If $ k(\mathcal{B})=\ell+1$, then $ d(\mathcal{A}*\mathcal{B})=n-2\ell-2=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 >2 $ from (\ref{eqn_41}). By Proposition \ref{P_2}, $(\mathcal{A}, \mathcal{B})$ is a PMDS pair, moreover, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with dimension $2\ell +3$ by Lemma \ref{L_20}. Hence $$k(\mathcal{A}*\mathcal{B})=2\ell+3>2\ell+2=k(\mathcal{C}^{\perp}),$$ which contradicts with $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$.

	{\bf Case II.} If $ k(\mathcal{B})=\ell $, then $n-2\ell-2 \leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell-1=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_41}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$ or $n-2\ell-2$. Moreover, $\mathcal{B}^{\perp}=[n,n- \ell,\ell+1]$ and so $\mathcal{B}$ is a full-support code by Remark \ref{R_21}.

	For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, by Proposition \ref{P_2} we know that $\mathcal{A}*\mathcal{B}$ is a PMDS pair. Moreover, by Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an linear MDS code, i.e., $k(\mathcal{A}*\mathcal{B})=2\ell+2=k(\mathcal{C}^{\perp})$, note that $\mathcal{A}*\mathcal{B} \subseteq \mathcal{C}^{\perp}$, thus 
	$$\mathcal{A}*\mathcal{B} = \mathcal{C}^{\perp}=[n, 2\ell+2, n-2\ell-2],$$ 
	which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$. 

	For $d(\mathcal{A}*\mathcal{B})=n-2\ell-2$, since $\mathcal{A}$ and $\mathcal{B}$ are both full-support codes, by Proposition \ref{P_3} we have $ k(\mathcal{A}*\mathcal{B}) \geq 2\ell+2$. Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, thus $k(\mathcal{A*B}) \leq 2\ell+2$, hence we have $$k(\mathcal{A*B})=2\ell+2=k(\mathcal{A})+k(\mathcal{B})-1,$$ which means that $\mathcal{A*B}$ is an MDS linear code by Lemma \ref{L_10}, i.e., $d(\mathcal{A*B})=n-2\ell-1$, which contradicts with $k(\mathcal{A}*\mathcal{B})=n-2\ell-2$.

	From the above, $\ell=\frac{n}{2}-2$, i.e., the parameters of $\mathcal{C}$ is $[n, 2, n-2]$. Futhermore, note that $d(\mathcal{C})=2\ell+2$ is even, thus $n$ is even.  $\hfill\Box$\\

	%\begin{remark}
		%In Theorem 4.2, if $\mathcal{A}=[n, \ell+3, n-\ell-3]_{q^m}$, from $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$, we have$$ 2 < n-2\ell-2=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}),$$  moreover, by Proposition \ref{P_2}, we can get$$d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\}.$$From the above, we know that $n-2\ell-2 \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\}$, i.e., $$n-2\ell-2 \leq n-\ell-1-k(\mathcal{B}),$$which means that $k(\mathcal{B})\leq \ell+1$. Note that $k(\mathcal{B}) \geq \ell$, hence, $k(\mathcal{B})= \ell+1$ or $\ell$.\end{remark}

		In the same proof as that of Theorem $4.2$,
		we can get the following corollary, which means that for the case $(D.8)$ of Lemma \ref{L_41}, if $\mathcal{A}$ is a full-support code, then the parameters of both $\mathcal{A*B}$ and $\mathcal{B}^{\perp}$ are determined when $2 \leq \ell <\frac{n}{2}-2$.

		%The following corollary shows that the case $(D.8)$ in Lemma \ref{L_41}, if $\mathcal{A}$ is a full-support code, by Remark 4.1 and the proof of Theorem 4.2, we also prove that there is only one case for the parameters of $\mathcal{A*B}$ and $\mathcal{B}^{\perp}$ when $2 \leq \ell <\frac{n}{2}-2$.

	\begin{corollary}
			Let $\ell \in \mathbb{Z}^{+}$ with $2 \leq \ell<\frac{n}{2}-2$.
		If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-2, 2 \ell+2]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with
		%Suppose that the NMDS linear code $\mathcal{C}=[n, n-2 \ell-$ $1, 2 \ell+1]_q$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ over $\mathbb{F}_{q^m}$ with
		$\mathcal{A}=[n, \ell+3, n-\ell-3]_{q^m}$ a full-support code, then the parameters of both $\mathcal{B}^{\perp}$ and $\mathcal{A}*\mathcal{B}$ are two possibilities as follows,

		$(1)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A*B}=\mathcal{C}^{\perp}$;

		$(2)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A*B}=[n,2\ell+2,n-2\ell-2]$.

	\end{corollary}

		Now, for the case $(D.2)$ of Lemma \ref{L_41}, the following theorem demonstrates that there are 3 cases for the parameters of both $\mathcal{B}^{\perp}$ and $\mathcal{A*B}$ when $2 \leq \ell<\frac{n}{2}-2$. 

	%(情况D.2)
	\begin{theorem}
		Let $\ell \in \mathbb{Z}^{+}$ with $2 \leq \ell<\frac{n}{2}-2$.
		If the q-ary NMDS linear code $\mathcal{C}=[n, n-2 \ell-2, 2 \ell+2]$ has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ with
		$\mathcal{A}=[n, \ell+2, n-\ell-1]_{q^m}$, then the parameters of both $\mathcal{B}^{\perp}$ and $\mathcal{A}*\mathcal{B}$ are three possibilities as follows,

		$(1)$ $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1]$;

		$(2)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A}*\mathcal{B}=[n,2\ell+1,n-2\ell]$;

		$(3)$ $\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad and \quad \mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}$.
	\end{theorem}

	{\bf Proof.} 
	From $\mathcal{A}* \mathcal{B} \subseteq \mathcal{C}^{\perp}$ and Proposition \ref{P_2}, we have
	$$ 2 < n-2\ell-2=d(\mathcal{C}^{\perp}) \leq d(\mathcal{A}*\mathcal{B}) \leq max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$
	note that $k(\mathcal{A})=\ell+2$, thus 
	\begin{equation}\label{eqn_42}
		n-2\ell-2 \leq d(\mathcal{A}*\mathcal{B}) \leq
		max \left\{1, n-\ell-k(\mathcal{B}) \right\}.
	\end{equation}

	Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+3 >\ell+2>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell-2 > n-2\ell-3>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell-1$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell+2$. Hence 
	$$ \ell \leq k(\mathcal{B}) \leq \ell+2.$$
	Namely, $k(\mathcal{B})= \ell+2$ or $\ell+1$ or $\ell$.


	{\bf Case I.} If $ k(\mathcal{B})=\ell+2$, then $ d(\mathcal{A}*\mathcal{B})=n-2\ell-2=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 >2$ from (\ref{eqn_42}). By Proposition \ref{P_2} and Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with dimension $2\ell +3$. Hence $$k(\mathcal{A}*\mathcal{B})=2\ell+3>2\ell+2=k(\mathcal{C}^{\perp}),$$ which contradicts with $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$.

	{\bf Case II.} If $ k(\mathcal{B})=\ell+1 $, then $n-2\ell-2 \leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell-1=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_42}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$ or $n-2\ell-2$. Moreover, it is easy to know that $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1]$ or $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+2]$.

	For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, by Proposition \ref{P_2} and Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an MDS linear code, i.e., $\mathcal{A*B}=[n, 2\ell+2, n-2\ell-1]$, hence $k(\mathcal{A*B})=2\ell+2=k(\mathcal{C}^{\perp})$, we have
	$$\mathcal{A*B}=\mathcal{C}^{\perp}=[n, 2\ell+2, n-2\ell-2],$$
	which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$. 

	For $d(\mathcal{A}*\mathcal{B})=n-2\ell-2$, if $\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+2]$, then $\mathcal{B}$ is a full-support code by Remark \ref{R_21},  now from Proposition \ref{P_3} we have $ k(\mathcal{A}*\mathcal{B}) \geq 2\ell+2$. Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, thus $k(\mathcal{A*B}) \leq 2\ell+2$, hence we have $$k(\mathcal{A*B})=2\ell+2=k(\mathcal{A})+k(\mathcal{B})-1,$$ 
	which means that 
	$\mathcal{A}*\mathcal{B}$ is an MDS linear code from Lemma \ref{L_10}, i.e., $d(\mathcal{A*B})=n-2\ell-1$, which contradicts with $d(\mathcal{A}*\mathcal{B})=n-2\ell-2$. Hence $\mathcal{B}^{\perp} \ne [n, n-\ell-1, \ell+2]$, i.e.,  $$\mathcal{B}^{\perp}=[n, n-\ell-1, \ell+1].$$ 
	Thus we complete the proof of $(1)$.

	{\bf Case III.} If $ k(\mathcal{B})=\ell $, then $n-2\ell-2 \leq d(\mathcal{A}*\mathcal{B}) \leq n-2\ell=n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 $ from (\ref{eqn_42}), i.e., $d(\mathcal{A}*\mathcal{B})=n-2\ell$ or $n-2\ell-1$ or $n-2\ell-2$. Moreover, $\mathcal{B}^{\perp}=[n,n- \ell,\ell+1]$ and so $\mathcal{B}$ is a full-support code by Remark \ref{R_21}. 

	 For $d(\mathcal{A}*\mathcal{B})=n-2\ell$, by Proposition \ref{P_2} and Lemma \ref{L_20}, $\mathcal{A}*\mathcal{B}$ is an MDS linear code with $$\mathcal{A*B}=[n,2\ell+1,n-2\ell] \quad \text{and} \quad \mathcal{B}^{\perp}=[n,n- \ell,\ell+1].$$
	Thus we complete the proof of $(2)$.

	 For $d(\mathcal{A}*\mathcal{B})=n-2\ell-1$, by Proposition \ref{P_3} and $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, we have
	$$ 2\ell+1 \leq k(\mathcal{A}*\mathcal{B}) \leq 2\ell+2 .$$
	i.e., $k(\mathcal{A}*\mathcal{B})=2\ell+1$ or $2\ell+2$.  
	 If $k(\mathcal{A}*\mathcal{B})=2\ell+1=k(\mathcal{A})+k(\mathcal{B})-1$, by Lemma $\ref{L_10}$, we know that $\mathcal{A*B}$ is an MDS linear code with minimal distance $n-2\ell$, which contradicts with $d(\mathcal{A*B})=n-2\ell-1$.
	If $k(\mathcal{A*B})=2\ell+2=k(\mathcal{C}^{\perp})$, then $\mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}=[n, 2\ell+2,n-2\ell-2]$, which contradicts with $d(\mathcal{A*B})=n-2\ell-1$.

	 For $d(\mathcal{A}*\mathcal{B})=n-2\ell-2$, by  Proposition \ref{P_3} and $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\perp}$, we have
	$$ 2\ell+1 \leq k(\mathcal{A}*\mathcal{B}) \leq 2\ell+2.$$
	i.e., $k(\mathcal{A}*\mathcal{B})=2\ell+1$ or $2\ell+2$. By Lemma $\ref{L_10}$, we know that $k(\mathcal{A}*\mathcal{B})=2\ell+2$, and so
	$$\mathcal{B}^{\perp}=[n, n-\ell, \ell+1] \quad \text{and} \quad \mathcal{A}*\mathcal{B}=\mathcal{C}^{\perp}.$$
	Thus we complete the proof of $(3)$.
	$\hfill\Box$


