	\section{ A brief proof for Lemmas $\ref{P_22}$-$\ref{P_23}$}
	In this section, we provide a brief proof for Lemmas $\ref{P_22}$-$\ref{P_23}$, which means that if an MDS linear code $\mathcal{C}$ with minimal distance $2\ell+2$ has an $\ell$-error-correcting pair $(\mathcal{A},\mathcal{B})$ and the parameters of $\mathcal{A}$ is the 1st or the 2nd case in Lemma \ref{P_1}, then $\mathcal{C}$ is a GRS code.

	%For convenience, we denote 
	%$${\bf AI.}~ \mathcal{A}=[n,\ell+2,n-\ell-1]~~~~~~ {\bf AII.} ~\mathcal{A}=[n,\ell+1,n-\ell] ~\text{and}~ d(\mathcal{B}^{\perp}) > \ell+1. $$

	\begin{theorem}
		Let $\ell \in \mathbb{Z}^{+}$ with $2\leq\ell<\frac{n}{2}-1$. If  $\mathcal{C}$ is an $[n, n-2 \ell-$ $1, 2 \ell+2]$ MDS linear code over $\mathbb{F}_{q}$ and $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$ over $\mathbb{F}_{q^m}$, where $${\bf I.}~\mathcal{A}=[n, \ell+2, n-\ell-1]_{q^m}~~\text{or}~~ {\bf II.}~\mathcal{A}=[n, \ell+1, n-\ell]_{q^m}~\text{with}~ d(\mathcal{B}^{\perp}) > \ell+1,$$ then we have

		$(1)$ $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{C}$ are both GRS codes with the same evaluation-point sequence;

		 $(2)$ $\mathcal{B}=(\mathcal{A} * \mathcal{C})^{\perp}$.
	\end{theorem}

	{\bf Proof.} %Let $\mathcal{C}$ be a $[n, n-2 \ell-1, 2\ell+2]_q$ code over $\mathbb{F}_q$ that has an $\ell$-error-correcting pair $(\mathcal{A}, \mathcal{B})$ over $\mathbb{F}_{q^m}$. 
	Firstly, we focus on the parameters of $\mathcal{B}$.

	For {\bf I.} Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus $d\left(\mathcal{B}^{\perp}\right) \geq \ell+1$ and so $k(\mathcal{B}) \geq \ell \geq 2$. On the other hand, since $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$,  $d\left(\mathcal{A}^{\perp}\right) =\ell+3 >\ell+2>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell > n-2\ell-1>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell+1$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell$. Hence
	$k(\mathcal{B})=\ell$.

	For {\bf II.} From $d(\mathcal{B}^{\perp}) > \ell+1$, we have $k(\mathcal{B}) \geq \ell+1$. Since $(\mathcal{A}, \mathcal{B})$ is an $\ell$-error-correcting pair for $\mathcal{C}$, thus  $\mathcal{A}* \mathcal{C} \subseteq \mathcal{B}^{\perp}$. Note that $d\left(\mathcal{A}^{\perp}\right) =\ell+2 >\ell+1>0$ and $d\left(\mathcal{C}^{\perp}\right) =n-2\ell > n-2\ell-1>0$, thus $d\left(\mathcal{B} \right) \geq n-\ell$ by Lemma \ref{L_22}, i.e., $k(\mathcal{B}) \leq \ell+1$. Hence
	$k(\mathcal{B})=\ell+1$.

	From the above, we have $k(\mathcal{A})+k(\mathcal{B})=2\ell+2$ for both cases {\bf I}-{\bf II}. 

	Note that $\mathcal{A}*\mathcal{B}\subseteq \mathcal{C}^{\bot}$ and $d(\mathcal{C}^{\bot})=n-2\ell$. Therefore for both cases we have
	$$d(\mathcal{A}*\mathcal{B})\geq d(\mathcal{C}^{\bot})=n-2\ell= max \left\{1, n-\left(k(\mathcal{A})+k(\mathcal{B})\right)+2 \right\},$$
	since $2\leq\ell<\frac{n}{2}-1$, hence 
	$(\mathcal{A}, \mathcal{B})$ is a PMDS pair by Proposition \ref{P_2}. Moreover, we also have $$k(\mathcal{A})+k(\mathcal{B})=2\ell+2<n,$$ thus $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{A}*\mathcal{B}$ are both MDS linear codes by Lemma \ref{L_20}.

	Now we prove (1).

	(1) In fact, from $k(\mathcal{A})$, $k(\mathcal{B})\geq 2$ for both cases, we know that $\mathcal{A}$, $\mathcal{B}$ and $\mathcal{A*B}$ are GRS codes with the same evaluation-point sequence by Lemma \ref{L_21}, moreover, $$k(\mathcal{A*B})=k(\mathcal{A})+k(\mathcal{B})-1=2\ell+1=k(\mathcal{C}^{\bot}).$$
	Thus $\mathcal{C}^{\bot}=\mathcal{A*B}$ is a GRS code, i.e., $\mathcal{C}$ is also a GRS code with the same evaluation-point sequence as that of $\mathcal{A*B}$, $\mathcal{A}$ and $\mathcal{B}$. 

	Next, we prove (2).

	(2) Since $\mathcal{A}$ and $\mathcal{C}$ are both GRS codes with the same evaluation-point sequence, thus we have $$k(\mathcal{B}^{\bot})=\left\{\begin{matrix}
		n-\ell=k(\mathcal{A})+k(\mathcal{C})-1=k(\mathcal A*\mathcal C), ~~~~~~~~\text{for {\bf I}},  \\
		n-\ell-1=k(\mathcal{A})+k(\mathcal{C})-1=k(\mathcal A*\mathcal C),~~~~ \text{\text{for {\bf II}}},
	\end{matrix}\right.$$ 
	note that $\mathcal{A*C} \subseteq \mathcal{B}^{\bot}$, thus $(\mathcal B)^{\bot}=\mathcal A*\mathcal{C}$, i.e., $\mathcal{B}=(\mathcal{A} * \mathcal{C})^{\perp}$. 

	From the above, we complete the proof.$\hfill\Box$

	\begin{remark}
		Compared with the proofs of Lemmas $\ref{P_22}$-$\ref{P_23}$, the proof of Theorem 5.1 does not use the condition $$q^m>\max \left\{\left(\begin{array}{l}n \\ i\end{array}\right) \mid 1 \leq i \leq \ell\right\},$$ so the condition $q^m>\max \left\{\left(\begin{array}{l}n \\ i\end{array}\right) \mid 1 \leq i \leq \ell\right\}$ in Lemmas $\ref{P_22}$-$\ref{P_23}$ can be deleted.
	\end{remark}

