\subsubsection*{Preliminaries}Given a vector \(v \in \mathbb{R}^n\), \(v^\top\) represents its transpose and \(v_i\) denotes its \(i\)-th entry. Given a matrix \(M \in \mathbb{R}^{n\times n}\), its entry in position \((i,j)\) is denoted as \(m_{ij}\) and its $i$-th row is denoted as $M_i$. The diagonal of a square matrix $M$ is denoted as \(\text{diag}(M)\), the identity function as \(\text{id}(\cdot)\), and the set-interior function as \(\mathcal{INT}(\cdot)\). Also, we denote the \(n \times n\) identity matrix as \(I_n\). The limit superior is expressed as $\overline{\lim}$ \cite{jiang2001input}. The sequence  $\{u(k), \dots, u(k+N)\}$ is denoted as $u([k:k+N])$. %The Minkowski set addition is defined as \(\mathbb X\oplus \mathbb Y=\{x+y\ |\ x\in\mathbb X,\ y\in\mathbb Y\}\), and the Pontryagin set difference as \(\mathbb X \ominus \mathbb Y=\{x\in\mathbb X\ |\ x+z\in\mathbb X,\ \forall z\in\mathbb Y\}\).
Let $\R_{\geq 0}$ (resp., $\mathbb Z_{\geq 0}$) be the set of positive real (resp., positive integer) numbers including $0$ and $\R_{+}\coloneqq\R_{\geq 0}\backslash \{0\}$. Given a set $\mathcal{X}$, the notation $\mathcal{X}^n$ represents the cartesian product of $\mathcal X$ taken $n$ times.
Moreover, denote the set of positive definite real matrices as $\mathbb{S}_+^n \coloneqq \{ M \in \mathbb{R}^{n \times n} \ : M=M^\top\succ 0 \}$, and the set of diagonal positive definite real matrices as
$\mathbb{D}_+^n \coloneqq \{ M \in \mathbb{R}^{n \times n} \ : \ M \succ 0 \ \wedge \ m_{ij} = 0 \ \forall i, j \in \{1, \dots, n\}, \ i \neq j \}$.
Given a square matrix $Q\in\mathbb S_+^n$, denote as $\mathcal{E}(Q)$ the ellipsoidal set $\mathcal{E}(Q)=\{v\in\R^n:v^\top Qv\leq1\}$.
Moreover, \(\mathcal{B}_{\epsilon}^{(n)}(0)\) denotes a ball of radius \(\epsilon\), centered at \(0\), in \(\mathbb{R}^n\).
A continuous function $\alpha:\R_{\geq0}\to\R_{\geq0}$ is a class $\mathcal K$-function if $\alpha(s)>0$ for all $s>0$, it is strictly increasing and $\alpha(0)=0$. Also, a continuous function $\alpha:\R_{\geq0}\to\R_{\geq0}$ is a class $\mathcal K_\infty$-function if it is a class $\mathcal K$-function and $\alpha(s)\to\infty$ as $s\to\infty$. Finally, a continuous function $\beta:\R_{\geq0}\times\mathbb Z_{\geq0}\to\R_{\geq0}$ is a class $\mathcal{KL}$-function if $\beta(s,k)$ is a class $\mathcal K$-function with respect to $s$ for all $k$, it is strictly decreasing in $k$ for all $s>0$, and $\beta(s,k)\to0$ as $k\to\infty$ for all $s>0$. The pair $(A, B)$, where $A\in\R^{n\times n}$ and $B\in\R^{n\times m}$, is said to be stabilizable if there exists a matrix $K\in\R^{n\times m}$ such that $A + BK$ is stable, i.e., all its roots are inside the unit circle on the complex plane \cite{glad2018control}. Similarly, the pair $(A, C)$, where $C\in\R^{p\times n}$,  is said to be detectable if there exists a matrix $L\in\R^{p\times n}$ such that $A - LC$ is stable \cite{glad2018control}. \smallskip\\
%
%
Consider a generic nonlinear discrete-time system described by
\begin{equation}\label{eq:nonlinear_sys}
\begin{cases}
    x(k+1)=f(x(k),w(k))\\
    y(k)=g({x}(k),\eta(k)).
\end{cases}
\end{equation}
where $k\in\mathbb Z_{\geq0}$ is the discrete-time index, $x\in\R^n$ is the state, $w\in\R^m$ is a perturbation acting on the system, $\eta\in \mathcal{N}\subseteq \mathbb{R}^p$ is the measurement noise, function  $f:\R^n\times\R^m\to\R^n$, and $g:\R^n\times\R^m\to\R^p$.

\begin{definition}[$\delta$ISS, \cite{bayer2013discrete}]\label{def:delta_ISS}
    System \eqref{eq:nonlinear_sys} is said to be $\delta$ISS with respect to the sets $\mathcal{X}\subseteq\R^n$ and $\mathcal{W}\subseteq\R^m$ if there exist functions $\beta\in\mathcal{KL}$ and $\gamma\in\mathcal{K_\infty}$ such that for any $k\in\mathbb{Z}_{\geq0}$, any pair of initial states $x_a(0)\in\mathcal{X}$,  $x_b(0)\in\mathcal{X}$ and any pair of input $w_a\in\mathcal{W}$ and $w_b\in\mathcal{W}$, it holds that% and any pair of input sequence $w_a([0:k])\in\mathcal{W}_{[0:k]}$ and $w_b([0:k])\in\mathcal{W}_{[0:k]}$, it holds that
    \begin{multline*}
    \norm{x_a(k)-x_b(k)}\leq\beta(\norm{x_a(0)-x_b(0)},k)\\        +\gamma(\max_{h\geq 0}\norm{w_a(h)-w_b(h)}).
    \end{multline*}\hfill{}$\square$
\end{definition}
The $\delta$ISS property is a fundamental stability property, which can be guaranteed provided that a suitable $\delta$ISS Lyapunov function exists, as stated in the following.
\begin{definition}[Dissipation-form $\delta$ISS Lyapunov function, \cite{bayer2013discrete}]
A function $V(x_a,x_b)$ is a dissipation-form $\delta$ISS Lyapunov function for system \eqref{eq:nonlinear_sys} if there exist $\mathcal{K_\infty}$-functions $\alpha_1$, $\alpha_2$ and $\alpha_3$, and a $\mathcal{K}$-function $\alpha_4$ such that, for any pair of states $x_a(k)\in\mathcal{X}$ and $x_b(k)\in\mathcal{X}$, and any pair of inputs $w_a(k)\in\mathcal{W}$ and $w_b(k)\in\mathcal{W}$, it holds that
    \begin{equation*}
       \alpha_1(\norm{x_a(k)-x_b(k)})\!\leq\! V(x_a(k),x_b(k))\!\leq\!\alpha_2(\norm{x_a(k)-x_b(k)}),
    \end{equation*}
    \begin{multline*}
    V(x_a(k+1),x_b(k+1))-V(x_a(k),x_b(k))\\\leq -\alpha_3(\norm{x_a(k)-x_b(k)})+\alpha_4(\norm{w_a(k)-w_b(k)}).
    \end{multline*}\hfill{}$\square$
\end{definition}
\begin{theorem}[\cite{bayer2013discrete}]\label{th:local_dISS}
   If system \eqref{eq:nonlinear_sys} admits a dissipation-form
    $\delta$ISS Lyapunov function over the sets $\mathcal{X}$ and $\mathcal{W}$, then it is $\delta$ISS with respect to such sets, in the sense specified by Definition \ref{def:delta_ISS}.\hfill{}$\square$
\end{theorem}
