Define the estimation error as $e(k) = x(k)-\hat x(k)$. We introduce the following definition. %
\begin{definition}[$\delta$ISS observer error dynamics]\label{def:delta_ISS_observer}
    Observer \eqref{eq:nonlinear_observer} is said to have $\delta$ISS observer error dynamics with respect to the sets $\mathcal{X}_e\subseteq\R^n$, $\mathcal{W}\subseteq\R^m$ and $\mathcal{N}\subseteq \mathbb{R}^p$ if there exist functions $\beta_o\in\mathcal{KL}$, $\gamma^w_o\in\mathcal{K_\infty}$ and $\gamma^\eta_o\in\mathcal{K_\infty}$ such that for any $k\in\mathbb{Z}_{\geq0}$, any initial estimation error $e(0)\in\mathcal{X}_e$ and any pair of input and noise $w(k)\in\mathcal{W}$ and $\eta(k)\in\mathcal{N}$, it holds that
    \begin{multline*}
    \norm{e(k)}\leq\beta_o(\norm{e(0)},k)\\        +\gamma_o^w(\max_{h\geq 0}\norm{w(h)})+\gamma_o^\eta(\max_{h\geq 0}\norm{\eta(h)}).
    \end{multline*}\hfill{}$\square$
\end{definition}
