\section{Problem statement}\label{sec:problem_statement}
%
\subsection{The plant model}
%
In this paper we address the problem of controlling a nonlinear plant whose dynamics is defined by an RNN model. We focus on the RNN models defined by the following subclass of RENs (see~\cite{revay2023recurrent,la2025regional}), which in \cite{revay2023recurrent} is denoted as single layer REN,
\begin{equation}\label{eq:plant_dynamics}
\begin{cases}
x(k+1)=A_xx(k)+B_uu(k)+D_ww(k)+B_\sigma\sigma(v(k))\\
v(k)=\tilde{A}x(k)+\tilde{B}u(k)+\tilde Dw(k)\\
y(k)=Cx(k)+\eta(k)
\end{cases}\ 
\end{equation}
%
where $x\in \R^n$ denotes the state vector, $u\in\R^m$ the input vector, $y\in\R^p$ the output vector, $w\in\R^d$ the disturbance vector and the output measurement is corrupted by a noise $\eta(k)\in\R^p$. Also, $A_x\in\R^{n\times n}$, $B_u\in\R^{n\times m}$, $D_w\in\R^{n\times d}$, $B_\sigma\in\R^{n\times \nu}$, $\tilde A\in\R^{\nu\times n}$, $\tilde B\in\R^{\nu\times m}$, 
$\tilde D\in\R^{\nu\times d}$, $C\in\R^{p\times n}$, and $\sigma(\cdot)=\begin{bmatrix}\sigma_1(\cdot)&\dots&\sigma_\nu(\cdot)\end{bmatrix}^{\top}$ is a decentralized vector of scalar functions satisfying the following assumption.
\begin{ass}\label{ass:sigmoid_function}
    Each component $\sigma_i:\R\rightarrow\R$, $i=1,\dots,\nu$, is a sigmoid function, i.e. a bounded, differentiable function with positive and continuous derivative at each point and one and only one inflection point in $v_i=0$. Also, $\sigma_i(\cdot)$ is Lipschitz continuous with unitary Lipschitz constant and such that $\sigma_i(0)=0$, $\frac{  \partial\sigma_i(v_i)}{\partial v_i}\big|_{v_i=0}=1$ and $\sigma_i(v_i)\in[-1,1]$, $\forall v_i\in\R$.\hfill{}$\square$
\end{ass}
%
We make the following assumptions on the boundedness of the terms $w(k)$ and $\eta(k)$.
\begin{ass}\label{ass:disturbance}
The disturbance $w(k)$ satisfies, for all $k\geq 0$, $w(k)\in \mathcal{E}(Q_w^0)$, where $Q_w^0\in\mathbb S_+^d$.\hfill{}$\square$
\end{ass}
\begin{ass}\label{ass:output_noise}
    The disturbance $\eta(k)$ satisfies, for all $k\geq 0$, $\eta(k)\in \mathcal{E}(Q_\eta^0)$, where $Q_\eta^0\in\mathbb S_+^p$.\hfill{}$\square$
\end{ass}
%Note that the assumption of ellipsoidal disturbance sets is done, without loss of generality, to facilitate the derivation of robust LMI-based design and analysis conditions.\\
%
The goal of this work is to design a control system that allows us to steer the plant's output to a neighbour of a constant setpoint $\bar{y}\in\R^p$ that must respect the following assumption. 
\begin{ass}\label{ass:output_reference}
The output reference $\bar{y}$ must be selected in such a way that there exist $\bar x$ and $\bar u$ such that $\bar x=A_x\bar x+B_u\bar u+B_\sigma \sigma(\tilde A\bar x+\tilde B\bar u)$ and $\bar y=C\bar x$.\hfill{}$\square$
\end{ass}
%
\subsection{Model reformulation and incremental sector condition}
%
As done in~\cite{la2025regional}, for convenience the plant dynamics \eqref{eq:plant_dynamics} is rewritten as follows
\begin{equation}\label{eq:plant_dynamics_q_open_loop}
    \begin{cases}
        x(k+1)=Ax(k)+Bu(k)+Dw(k)+B_qq(v(k))\\
        v(k)=\tilde Ax(k)+\tilde Bu(k)+\tilde Dw(k)\\
        y(k)=Cx(k)+\eta(k).
    \end{cases}
\end{equation}
where $A=A_x+B_\sigma \tilde A$, $B=B_u+B_\sigma \tilde B$, $D=D_w+B_\sigma \tilde D$, $B_q=-B_\sigma$, and the vector $ q(v)=\begin{bmatrix}q_1(v_1) & \dots &q_\nu(v_\nu)\end{bmatrix}^\top\in\R^\nu$ is composed of the functions $q_i(v_i)=v_i-\sigma(v_i)$, $i=1,\dots,\nu$. For the reader's convenience, as an example Figure \ref{fig:sigma_q_functions} displays function $\sigma_i(v_i)=\tanh(v_i)$ and $q_i(v_i)=v_i-\tanh(v_i)$.
\begin{figure}[htbp]
     \centering
    \includegraphics[width=0.75\columnwidth]{sigma_q_functions.eps}
    \caption{Function $\sigma_i(v_i)=\tanh(v_i)$ (solid black) and function $q_i(v_i)=v_i-\sigma_i(v_i)$ (dashed blue).}
      \label{fig:sigma_q_functions}
\end{figure}
%
A key property used in this work is the incremental sector condition satisfied by $q_i(\cdot)$, proved in the following lemma.
%
\begin{lemma}\label{lem:sector_condition}
Under Assumption~\ref{ass:sigmoid_function}, for all $h_i>1$, $\exists\bar v_i(h_i)\in\R_{+}$ such that, for all pairs $(v_i,v_i+\Delta v_i)\in[-\bar v_i(h_i),\bar v_i(h_i)]^2$, it holds that
\begin{equation}\label{eq:sector_condition_h}
\Delta q_i(\Delta v_i-h_i\Delta q_i)\geq 0,
\end{equation}
%
where $\Delta q_i=q_i(v_i+\Delta v_i)-q_i(v_i)$. Function $\bar v_i(h_i):(1,+\infty)\to(0,+\infty)$ is a continuous, strictly decreasing function such that $\bar v_i(h_i) \to +\infty$ as $h_i\to 1^+$ and $\bar v_i(h_i)\to0$ as $h_i\to +\infty$. Also, in case $h_i=1$, condition \eqref{eq:sector_condition_h} holds for all $(v_i,v_i+\Delta v_i)\in\R^2$.\hfill{}$\square$
\end{lemma}
The proof of Lemma~\ref{lem:sector_condition} is provided in the Appendix.\smallskip\\
%
%
Note that the analytic expression of $\bar v_i(h_i)$ cannot be defined explicitly. However, for any given $h_i>1$, we can compute $\bar v_i(h_i)$ numerically by solving \eqref{opt:locality_constraints} (see Appendix).\\
%
Let $H=\diag(h_1, \dots,h_\nu)$, $\Delta v=\begin{bmatrix}\Delta v_1&\dots&\Delta v_\nu\end{bmatrix}^\top$ and $\Delta q(v+\Delta v,v)=q(v+\Delta v)-q(v)$, and define the set
\[\mathcal{I}(H)=\{i\in\{1,\dots,\nu\}\ : \ h_i>1\}.\]
In view of \eqref{eq:sector_condition_h}, for any matrix $S\in\mathbb{D}_+^\nu$, the following inequality holds
\begin{multline}\label{eq:sector_inequality}
    \Delta q(v+\Delta v,v)^\top S(\Delta v-H\Delta q(v+\Delta v,v))\geq 0,\\  \forall v,v+\Delta v\in\mathcal{V}(H)
\end{multline}
where the set $\mathcal{V}(H)$ is defined as
\begin{multline*}
    \mathcal{V}(H)\coloneqq\{v\in\R^\nu \ : \ v_i\in[-\bar v_i(h_i),\bar v_i(h_i)], \ \forall i\in \mathcal{I}(H)\}.
\end{multline*}
