\section{Nonlinear observer design}\label{sec:observer}
%
In many real-world applications, particularly when working with RNN models, where state variables may not directly correspond to measurable physical quantities, the system state is often unavailable. %The state-feedback assumption is often impractical in many real-world applications, particularly when working with RNN models, where the state variables may not correspond directly to measurable physical quantities. 
For this reason, to estimate the system state $x(k)$, a nonlinear observer is proposed of the form
\begin{equation}\label{eq:observer_dynamics}
    \begin{cases}
        \begin{aligned}\hat{x}(k+1) = &A\hat{x}(k) + Bu(k) + L(y(k) - C\hat{x}(k)) \\
        &+ B_q q(\hat{v}(k))\end{aligned} \\
        \hat{v}(k) = \tilde{A} \hat{x}(k) + \tilde{B} u(k) + \tilde{L} (y(k) - C\hat{x}(k))
    \end{cases}
\end{equation}
where $\hat x\in\R^n$ is the observer state and $L\in\R^{n\times p}$ and $\tilde L\in\R^{\nu\times p}$ are observer gains.
The following theorem provides a design condition for the observer \eqref{eq:observer_dynamics}.
%
\begin{theorem}
    \label{th:dISS_observer}
    Consider the observer dynamics \eqref{eq:observer_dynamics} and let Assumptions \ref{ass:sigmoid_function}, \ref{ass:disturbance}, and \ref{ass:output_noise} hold. If there exist $\gamma_o\in\R_+$, and matrices $P_o,Q_{o,x}\in \mathbb S^n_+$, $Q_{o,w_o}\in \mathbb S^{d+p}_+$, $H_o,S_o\in\mathbb{D}_+^v$, with $H_o\succeq I_\nu$, $N\in\R^{n\times p}$, and $\tilde N\in\R^{\nu\times p}$, such that 

   \begin{subequations}\label{eq:LMIs_observer}
   \scriptsize{
    \begin{equation}\label{eq:dISS_condition_obs}
    \begin{bmatrix}
        P_o\!-\!Q_{o,x}\!\!&\!\!-\!\tilde A^\top S_o\!+\!C^\top\tilde N^\top\!\!&\!\!0\!\!&\!\!A^\top P_o\!-\!C^\top N^\top\\
        -S_o\tilde A+\tilde NC\!\!&\!\!2S_oH_o\!\!&\!\!\begin{bmatrix}-S_o\tilde D\!\!&\!\!\tilde N\end{bmatrix}\!\!&\!\!B_q^\top P_o\\
        0\!\!&\!\!\begin{bmatrix}-\tilde D^\top S_o\\\tilde N^\top\end{bmatrix}\!\!&\!\!Q_{o,w_o}\!\!&\!\!\begin{bmatrix}D^\top P_o\\N^\top\end{bmatrix}\\
        P_oA-NC\!\!&\!\!P_oB_q\!\!&\!\!\begin{bmatrix}P_oD\!\!&\!\!N\end{bmatrix}\!\!&\!\!P_o
    \end{bmatrix}\!\!\succeq\!0,
    \end{equation}
    \begin{equation}\label{eq:mRPI_set_condition_1_dISS_obs}
        Q_{o,w_o}\preceq \diag{(Q_w^0/2,Q_\eta^0/2)},
    \end{equation}
    \begin{equation}\label{eq:mRPI_set_condition_2_dISS_obs}
        Q_{o,x}-P_o/\gamma_o\succeq 0,
    \end{equation}     
    \begin{equation}\label{eq:locality_set_dISS_obs1}
    \begin{bmatrix}
        P_o/(2\gamma_o)&0&\tilde A_{i}^\top\\
        0&Q_{w}^0/2&\tilde D_{i}^\top\\
        \tilde A_{i}&\tilde D_{i}&\bar v_i(h_{o,i})^2
    \end{bmatrix}\succeq 0, \ \forall i\in\mathcal{I}(H_o),
    \end{equation}
    \begin{equation}\label{eq:locality_set_dISS_obs2}
    \begin{bmatrix}
        P_o/(2\gamma_o)&0&C^\top\tilde N_i^\top\\
        0&Q_\eta^0/2&\tilde N_i^\top\\
        \tilde N_iC&\tilde N_{i}&\bar v_i(h_{o,i})^2s_{o,i}^2
        \end{bmatrix}\succeq 0, \ \forall i\in\mathcal{I}(H_o),
    \end{equation}
    }
\end{subequations}
then, setting $L=P_o^{-1}N$ and $\tilde L=S_o^{-1}\tilde N$,
\begin{itemize}
        \item if $\mathcal{I}(H_o)=\emptyset$,  \eqref{eq:observer_dynamics} has $\delta$ISS observer error dynamics with respect to the sets $\R^n$, $\mathcal{E}(Q_w^0)$, and $\mathcal{E}(Q_\eta^0)$;
        \item if $\mathcal{I}(H_o)\neq\emptyset$ and if the pair ($\hat x$,$u$) satisfies \begin{equation}\label{eq:locality_condition_obs}
        \tilde A \hat x+\tilde Bu\in\bar{\mathcal V}_o,
        \end{equation}
        where the set
        \begin{equation*}
        \begin{aligned}
        \bar{\mathcal V}_o=&\left(\mathcal V(H_o)\ominus\left(\tilde A\mathcal E(P_o/\gamma_o)\oplus\tilde D\mathcal{E}(Q_w^0)\right)\right)\cap\\&\left(\mathcal V(H_o)\ominus\left(\tilde LC\mathcal E(P_o/\gamma_o)\oplus\tilde L\mathcal{E}(Q_\eta^0)\right)\right)
        \end{aligned}
        \end{equation*}
        is non-empty,
        then \eqref{eq:observer_dynamics} has $\delta$ISS observer error dynamics with respect to the sets $\mathcal{E}(P_o/\gamma_o)$, $\mathcal{E}(Q_w^0)$, and $\mathcal{E}(Q_\eta^0)$.
    \end{itemize} 
Moreover, the set $\mathcal{E}(P_o/\gamma_o)$ is an RPI set for the observer error dynamics, i.e., if $x(0)-\hat{x}(0)\in\mathcal{E}(P_o/\gamma_o)$, then $x(k)-\hat{x}(k)\in\mathcal{E}(P_o/\gamma_o)$ for all $k\geq 0$.\hfill{}$\square$
\end{theorem}
The proof of Theorem~\ref{th:dISS_observer} is provided in the Appendix.\smallskip\\
%
%
Regarding the existence of a feasible solution to problem \eqref{eq:LMIs_observer}, note that the feasibility of conditions \eqref{eq:mRPI_set_condition_1_dISS_obs}-\eqref{eq:locality_set_dISS_obs2} primarily depends on the magnitude of the disturbances $w(k)$ and $\eta(k)$. On the other hand, the feasibility of \eqref{eq:dISS_condition_obs} is more critical, as it is directly linked to the structure of model~\eqref{eq:plant_dynamics_q_open_loop}, as stated in the following lemma.
\begin{lemma}\label{lem:NScond_obs}
  A necessary and sufficient condition for the existence of $H_o\in\mathbb D_+^\nu$, with $H_o\succeq I_\nu$, ensuring feasibility of \eqref{eq:dISS_condition_obs} is that the pair $(A,C)$ is detectable.\hfill{}$\square$
\end{lemma}
The proof of Lemma~\ref{lem:NScond_obs} is provided in the Appendix.\smallskip\\
