\section{Controller design}\label{sec:local_dISS}
%
\subsection{The control law}
In this section, we define the control law
\begin{equation}\label{eq:control_law_tracking} 
u(k)=\bar u+K(\hat{x}(k)-\bar x),
\end{equation}
where  $K\in\R^{m\times n}$ is the control gain, which is here designed in order to confer stability properties to the control system.\\
First note that the dynamics of the estimated state $\hat x(k)$ satisfies the following 
\begin{equation}\label{eq:observer_dynamics_2}
\begin{cases}
\begin{aligned}\hat x(k+1)=&A\hat x(k)+Bu(k)+LCe(k)+L\eta(k)\\&+B_qq(\hat v(k))\end{aligned}\\
\hat v(k)=\tilde{A}\hat x(k)+\tilde{B}u(k)+\tilde LCe(k)+\tilde L \eta(k)
\end{cases}
\end{equation}
Let us define the exogenous variable vector $w_c(k)=\begin{bmatrix}\eta(k)^\top,& e(k)^\top\end{bmatrix}^\top$, acting as a disturbance in \eqref{eq:observer_dynamics_2}. %Note that if $\eta(k)$ satisfies Assumption~\ref{ass:output_noise} and the state estimate $\hat x(k)$ is initialized such that $e(0)\in\mathcal{E}(P_o/\gamma_o)$, then $w_c(k)\in \mathcal{E}(Q_{w,c}^0)$, where $Q_{w,c}^0=\diag{(Q_\eta^0,P_o/\gamma_o)}$, for all $k>0$. 
Introducing matrices $A_K=A+BK$, $\tilde A_K=\tilde A+\tilde BK$, $D_c=\begin{bmatrix}L& LC\end{bmatrix}$, and $\tilde D_c=\begin{bmatrix}\tilde L& \tilde LC\end{bmatrix}$, the closed-loop observer state evolves according to
\begin{equation}\label{eq:closed_loop_observer}
\begin{cases}
\begin{aligned}\hat x(k+1)=& A_K \hat x(k)+B(\bar u-K\bar x)+D_c w_c(k)\\&+B_q q(\hat v(k))\end{aligned}\\
\hat v(k)=\tilde A_K\hat x(k)+\tilde B(\bar u-K\bar x)+\tilde D_c w_c(k)\\
\end{cases}
\end{equation}
The following theorem establishes a sufficient condition for the $\delta$ISS of the observer state dynamics \eqref{eq:closed_loop_observer}.
\\
\begin{theorem}\label{th:dISS}
Let Assumptions \ref{ass:sigmoid_function}, \ref{ass:disturbance}, and \ref{ass:output_noise} hold. Also, assume that $e(k)\in\mathcal{E}(P_o/\gamma_o)$ for $k\geq0$, and define $Q_{w,c}^0=\diag{(Q_\eta^0,P_o/\gamma_o)}$. If there exist $\gamma_c\in\R_{+}$, and matrices $Q_c,\tilde Q_{c,x}\in\mathbb{S}_+^n$, $Q_{c,w_c}\in\mathbb{S}_+^d$ and $H_c,U_c\in\mathbb D_+^\nu$, with $H_c\succeq I_\nu$, and $Z\in\R^{m,n}$ that satisfy the following conditions
