%\footnotesize
%\setlength{\abovedisplayskip}{3pt}
%\setlength{\belowdisplayskip}{3pt}
\begin{subequations}\label{eq:LMIs}
\scriptsize{
\begin{equation}\label{eq:dISS_condition}
\begin{bmatrix}
    Q_c-\tilde Q_{c,x}\!\!&\!\!-Q_c\tilde A^\top\!-\!Z^\top \tilde B^\top \!\!&\!\!0\!\!&\!\!Q_cA^\top\!+\!Z^\top B^\top\\
    -\tilde AQ_c\!-\!\tilde B Z\!\!&\!\!2H_cU_c\!\!&\!\! -\tilde D_c\!\!&\!\!U_cB_q^\top\\
    0\!\!&\!\!-\tilde D_c^\top \!\!&\!\!Q_{c,w_c}\!\!&\!\!D_c^\top\\
    AQ_c\!+\!BZ\!\!&\!\!B_qU_c\!\!&\!\!D_c\!\!&\!\!Q_c
\end{bmatrix}
    \!\!\succeq 0,
\end{equation}
\begin{equation}\label{eq:mRPI_set_condition_1_dISS}
Q_{c,w_c}\preceq Q_{w_c}^0,
\end{equation}
\begin{equation}\label{eq:mRPI_set_condition_2_dISS}
 \tilde Q_{c,x}-Q_c/\gamma_c\succeq0,
%\tilde Q_x - Q/\gamma\succeq 0,
\end{equation}
\begin{equation}\label{eq:locality_set_dISS}
\begin{bmatrix}\
        Q_c/(2\gamma_c)\!\!\!&\!\!\!0\!\!\!&\!\!\!Q_c\tilde A_{i}^\top+Z^\top\tilde B_i^\top\\
        0\!\!\!&\!\!\!Q_{w_c}^0/2\!\!\!&\!\!\!\tilde D_{c,i}^\top\\
        \tilde A_{i}Q_c+\tilde B_iZ\!\!\!&\!\!\!\tilde D_{c,i}\!\!\!&\!\!\!(\bar v_i(h_{c,i})\!-\!|\tilde A_i\bar x\!+\!\tilde B_i\bar u|)^2
        \end{bmatrix}\!\!\succeq 0, \ \forall i\in\mathcal{I}(H_c),
\end{equation}
%\textcolor{blue}{
\begin{equation}\label{eq:locality_set_dISS_ctrobs1}
\begin{aligned}
&\begin{bmatrix}\
        Q_c/(3\gamma_c)\!\!\!&\!\!\!0&\!\!\!0\!\!\!&\!\!\!Q_c\tilde A_{i}^\top+Z^\top\tilde B_i^\top\\
        0\!\!\!&\!\!\!P_o/(3\gamma_o)\!\!\!&\!\!\!0\!\!\!&\!\!\!\tilde A_{i}^\top\\
        0\!\!\!&\!\!\!0\!\!\!&\!\!\!Q_w^0/3\!\!\!&\!\!\!\tilde D_{i}\\
