        \end{bmatrix}\!\!\succeq 0,\\& \ \forall i\in\mathcal{I}(H_o),
\end{aligned}
\end{equation}
\begin{equation}\label{eq:locality_set_dISS_ctrobs2}
\begin{aligned}
&\begin{bmatrix}\
        Q_c/(3\gamma_c)\!\!\!&\!\!\!0\!\!\!&\!\!\!0\!\!\!&\!\!\!Q_c\tilde A_{i}^\top+Z^\top\tilde B_i^\top\\
        0\!\!\!&\!\!\!P_o/(3\gamma_o)\!\!\!&\!\!\!0\!\!\!&\!\!\! C^\top \tilde L_{i}^\top\\
        0\!\!\!&\!\!\!0\!\!\!&\!\!\!Q_\eta^0/3\!\!&\!\!\tilde L_{i}^\top\\
        \tilde A_{i}Q_c+\tilde B_iZ\!\!\!&\!\!\!\tilde L_{i}C\!\!\!&\!\!\!\tilde L_{i}\!\!\!&\!\!\!(\bar v_i(h_{o,i})\!-\!|\tilde A_i\bar x\!+\!\tilde B_i\bar u|)^2
        \end{bmatrix}\!\!\succeq 0, \\& \forall i \in \mathcal{I}(H_o),
\end{aligned}
\end{equation}
%}
\begin{equation}\label{eq:locality_eq_dISS}
\bar v_i(h_{c,i})\geq|\tilde A_i\bar x+\tilde B_i\bar u|, \ \forall i\in\mathcal{I}(H_c),
\end{equation}
%\textcolor{blue}{
\begin{equation}\label{eq:locality_eq_dISS_ctrobs}
\bar v_i(h_{o,i})\geq|\tilde A_i\bar x+\tilde B_i\bar u|, \ \forall i\in\mathcal{I}(H_o),
\end{equation}}
\end{subequations}
%\endgroup
%\normalsize
then, setting $K=ZQ_c^{-1}$ and $P_c=Q_c^{-1}$, 
\begin{itemize}
    \item if $\mathcal{I}(H_c)=\emptyset$, the system described by \eqref{eq:closed_loop_observer} is $\delta$ISS with respect to the sets $\R^n$ and $\mathcal E(Q_{w_c}^0)$;
    \item if $\mathcal{I}(H_c)\neq\emptyset$, system \eqref{eq:closed_loop_observer} is $\delta$ISS with respect to the sets $\mathcal{E}(P_c/\gamma_c)\oplus\bar x$ and $\mathcal E(Q_{w_c}^0)$. 
\end{itemize} 
Moreover, the set $\mathcal{E}(P_c/\gamma_c)\oplus\bar x$ is an RPI set for the closed-loop observer dynamics and, if $\hat x(0)\in\mathcal{E}(P_c/\gamma_c)\oplus\bar x$, then also \eqref{eq:locality_condition_obs} holds for all $k>0$.\hfill{}$\square$
\end{theorem}
The proof of Theorem~\ref{th:dISS} is provided in the Appendix.\smallskip\\
It is important to consider also the feasibility of the LMI inequalities \eqref{eq:LMIs}. Similarly to the case of \eqref{eq:LMIs_observer}, while the feasibility of \eqref{eq:mRPI_set_condition_1_dISS}-\eqref{eq:locality_eq_dISS_ctrobs} basically depends on the magnitude of the output noise $\eta(k)$ and of the estimation error $e(k)$ and on the choice of the equilibrium setpoint, inequality
\eqref{eq:dISS_condition} is the key one since it is essentially related to the system structure. In the following lemma we provide a sufficient and necessary condition for the existence of a suitable $H_c$ that allows us to provide a feasible solution to it.
%
%
\begin{lemma}\label{lem:NScond}
  A necessary and sufficient condition for the existence of $H_c\in\mathbb D_+^\nu$, with $H_c\succeq I_\nu$, ensuring feasibility of \eqref{eq:dISS_condition} is that $(A,B)$ is stabilizable.\hfill{}$\square$
\end{lemma}
The proof of Lemma~\ref{lem:NScond} is provided in the Appendix.
