\begin{algorithm}[t]
\caption{Design Procedure}
\label{alg:design_procedure}
\begin{algorithmic}[1]
\State \textbf{Ensure} $(A,B)$ is stabilizable and $(A,C)$ is detectable
\State \textbf{Set} $H_o = I_\nu$, $\gamma_o = 1$, $H_c = I_\nu$, $\gamma_c = 1$,  
$\gamma_{o,\text{max}}, \gamma_{c,\text{max}}, \varepsilon_h, \varepsilon_\gamma \in \mathbb{R}_+$

\While{\eqref{eq:dISS_condition_obs}-\eqref{eq:locality_set_dISS_obs1} is not feasible}
    \If{$\gamma_o < \gamma_{o,\text{max}}$}
        \State \textbf{Set} $\gamma_o = \gamma_o + \varepsilon_\gamma$
    \Else
        \State \textbf{Set} $H_o = H_o + \varepsilon_h I_\nu$, $\gamma_o = 1$
        \If{\eqref{eq:locality_eq_dISS_ctrobs} is not satisfied}
            \State \textbf{Exit:} Problem is infeasible
        \EndIf
    \EndIf
\EndWhile

\State Fix $S_o$
\If{\eqref{eq:LMIs_observer} is feasible}
    \State \textbf{Set} $L = P_o^{-1}N$, $\tilde{L} = S_o^{-1}\tilde{N}$
\Else
    \State \textbf{Go to line} 3
\EndIf

\While{\eqref{eq:dISS_condition}-\eqref{eq:locality_set_dISS_ctrobs2} is not feasible}
    \If{$\gamma_c < \gamma_{c,\text{max}}$}
        \State \textbf{Set} $\gamma_c = \gamma_c + \varepsilon_\gamma$
    \Else
        \State \textbf{Set} $H_c = H_c + \varepsilon_h I_\nu$, $\gamma_c = 1$
        \If{\eqref{eq:locality_eq_dISS} is not satisfied}
            \State \textbf{Exit:} Problem is infeasible
        \EndIf
    \EndIf
\EndWhile

\State \textbf{Set} $K = ZQ_c^{-1}$, $P_c = Q_c^{-1}$
\end{algorithmic}
\end{algorithm}
