%
%
%
%
Note that, applying \eqref{eq:control_law_tube} to the observer dynamics \eqref{eq:observer_dynamics_2}, the resulting closed-loop dynamics evolves as
\begin{equation}\label{eq:closed_loop_observer_MPC}
\begin{aligned}
\hat x(k+1)=&A_K\hat x(k)+B(\tilde u(k)-K\tilde x(k))+D_cw_c(k)\\&+B_qq(\tilde{A}_K\hat x(k)+\tilde{B}(\tilde u(k)-K\tilde x(k))\\&+\tilde D_cw_c(k)).
\end{aligned}
\end{equation}
\begin{proposition}\label{prop:dISS_control}
    Let Assumptions \ref{ass:sigmoid_function}, \ref{ass:disturbance}, and \ref{ass:output_noise} hold. Also, assume that $e(k)\in\mathcal{E}(P_o/\gamma_o)$, for $k\geq0$. If there exist $\gamma_c\in\R_+$, and matrices $Q_c,\tilde Q_{c,x}\in \mathbb S^n_+$, $Q_{c,w_c}\in \mathbb S^{n+p}_+$, $H_c,U_c\in\mathbb{D}_+^v$, with $H_c\succeq I_\nu$, and $Z\in\R^{m\times n}$ that satisfy \eqref{eq:dISS_condition}-\eqref{eq:mRPI_set_condition_2_dISS}, and such that  \begin{equation}\label{eq:locality_set_dISS_mpc}
    \begin{bmatrix}\
        Q_c/(2\gamma_c)\!\!&\!\!0\!\!&\!\!Q_c\tilde A_{i}^\top+Z^\top \tilde B_i^\top\\
        0\!\!&\!\!Q_{w_c}^0/2\!\!&\!\!\tilde D_{c,i}\\
        \tilde A_{i}Q_c+\tilde B_iZ\!\!&\!\!\tilde D_{c,i}\!\!&\!\!\bar v_i(h_{c,i})^2
        \end{bmatrix}\succeq 0, \ \forall i\in\mathcal{I}(H_c),
    \end{equation}
then, setting $K=ZQ_c^{-1}$ and $P_c=Q_c^{-1}$, \begin{itemize}
        \item if $\mathcal{I}(H_c)=\emptyset$, the closed-loop observer dynamics \eqref{eq:closed_loop_observer_MPC} is $\delta$ISS with respect to the sets $\R^n$ and $\mathcal{E}(Q_{w_c}^0)$;
        \item if $\mathcal{I}(H_c)\neq\emptyset$ and the pair ($\tilde x$, \ $\tilde u$) satisfies 
        \begin{equation}\label{eq:locality_constr_MPC}
        \tilde A \tilde x+\tilde B\tilde u\in\bar{\mathcal V}_c,
        \end{equation}
        where the set
        \begin{equation*}
        \bar{\mathcal V}_c=\mathcal V(H_c)\ominus\left(\tilde A_K\mathcal E(P_c/\gamma_c)\oplus\tilde D_c\mathcal{E}(Q_{w_c}^0)\right)
        \end{equation*}
        is non-empty, the closed-loop observer dynamics \eqref{eq:closed_loop_observer_MPC} is $\delta$ISS with respect to the sets $\mathcal{E}(P_c/\gamma_c)\oplus\tilde x$ and $\mathcal{E}(Q_{w_c}^0)$.
    \end{itemize} 
Moreover, the set $\mathcal{E}(P_c/\gamma_c)$ is an RPI set for the dynamics of $\tilde e(k)$.\hfill{}$\square$
\end{proposition}
The proof of Proposition~\ref{prop:dISS_control} is provided in the Appendix.\smallskip\\
%
Note that the state $x(k)$ of the real system is computed as $x(k)=\tilde x(k)+e(k)+\tilde e(k)$. Therefore, if the observer gains $(L,\tilde L)$ and the control gain $K$ are selected according to Theorem~\ref{th:dISS_observer} and Proposition~\ref{prop:dISS_control}, respectively, the set $\mathcal{E}(P_o/\gamma_o)\oplus\mathcal{E}(P_c/\gamma_c)$ is an RPI set for the dynamics of $x(k)-\tilde x(k)$, provided that $e(0)\in\mathcal{E}(P_o/\gamma_o)$ and, if $\mathcal{I}(H_o)\neq\emptyset$ or $\mathcal{I}(H_c)\neq\emptyset$, condition \eqref{eq:locality_condition_obs} and \eqref{eq:locality_constr_MPC}, respectively, hold. The following lemma reformulates \eqref{eq:locality_condition_obs} with respect to the state and input of the nominal system.
\begin{lemma}\label{lem:MPC_locality_cstr} 
%\footnotesize
Let the assumptions of Proposition~\ref{prop:dISS_control} hold. If there exist $\gamma_c\in\R_+$, $Q_c\in\mathbb S_+^n$ and $Z\in\R^{m\times n}$ that, for all $i\in\mathcal I(H_o)$, satisfy 
\begin{subequations}
    \begin{equation}\label{eq:locality_set_dISS_obs_mpc_1}
    \begin{bmatrix}
    P_o/(3\gamma_o)\!\!&\!\!0\!\!&\!\!0\!\!&\!\!\tilde A_i^\top\\
    0\!\!&\!\!Q_c/(3\gamma_c)\!\!&\!\!0\!\!&\!\!Q_c\tilde A_{i}^\top+Z\tilde B_i^\top\!\!&\!\!\\
    0\!\!&\!\!0&\!\!Q_w^0/3\!\!&\!\!\tilde D_i^\top\\
    \tilde A_i\!\!&\!\!\tilde A_{i}Q_c+\tilde B_iZ\!\!&\!\!\tilde D_i\!\!&\!\!\bar v(h_{i,o})^2
    \end{bmatrix}\!\!\succeq 0
    \end{equation}
    \begin{equation}\label{eq:locality_set_dISS_obs_mpc_2}
    \begin{bmatrix}
    P_o/(3\gamma_o)\!\!&\!\!0\!\!&\!\!0\!\!&\!\!C^\top\tilde L_i^\top\\
    0\!\!&\!\!Q_c/(3\gamma_c)\!\!&\!\!0\!\!&\!\!Q_c\tilde A_{i}^\top+Z\tilde B_i^\top\!\!&\!\!\\
    0\!\!&\!\!0&\!\!Q_\eta^0/3\!\!&\!\!\tilde L_i^\top\\
    \tilde L_iC\!\!&\!\!\tilde A_{i}Q_c+\tilde B_iZ\!\!&\!\!\tilde L_i\!\!&\!\!\bar v(h_{i,o})^2
    \end{bmatrix}\!\!\succeq 0
    \end{equation}
\end{subequations}
\normalsize
then, setting $K=ZQ_c^{-1}$ $P_c=Q_c^{-1}$, if $\tilde e\in\mathcal{E}(P_c/\gamma_c)$ and the pair $(\tilde x,\tilde u)$ satisfies
    \begin{equation}\label{eq:locality_constr_obsMPC}
    \tilde A\tilde x+\tilde B\tilde u\in\mathcal{\bar V}_{o_c},
\end{equation}
where the set 
\begin{align*}
\mathcal{\bar V}_{o_c}\!\!=&\left(\mathcal V(H_o)\!\ominus\!\left(\tilde A\mathcal E(P_o/\gamma_o)\!\oplus\!\tilde D\mathcal{E}(Q_w^0)\!\oplus\!\tilde A_K\mathcal E(P_c/\gamma_c)\right)\right)\cap\\
&\left(\mathcal V(H_o)\!\ominus\!\left(\tilde LC\mathcal E(P_o/\gamma_o)\!\oplus\!\tilde L\mathcal{E}(Q_\eta^0)\!\oplus\!\tilde A_K\mathcal E(P_c/\gamma_c)\right)\right),
\end{align*}
is non-empty, then \eqref{eq:locality_condition_obs} holds. \hfill{}$\square$
\end{lemma}
The proof of Lemma~\ref{lem:MPC_locality_cstr} is provided in the Appendix.
