\subsection{Constraint tightening}
The formulation of the NMPC problem requires expressing the state and control constraints in terms of equivalent constraints for the nominal system.
We make the following assumption.
\begin{ass}\label{ass:set}
        There exist $\epsilon_u,\epsilon_y\in\R_+$, $\bar{\bar y}\in\R^p$ and $\bar{\bar u}\in\R^m$
    such that $C\mathcal E(P_c/\gamma_c)\oplus C\mathcal E(P_o/\gamma_o)\oplus\mathcal{B}_{\epsilon_y}^{(p)}(\bar{\bar y})\subseteq \mathbb{Y}$ and $K\mathcal E(P_c/\gamma_c)\oplus\mathcal{B}_{\epsilon_u}^{(m)}(\bar{\bar u})  \subseteq \mathbb{U}$.\hfill{}$\square$
\end{ass}
%
In view of Assumption~\ref{ass:set}, %Theorem~\ref{th:dISS_observer} and Proposition~\ref{prop:dISS_control}
we can define the tightened sets $\tilde{\mathbb Y}=\mathbb Y\ominus C\left(\mathcal{E}(P_o/\gamma_o)\oplus\mathcal{E}(P_c/\gamma_c)\right)$ and $\tilde{\mathbb U}=\mathbb U\ominus K\mathcal{E}(P_c/\gamma_c)$.
Moreover, to guarantee \eqref{eq:locality_constr_MPC}  when $\mathcal{I}(H_c)\neq\emptyset$, we introduce the set 
\[\mathcal V_c(H_c)=\{v\in\R^\nu:|v_i|\leq\bar v_{c,i}(h_{c,i}), \ \forall i\in \mathcal{I}(H_c)\}\]
where
\begin{equation*}
\bar{v}_{c,i}(h_{c,i}) = \bar{v}_i(h_{c,i}) - \max_{\substack{\tilde e \in \mathcal{E}(P_c/\gamma_c), \\ w_c \in \mathcal{E}(Q_{w_c})}} |\tilde{A}_{K,i} \tilde e  + \tilde{D}_{c,i} w_c|.
\end{equation*}
Note that $\mathcal V_c(H_c)\subseteq\bar{\mathcal V}_c$.
Additionally, to guarantee \eqref{eq:locality_constr_obsMPC}, we define the set
\[
\mathcal V_o(H_o)=\{v\in\R^\nu:|v_i|\leq\bar v_{o,i}^\star(h_{o,i}), \\\ \forall i\in \mathcal{I}(H_o)\}
\]
where $\bar v_{o,i}^\star(h_{o,i})=\min(\bar v_{o,i}(h_{o,i}),\tilde v_{o,i}(h_{o,i}))$, with
\begin{equation*}
\bar{v}_{o,i}(h_{o,i}) = \bar{v}_i(h_{o,i}) -\max_{\substack{e \in \mathcal{E}(P_o/\gamma_o), \\ w \in \mathcal{E}(Q_w^0), \\ \tilde e \in \mathcal{E}(P_c/\gamma_c)}}  |\tilde{A}_{i} e + \tilde{D}_{i} w+\tilde A_{K,i}  \tilde e|,
\end{equation*}
and
\begin{equation*}
\tilde{v}_{o,i}(h_{o,i}) = \bar{v}_i(h_{o,i}) - \max_{\substack{e \in \mathcal{E}(P_o/\gamma_o), \\ \eta \in \mathcal{E}(Q_\eta^0), \\ \tilde e \in \mathcal{E}(P_c/\gamma_c)}} |\tilde{L}_{i}C e + \tilde{L}_{i} \eta+\tilde A_{K,i} \tilde e|.
\end{equation*}
Note that $\mathcal V_o(H_o)\subseteq\bar{\mathcal V}_{o_c}$.\\
%
Finally, we modify Assumption~\ref{ass:output_reference} as follows.
\begin{ass}\label{ass:output_reference_constr}
The output reference $\bar{y}\in \mathcal{INT}(\tilde{\mathbb Y})$ must be selected in such a way that the equilibrium triple $(\bar x,\bar u,\bar y)$ satisfies $\bar u\in \mathcal{INT}(\tilde{\mathbb{U}})$ and $\tilde A\bar x+\tilde B\bar u\in\mathcal{V}_o(H_o)\cap\mathcal{V}_c(H_c)$.
\end{ass}
%
\subsection{Tube-based NMPC design}
In line with the classic tube-based NMPC, at each time instant $k$ a finite-horizon optimal control problem (FHOCP) is stated with reference to the nominal system \eqref{eq:nom_system}. The control input sequence $\tilde{u}([k:k+N-1])$ on a given prediction horizon of length $N$ and the nominal state $\tilde{x}(k)$ are considered as optimization variables.\\
The FHOCP is formulated as follows
\begin{subequations}\label{opt:NMPC}
\begin{align}
&\min_{\tilde{x}(k),\tilde{u}([k:k+N-1])} J(\tilde{x}([k:k+N]),\tilde{u}([k:k+N-1]) \notag\\
&\text{subject to:} \notag\\
&\hat x(k)-\tilde x(k) \in \mathcal{E}(P_c/\gamma_c)\label{opt:NMPC_init}\\
&\forall\tau=0,\dots,\ N-1:\notag\\
&\quad \begin{aligned}
&\tilde{x}(k+\tau+1) = A \tilde{x}(k+\tau) + B \tilde{u}(k+\tau) \\
&\quad + B_q q \left( \tilde{A} \tilde{x}(k+\tau) + \tilde{B} \tilde{u}(k+\tau) \right)
\end{aligned} \label{opt:NMPC_system} \\
&\quad \tilde{u}(k+\tau)\in \tilde{ \mathbb U} \label{opt:NMPC_input}\\
&\quad C\tilde{x}(k+\tau)\in\tilde{\mathbb Y}\label{opt:NMPC_outputcstr}\\
&\quad\tilde A\tilde x(k+\tau)+ \tilde B\tilde u(k+\tau)\in\mathcal V_c(H_c)\label{opt:NMPC_localcstr_control}\\
&\quad\tilde A\tilde x(k+\tau)+ \tilde B\tilde u(k+\tau)\in\mathcal V_o(H_o)\label{opt:NMPC_localcstr_observer}\\
&\tilde{x}(k+N) \in \mathbb X_f(\bar x) \label{opt:NMPC_terminal}
\end{align}
\end{subequations}
Note that constraint \eqref{opt:NMPC_system} embeds the dynamics of the predictive model, which is initialized by constraint \eqref{opt:NMPC_init} in the neighbourhood of the state estimate $\hat x(k)$. Input and output constraints are imposed through \eqref{opt:NMPC_input} and \eqref{opt:NMPC_outputcstr}, respectively. Locality constraints \eqref{eq:locality_constr_MPC} and \eqref{eq:locality_constr_obsMPC} are enforced through \eqref{opt:NMPC_localcstr_control} and \eqref{opt:NMPC_localcstr_observer}, respectively. Finally, the nominal state is required to reach the terminal set $\mathbb X_f(\bar x)$ at the end of the prediction horizon, as specified by \eqref{opt:NMPC_terminal}.  Let the cost function, which penalizes the deviation of $(\tilde x,\ \tilde u)$ from the target equilibrium $(\bar x,\ \bar u)$, be defined by 
\begin{multline*}
    J=\sum_{\tau=0}^{N-1}\left(\norm{\tilde{x}(k+\tau)-\bar x}_{\Lambda_x}^2+\norm{\tilde{u}(k+\tau)-\bar u}_{\Lambda_u}^2\right)\\+V_f(\tilde{x}(k+N),\bar x)
\end{multline*}
where $\Lambda_x\in\mathbb S_+^n$, $\Lambda_u\in\mathbb S_+^m$, and $V_f$ is the terminal cost.\\
According to the receding horizon approach, the optimal solution of the FHOCP, denoted as $(\tilde x(k),\ \tilde u([k:k+N]))$, is computed at each time step, and the control law~\eqref{eq:control_law_tube} is applied to the system.
%
\subsection{Terminal ingredients}
As customary, we base the design of the NMPC terminal components, namely the terminal set $\mathbb{X}_f(\bar x)$ and the terminal cost $V_f(\tilde x(k),\bar x)$, on the definition of an auxiliary law. In particular, we select as an auxiliary law 
\begin{equation}\label{eq:control_law_aux}
    \tilde u(k)=\bar u+K(\tilde x(k)-\bar x),
\end{equation}
%where $K$ is a design parameter. 
The terminal set is defined as 
\[\mathbb X_f(\bar x)=\mathcal E(P_f/\gamma_f)\oplus\bar x,\]
where $P_f\in\mathbb S_+^n$ and $\gamma_f\in\R_+$. The terminal cost is defined as \[V_f(\tilde x(k+N),\bar x)=\norm{\tilde x(k+N)-\bar x}^2_{P_f}.\]
%Additionally, constraints \eqref{eq:locality_constr_hf_terminal}-\eqref{eq:output_constr_terminal} ensure that for $\tilde x\in\mathcal{E}(P_f/\gamma_f)\oplus\bar x$, it holds $\tilde A_K\tilde x\in\mathcal{V}(H_f)\cap\mathcal{V}_c(H_c)\cap\mathcal{V}_o(H_o)$, $K\tilde x\in\tilde{ \mathbb U}$, and $C\tilde x\in\tilde{ \mathbb Y}$, respectively.\\
%
\subsection{Design procedure}\label{sec:NMPC_design}
Consider the control system represented in Figure~\ref{fig:control_architecture_MPC}. The following procedure is proposed for the design of the observer gains $(L,\tilde L)$, the control gain $K$, and the terminal ingredients $\mathbb{X}_f(\bar x)$ and $V_f(\tilde x(K+N),\bar x)$.\smallskip\\
\step{1} To determine the observer gains $(L,\tilde L)$  and the control gain $K$, execute Algorithm~\ref{alg:design_procedure}, replacing step $14$ with the LMI problem
\begin{align*}
&\min_{\substack{Q_c,\tilde Q_{c,x}\in\mathbb{S}_+^n, Q_{c,w_c}\in\mathbb{S}_+^{n+p},\\Z\in\R^{m\times n},U_c\in\mathbb{D}_+^\nu}} \beta_c\\
&\text{subject to:}\\
&\quad\eqref{eq:dISS_condition}–\eqref{eq:mRPI_set_condition_2_dISS},\eqref{eq:locality_set_dISS_mpc},\eqref{eq:locality_set_dISS_obs_mpc_1},\eqref{eq:locality_set_dISS_obs_mpc_2},\\
&\quad f_{LMI,c}(Q_c)\preceq\beta_cI
\end{align*}
where $f_{LMI,c}(Q_c)$ is a function defined by the designer to minimize the RPI set $\mathcal{E}(P_c/\gamma_c)$ (see \cite{boyd1994linear}).\\
\step{2} Define the tightened sets $\tilde{\mathbb Y}$ and $\tilde{\mathbb U}$, the sets $\mathcal{V}_c(H_c)$ and $\mathcal{V}_o(H_o)$, and set $H_f=I_\nu$.\\  
\step{3} Solve the following optimization problem
\begin{subequations}\label{opt:terminal_ingredients}
\begin{align}
\footnotesize
&\min_{\tilde{\gamma}_f\in\R_+,P_f\in\mathbb S_+^n,S_f\in\mathbb D_+^\nu} \beta_{f,1}\text{trace}(P_f)+\beta_{f,2}\gamma_f\label{eq:cost_terminal}\\
&\text{subject to:}\notag\\
&
\begin{bmatrix}
P_f-\Lambda_x-K^\top\Lambda_uK & -\tilde A_{K}^\top S_f & A_{K}^\top P_f\\
-S_f\tilde A_{K} & 2S_fH_f & B_q^\top P_f\\
P_fA_{K} & P_fB_q & P_f
\end{bmatrix}\succeq 0\label{eq:dISS_terminal}\\
&
\begin{bmatrix}
    P_f\!\!&\!\!C^\top G_{y,r}^\top\\
    G_{y,r}C\!\!&\!\!\tilde\gamma_f(b_{y,r}-G_{y,r}C\bar x)^2
\end{bmatrix}\succeq0, \ \forall r=1,\dots,\ n_r\label{eq:output_constr_terminal}\\
&
\begin{bmatrix}
    P_f&K^\top G_{u,s}^\top\\
    G_{u,s}K&\tilde\gamma_f(b_{u,s}-G_{u,s}\bar u)^2
\end{bmatrix}\succeq0, \ \forall s=1,\dots,\ n_s\label{eq:input_constr_terminal}\\
&
\begin{bmatrix}
    P_f&\tilde A_{K,i}^\top\\
    \tilde A_{K,i}&\tilde\gamma_fv_i(h_{f,i})^2
\end{bmatrix}\succeq0, \ \forall i\in \mathcal I(H_f)\label{eq:locality_constr_hf_terminal}\\
&
\begin{bmatrix}
    P_f\!\!&\!\!\tilde A_{K,i}^\top\\
    \tilde A_{K,i}\!\!&\!\!\tilde\gamma_f(\bar v_{c,i}(h_{c,i})\!-\!|\tilde A_i\bar{x}\!+\!\tilde B_i\bar{u}|)^2
\end{bmatrix}\!\!\succeq\!0, \ \forall i\!\in\! \mathcal I(H_c)\label{eq:locality_constr_hc_terminal}\\
&
\begin{bmatrix}
    P_f\!\!&\!\!\tilde A_{K,i}^\top\\
    \tilde A_{K,i}\!\!&\!\!\tilde\gamma_f(\bar v_{o,i}^\star(h_{o,i})\!-\!|\tilde A_i\bar{x}\!+\!\tilde B_i\bar{u}|)^2
\end{bmatrix}\!\!\succeq\!0, \ \forall i\!\in\! \mathcal I(H_o)\label{eq:locality_constr_ho_terminal}
\end{align}
\end{subequations}
%\normalsize
where $\beta_{f,1},\beta_{f,2}\in\R_+$ are design parameters. If \eqref{opt:terminal_ingredients} is feasible, set $\gamma_f=1/\tilde{\gamma}_f$, otherwise set $H_f=H_f+\epsilon_hI_\nu$ and repeat Step 3.\\
Note that the minimization of the cost \eqref{eq:cost_terminal} in \eqref{opt:terminal_ingredients} allows maximising the set $\mathbb X_f(\bar x)$.
%
%
\subsection{Main result}
The theoretical properties of the resulting closed-loop system are summarized in the following theorem.
\begin{theorem}\label{th:FHOCP_guarantees}
Suppose that Assumptions \ref{ass:sigmoid_function}-\ref{ass:output_reference_constr} are verified and that $e(0) \in \mathcal{E}(P_o/\gamma_o)$. Then, if the FHOCP  \eqref{opt:NMPC} admits a solution at time $k=0$, it admits a solution for each $k>0$. Moreover, the output ${y}$ asymptotically converges to $\bar y\oplus C\mathcal{E}(P_c/\gamma_c)\oplus C\mathcal{E}(P_o/\gamma_o)$ as $k\rightarrow+\infty$.\hfill{}$\square$
\end{theorem}
The proof of Theorem~\ref{th:FHOCP_guarantees} is provided in the Appendix.\smallskip\\
