\section*{Appendix: proof of the main results}
%
In this appendix we report the proofs of the main results reported in the paper. In the following, we omit the time dependency where possible for the sake of conciseness.\smallskip\\
%
Before proceeding with the proofs, we need to introduce first the following lemma. 
\begin{lemma}\label{lem:constr_satisfaction}
    Consider $n_v$ vectors $v_i\in\mathcal{E}(P_i)$, where $P_i\in \mathbb{S}^{n_i}_{+}$, $i=1,\dots,n_v$. A sufficient condition for $|\sum_{i=1}^{n_v}G_iv_i|\leq b$, where $G_i$ are matrices of suitable dimensions and $b\in\R_{+}$, is 
\begin{equation}\label{eq:constr_satisfaction}
    \begin{bmatrix}
        P_1/n_v & 0 & \cdots & 0 & G_1^\top \\
        0 & P_2/n_v  & \cdots & 0 & G_2^\top \\
        \vdots & \vdots & \ddots & \vdots & \vdots \\
        0 & 0 & \cdots & P_n/n_v  & G_{n_v}^\top \\
        G_1 & G_2 & \cdots & G_{n_v} & b^2
    \end{bmatrix} \succeq 0.
\end{equation}
\hfill{}$\square$
\end{lemma}
\textbf{Proof of Lemma \ref{lem:constr_satisfaction}}.
Since  $v_i\in\mathcal{E}(P_i)$ for all $i=1,\dots,n_v$,  it follows that $\sum_{i=1}^\nu v_i^\top P_iv_i\leq n_v$, which can be rewritten in quadratic form as
\begin{equation}\label{eq:constr_satisfaction_1}
\begin{bmatrix}
    v_1^\top&\dots&v_{n_v}^\top
\end{bmatrix}
\begin{bmatrix}
        P_1/n_v \!\!&\!\! 0 \!\!&\!\! \cdots \!\!&\!\! 0\\
        0 \!\!&\!\! P_2/n_v  \!\!&\!\! \cdots \!\!&\!\! 0\\
        \vdots \!\!&\!\! \vdots \!\!&\!\! \ddots \!\!&\!\! \vdots \\
        0 \!\!&\!\! 0 \!\!&\!\! \cdots \!\!&\!\! P_n/n_v
    \end{bmatrix}
\begin{bmatrix}
    v_1\\\vdots\\v_{n_v}
\end{bmatrix}\leq 1.
\end{equation}
By applying the Schur complement, condition \eqref{eq:constr_satisfaction} is equivalent to
\[
\begin{bmatrix}
        P_1/n_v\!\!&\!\!0\!\!&\!\!\cdots &\!\!0\\
        0\!\!&\!\!P_2/n_v\!\!&\!\!\cdots\!\!&\!\!0\\
        \vdots\!\!&\!\!\vdots\!\!&\!\!\ddots\!\!&\!\!\vdots \\
        0\!\!&\!\!0 &\!\!\cdots\!\!&\!\! P_n/n_v
\end{bmatrix}\!-\!\cfrac{1}{b^2}\begin{bmatrix}
        G_1^\top\\\vdots\\G_{n_v}^\top
\end{bmatrix}
\begin{bmatrix}
        G_1\!\!&\!\!\dots\!\!&\!\!G_{n_v}
\end{bmatrix}\succeq0,
\]
which leads to
\begin{equation}\label{eq:constr_satisfaction_2}
\begin{bmatrix}
        P_1/n_v\!\!&\!\!0\!\!&\!\!\cdots &\!\!0\\
        0\!\!&\!\!P_2/n_v\!\!&\!\!\cdots\!\!&\!\!0\\
        \vdots\!\!&\!\!\vdots\!\!&\!\!\ddots\!\!&\!\!\vdots \\
        0\!\!&\!\!0 &\!\!\cdots\!\!&\!\! P_n/n_v
\end{bmatrix}\!\succeq\cfrac{1}{b^2}\begin{bmatrix}
        G_1^\top\\\vdots\\G_{n_v}^\top
\end{bmatrix}
\begin{bmatrix}
        G_1\!\!&\!\!\dots\!\!&\!\!G_{n_v}
\end{bmatrix}.
\end{equation}
From conditions \eqref{eq:constr_satisfaction_1} and \eqref{eq:constr_satisfaction_2}, we obtain
\[
\begin{bmatrix}
    v_1^\top&\dots&v_{n_v}^\top
\end{bmatrix}
\begin{bmatrix}
        G_1^\top\\\vdots\\G_{n_v}^\top
\end{bmatrix}
\begin{bmatrix}
        G_1&\dots&G_{n_v}
\end{bmatrix}
\begin{bmatrix}
    v_1\\\vdots\\v_{n_v}
\end{bmatrix}\leq b^2,
\]
which is equivalent to $|\sum_{i=1}^{n_v}G_iv_i|\leq b$, completing the proof.
\hfill{}$\square$\smallskip\\
