Also, we introduce the following lemma, useful to characterize robustly positive invariant sets of $\delta$ISS systems.
\begin{lemma}\label{lem:RPI_set}
    Consider a variable $v\in\R^{n_v}$. If there exist a scalar $\gamma\in\R_+$ and matrices $P,Q_x\in\mathbb{S}_+^{n_v}$ such that $Q_x- P/\gamma\succeq0$ and, for all $v\in\mathcal{E}(P/\gamma)$, it holds
    \begin{equation}\label{eq:quadratic_dISS_function}
    \norm{v^+}^2_P-\norm{v}^2_P\leq -\norm{v}^2_{Q_x}+1,
    \end{equation}
    then $\mathcal{E}(P/\gamma)$ is forward invariant for the dynamics of $v$, i.e., $v\in\mathcal{E}(P/\gamma)$ implies $v^+\in\mathcal{E}(P/\gamma)$.\hfill{}$\square$
\end{lemma}
%
\textbf{Proof of Lemma \ref{lem:RPI_set}}.
%Since $w\in\mathcal{E}(Q_w^0)$ and $Q_w\preceq Q_w^0$, it follows that \[\norm{w}_{Q_w}^2\leq\norm{w}_{Q_w^0}^2\leq1.\] 
%Using this in \eqref{eq:quadratic_dISS_function} implies that 
%\begin{equation}\label{eq:quadratic_dISS_function_2}  
%\|x^+-\tilde x^+\|^2_{P}-\|x-\tilde x\|^2_{P}\leq-\norm{x-\tilde x}^2_{Q_{x}}+1.
%\end{equation}
Observe that $Q_x\succeq P/\gamma$
    implies $\mathcal{E}(Q_{x})\subseteq\mathcal{E}(P/\gamma)$.
    First of all, if $v\in\mathcal E(P/\gamma)\backslash\mathcal E(Q_{x})$, we have $\norm{v}_{Q_{x}}^2\geq 1$. Thus, from \eqref{eq:quadratic_dISS_function}, it follows that $\norm{v^+}^2_{P}\leq\norm{v}^2_{P}\leq\gamma$.
    On the other hand, if $v\in\mathcal E(Q_{x})$, $Q_x\succeq P/\gamma$ implies $\norm{v}^2_{Q_{x}}\geq\frac{1}{\gamma}\norm{v}^2_{P}$. Combining this with \eqref{eq:quadratic_dISS_function}, we obtain
    \begin{equation*}
        \begin{aligned}
        \norm{v^+}^2_{P}&\leq\norm{v}^2_{P}-\frac{1}{\gamma}\norm{v}_{P}^2+1\\
            &=\left(\cfrac{\gamma-1}{\gamma}\right)\norm{v}_{P}^2+1\\
            &=(\gamma-1)\norm{v}_{Q_{x}}^2+1\leq\gamma, 
        \end{aligned}
    \end{equation*}
    Therefore, $v^+\in\mathcal{E}(P/\gamma)$ as claimed.
\hfill{}$\square$
