\begin{lemma}\label{lem:Kunction_upperbound}
    Given a function $\gamma\in\mathcal{K}$,  the following inequality holds
    \begin{equation}\label{eq:Kunction_upperbound}        
    \gamma(s_1+s_2)\leq\gamma(2s_1)+\gamma(2s_2),
    \end{equation}
    for all $s_1,s_2\in\R_{\geq0}$.
    \hfill{}$\square$
\end{lemma}
\textbf{Proof of Lemma \ref{lem:Kunction_upperbound}.}
    Consider two scalars $s_1,s_2\in\R_{\geq0}$. Since $s_1$ and $s_2$ are positive by assumption, it follows that $\gamma(2s_1)\geq0$ and $\gamma(2s_2) \geq 0$. Note that, if $s_1 \leq s_2$, then $s_1 + s_2 \leq 2s_2$, and therefore, by the monotonicity of class $\mathcal{K}$-functions, it follows that $\gamma(s_1 + s_2) \leq \gamma(2s_2)\leq\gamma(2s_1)+\gamma(2s_2)$. On the other hand, if $s_1 > s_2$, then $s_1 + s_2 \leq 2s_1$, and therefore $\gamma(s_1 + s_2) \leq \gamma(2s_1)\leq\gamma(2s_1)+\gamma(2s_2)$, therefore proving \eqref{eq:Kunction_upperbound}.        
\hfill{}$\square$
\smallskip\\
