\textbf{Proof of Lemma \ref{lem:sector_condition}.}
From the definition of function $q_i(v_i)=v_i-\sigma_i(v_i)$, we have that
\begin{equation}\label{eq:q_derivative}
\frac{\partial q_i(v_i)}{\partial v_i}=\frac{\partial}{\partial v_i}(v_i-\sigma_i(v_i))=1-\frac{\partial \sigma_i(v_i)}{\partial v_i}.
\end{equation}
In view of Assumption~\ref{ass:sigmoid_function},
\[0< \frac{\partial \sigma_i(v_i)}{\partial v_i}\leq 1,\]  
and $\partial \sigma_i(v_i)/\partial v_i=1$ only for $v_i=0$.
Consequently, from \eqref{eq:q_derivative}, the derivative of $q_i(v_i)$  with respect to $v_i$ is also bounded, giving
\begin{equation}\label{eq:q_derivative_global}
0\leq\frac{\partial q_i(v_i)}{\partial v_i}<1,
\end{equation}
and $\partial q_i(v_i)/\partial v_i=0$ only for $v_i=0$.
Condition \eqref{eq:q_derivative_global} implies that $q_i(\cdot)$ is monotonically increasing and Lipschitz continuous with unitary Lipschitz constant.

Since  $q_i(\cdot)$ is continuous and differentiable, in view of the mean value theorem, for all $(v_i,v_i+\Delta v_i)\in\R^2$, there exists a scalar $v_i^\star$ such that $v_i^\star\in[v_i,v_i+\Delta v_i]$ if $\Delta v_i\geq0$, or $v_i^\star\in[v_i+\Delta v_i,v_i]$ if $\Delta v_i<0$,
such that
\begin{equation}\label{eq:Lagrange_theorem}
\Delta q_i=q_i(v_i+\Delta v_i)-q_i(v_i)=\delta q_i(v_i^\star)\Delta v_i,
\end{equation}
where $\delta q_i(v_i^\star)=\frac{\partial{q_i(v_i)}}{\partial{v_i}}|_{v_i=v_i^\star}$.\\ 
This implies that
\begin{equation*}
    \Delta q_i(\Delta v_i-h_i\Delta q_i)=\delta q_i(v_i^\star)(1-h_i\delta q_i(v_i^\star))\Delta v_i^2.
\end{equation*}
Recall that, in view of Assumption~\ref{ass:sigmoid_function}, for $v_i^\star<0$ (resp. $v_i^\star>0$), $\frac{\partial^2 q_i(v_i)}{\partial v_i^2}<0$ (resp. $\frac{\partial^2 q_i(v_i)}{\partial v_i^2}>0$), meaning that $\delta q_i(v_i^\star)$ is strictly decreasing (resp. increasing) for $v_i^\star<0$ (resp. $v_i^\star>0$). Also, $\delta q_i(v_i^\star)\to1$ both as $v_i^\star\to+\infty$ and $v_i^\star\to-\infty$, and $\delta q_i(0)=0$.\\
Moreover, from \eqref{eq:q_derivative_global}, it holds that $0\leq\delta q_i(v_i^\star)\leq1$, $\forall v_i^\star\in\R$.
In  view of this, it follows that
\begin{itemize}
    \item for $h_i=1$, $1-h_i\delta q_i(v_i^\star)\geq0$, and $\delta q_i(v_i^\star)\geq 0$, $\forall v_i^\star\in\R$;
    \item for all $h_i>1$, $\exists\tilde v_i\in\R$ sufficiently small such that $1-h_i\delta q_i(v_i^\star)\geq 0$, i.e. $\delta q_i(v_i^\star)\leq\frac{1}{h_i}$, for any $v_i^\star\in[-\tilde v_i,\tilde v_i]$.
\end{itemize}
In particular, define
\begin{equation}\label{opt:locality_constraints}
    \begin{aligned}
    \bar v_i(h_i)=&\max_{\tilde v_i}\tilde v_i\\
    &\text{subject to}\\
    &\delta q_i(v_i^\star)\leq\frac{1}{h_i}, \forall v_i^\star\in[-\tilde v_i,\tilde v_i].
    \end{aligned}
    \end{equation} 
In view of the continuity of $\delta q_i(v_i^\star)$, $\bar v_i(h_i)$ is also continuous. Also, since $0\leq\delta q_i(v_i^\star)\leq 1$ $\forall v_i^\star$, and $\delta q_i(v_i^\star)=0$ only in $v_i^\star=0$, then $\bar v_i(h_i)\to+\infty$ as $h_i\to1^+$, and $\bar v_i(h_i)\to0^+$ as $h_i\to+\infty$.\hfill{}$\square$\smallskip\\
