\textbf{Proof of Theorem \ref{th:dISS_observer}.}
In view of \eqref{eq:sector_inequality} and Lemma \ref{lem:sector_condition}, for any $H_o\in\mathbb{D^\nu_+}$ with $H_o\succeq I_\nu$, if $v,\hat{v}\in \mathcal{V}(H_o)$ then, for all $S_o\in\mathbb{D^\nu_+}$
\begin{equation}\label{eq:sector_inequality_obs1}
    \Delta q(v,\hat{v})^\top S_o(\Delta v-H_o\Delta q(v,\hat{v}))\geq 0
\end{equation}
where $\Delta v=v-\hat{v}=(\tilde{A}-\tilde{L}C)e+\tilde{D}w-\tilde{L}\eta$. For compactness we denote $\Delta q_o=\Delta q(v,\hat{v})$, $w_o=[w^\top,\eta^\top]^\top$, and $\phi_o=[e^\top,\Delta q_o^\top,w_o^\top]^\top$ and we rewrite \eqref{eq:sector_inequality_obs1} as
\begin{multline}\label{eq:sector_inequality_obs2}
    \Delta q_o^\top S_o((\tilde{A}-\tilde{L}C)e+\begin{bmatrix}
      \tilde{D}&  -\tilde{L}
    \end{bmatrix}w_o-H_o\Delta q_o)\\=
    \Delta q_o^\top S_o(\tilde{A}_Le+\tilde{D}_ow_o-H_o\Delta q_o)\geq 0
\end{multline}
where $\tilde{A}_L=\tilde{A}-\tilde{L}C$ and $\tilde{D}_o=\begin{bmatrix}
      \tilde{D}&  -\tilde{L}
    \end{bmatrix}$. The latter can be rewritten as
%
\begin{equation}\label{eq:sector_condition_quadratic_obs}
    \phi_o^\top\begin{bmatrix}
    0& \tilde{A}_L^\top S_o &0\\
    S_o\tilde{A}_L&-2S_oH_o& S_o\tilde D_o\\
    0&\tilde D_o^\top S_o&0
\end{bmatrix}\phi_o\geq0.
\end{equation}
 Defining ${A}_L=A-LC$, the dynamics of $e$ is  \begin{equation}\label{eq:error_dynamics_observer}
    \begin{aligned}
    e^+&=x^+-\hat{x}^+={A}_Le+D w-L \eta+B_q \Delta q_o\\
    &=\begin{bmatrix}
        {A}_L&B_q&D_o
    \end{bmatrix}\phi_o,
    \end{aligned}
    \end{equation}
    %
    where $D_o=\begin{bmatrix}D&L\end{bmatrix}$.
Define $V_o(x,\hat{x})=\norm{e}_{P_o}^2$, where $P_o\in\mathbb{S}^n_+$. We can write
\begin{equation}\label{eq:Lyapunov_function_increment_observer}
\begin{aligned}
&\Delta V_o
=V_o(x(k+1),\hat x(k+1))-V_o(x(k),\hat x(k))\\
&=\phi_o^\top\left(\begin{bmatrix}
        {A}_L^\top\\B_q^\top\\D_o^\top
    \end{bmatrix}P_o\begin{bmatrix}
        {A}_L&B_q&D_o
    \end{bmatrix}-\begin{bmatrix}
        P_o&0&0\\0&0&0
        \\0&0&0
    \end{bmatrix}\right)\phi_o.
\end{aligned}
\end{equation}
From \eqref{eq:sector_condition_quadratic_obs} and \eqref{eq:error_dynamics_observer}, if $v,\hat{v}\in \mathcal{V}(H_o)$ it is possible to guarantee that
\begin{equation}\label{eq:dissipation_form_function_observer}
    \Delta V_o\leq-\norm{e}^2_{Q_{o,x}}+\norm{ w_o(k)}^2_{Q_{o,w_o}},
    \end{equation}
and, in view of Theorem \ref{th:local_dISS}, that the observer error dynamics are $\delta$ISS, by imposing
\begin{multline}\label{eq:dissipation_form_function_observer_2}
    \Delta V_o+\phi_o^\top\!\!\begin{bmatrix}
    0&\tilde{A}_L^\top S_o &0\\
    S_o\tilde{A}_L&-2S_oH_o& S_o\tilde D_o\\
    0&\tilde D_o^\top S_o&0
\end{bmatrix}\!\!\phi_o\\\!\leq\!\!-\norm{e}^2_{Q_{o,x}}+\norm{w_o}^2_{Q_{o,w_o}}\!.
\end{multline}
Using \eqref{eq:Lyapunov_function_increment_observer}, condition \eqref{eq:dissipation_form_function_observer_2} is satisfied by imposing
\begin{multline}\label{eq:dISS_condition_2_obs_zero}
\begin{bmatrix}
        {A}_L^\top\\B_q^\top\\D_o^\top
    \end{bmatrix}P_o\begin{bmatrix}
        {A}_L&B_q&D_o
    \end{bmatrix}\\-
\begin{bmatrix}
    P_o-Q_{o,x}&-\tilde A_L^\top S_o &0\\
    -S_o\tilde A_L&2S_oH_o& -S_o\tilde D_o\\
    0&-\tilde D_o^\top S_o&Q_{o,w_o}
    \end{bmatrix}
    \preceq 0
\end{multline}
which, in view of the Schur complement, is equivalent to
\begin{multline}\label{eq:dISS_condition_2_obs}
\begin{bmatrix}
    P_o-Q_{o,x}&-\tilde A_L^\top S_o &0&A_L^\top P_o\\
    -S_o\tilde A_L&2S_oH_o& -S_o\tilde D_o&B_q^\top P_o\\
    0&-\tilde D_o^\top S_o&Q_{o,w_o}&D_o^\top P_o\\
    P_oA_L&P_oB_q&P_oD_o&P_o
    \end{bmatrix}
    \succeq 0.
\end{multline}
%Recalling that $A_L=A-LC$ and $\tilde A_L=\tilde A-\tilde LC$,
Substituting $N=P_oL$ and $\tilde N=S_o\tilde L$ into \eqref{eq:dISS_condition_2_obs}, yields condition \eqref{eq:dISS_condition_obs}.\smallskip\\
