\textbf{Proof of Proposition~\ref{prop:closed_loop_K_as_gain}.}
To prove Proposition~\ref{prop:closed_loop_K_as_gain}, note that under Assumptions~\ref{ass:disturbance} and \ref{ass:output_noise}, and assuming $e(0) \in \mathcal{E}(P_o / \gamma_o)$, Theorem~\ref{th:dISS_observer} implies the existence of a class $\mathcal{KL}$-function $\beta_o$ and class $\mathcal{K}_\infty$-functions $\gamma_{o,w}$ and $\gamma_{o,\eta}$ such that system~\eqref{eq:observer_dynamics} satisfies
%text
%\begin{multline*}
    $\norm{e(k)}\leq\beta_o(\norm{e(0)},k)        +\gamma_{o,w}(\max_{h\geq 0}\norm{w(h)})+\gamma_{o,\eta}(\max_{\eta\geq 0}\norm{\eta(h)})$.
%\end{multline*}
Following similar steps as in the proof of Lemma $3.8$ in \cite{jiang2001input}, it is possible to show that this condition implies the existence of a class $\mathcal{K}$-function $\gamma_{o}$ such that
\begin{multline}\label{eq:k_as_gain_obs}
    \overline{\lim}_{k \to+ \infty} \norm{e(k)}\leq\gamma_{o}(\overline{\lim}_{k \to+ \infty} \norm{w(k)})\\+\gamma_{o}(\overline{\lim}_{k \to+ \infty}\norm{\eta(k)}).
\end{multline}
Similarly, Theorem~\ref{th:dISS} guarantees the existence of functions $\beta_c\in\mathcal{KL}$ and $\gamma_{c,\eta},\gamma_{c,e}\in\mathcal{K}_\infty$, such that system~\eqref{eq:closed_loop_observer} satisfies
%text
%\begin{multline*}
$    \norm{\hat x(k)-\bar x}\leq\beta_c(\norm{\hat x(k)-\bar x},k)        +\gamma_{c,\eta}(\max_{h\geq 0}\norm{\eta(h)})+\gamma_{c,e}(\max_{h\geq 0}\norm{e(h)}),$
%\end{multline*}
which implies the existence of a class $\mathcal{K}$-function $\gamma_{c}$ such that
\begin{multline}\label{eq:k_as_gain_control}
    \overline{\lim}_{k \to+ \infty} \norm{\hat x(k)-\bar x}\leq\gamma_{c}(\overline{\lim}_{k \to+ \infty} \norm{\eta(k)})\\+\gamma_{c}(\overline{\lim}_{k \to+ \infty}\norm{e(k)}).
\end{multline}
Noting that $\norm{x-\bar x}=\norm{\hat x-\bar x+e}\leq\norm{\hat x-\bar x}+\norm{e}$, and
using \eqref{eq:k_as_gain_obs} and \eqref{eq:k_as_gain_control}, yields
\begin{equation*}
    \begin{aligned}
        &\overline{\lim}_{k \to+ \infty} \norm{x(k)-\bar x}\\
        &\leq\overline{\lim}_{k \to+ \infty} \norm{\hat x(k)-\bar x}+\overline{\lim}_{k \to+ \infty} \norm{e(k)}\\
        &\leq\gamma_{c}(\overline{\lim}_{k \to+ \infty} \norm{\eta(k)})+\gamma_{c}(\overline{\lim}_{k \to+ \infty}\norm{e(k)})\\
        &\ \ +\overline{\lim}_{k \to+ \infty} \norm{e(k)}\\
        &\leq\gamma_{c}(\overline{\lim}_{k \to+ \infty} \norm{\eta(k)})+\gamma_{c}(\gamma_{o}(\overline{\lim}_{k \to+ \infty} \norm{w(k)})\\&\ \ +\gamma_{o}(\overline{\lim}_{k \to+ \infty}\norm{\eta(k)}))+\gamma_{o}(\overline{\lim}_{k \to+ \infty} \norm{w(k)})\\&\ \ +\gamma_{o}(\overline{\lim}_{k \to+ \infty}\norm{\eta(k)})\\
        &\leq \gamma_{c}(\overline{\lim}_{k \to+ \infty} \norm{\eta(k)})+\gamma_{co}(\overline{\lim}_{k \to+ \infty} \norm{w(k)})\\
        &\ \ +\gamma_{co}(\overline{\lim}_{k \to+ \infty}\norm{\eta(k)})+\gamma_{o}(\overline{\lim}_{k \to+ \infty}\norm{w(k)})\\&\ \ +\gamma_{o}(\overline{\lim}_{k \to+ \infty} \norm{\eta(k)})).
    \end{aligned}
\end{equation*}
where, according to Lemma~\eqref{lem:Kunction_upperbound}, $\gamma_{co}(\cdot)=\gamma_c(2\gamma_o(\cdot))\in\mathcal{K}$.
Finally, by leveraging the super-additivity property of class $\mathcal{K}$-functions \cite{wiltz2024note}, it can be shown that there exist function $\gamma_w\in \mathcal{K}$ such that 
$\gamma_{co}(\overline{\lim}_{k \to + \infty} \|w(k)\|)+\gamma_{o}(\overline{\lim}_{k \to + \infty} \|w(k)\|) \leq \gamma_w(\overline{\lim}_{k \to + \infty} \|w(k)\|)$, and function $\gamma_\eta \in \mathcal{K}$ such that
$\gamma_{c}(\overline{\lim}_{k \to + \infty} \|\eta(k)\|) + \gamma_{co}(\overline{\lim}_{k \to + \infty} \|\eta(k)\|)) + \gamma_{o}(\overline{\lim}_{k \to + \infty} \|\eta(k)\|) \leq \gamma_\eta(\overline{\lim}_{k \to + \infty} \|\eta(k)\|)$, therefore proving \eqref{eq:closed_loop_K_as_gain}.
