% \vspace{-1em}
\centerline{\includegraphics[width=.99\linewidth]{fig/MBDA.png}}
\captionsetup{justification=raggedright, singlelinecheck=false}
\caption{Structure of the proposed MBDA module.}
\label{mbda}
