\centerline{\includegraphics[width=.98\linewidth]{fig/DGCN.png}}
\captionsetup{justification=raggedright, singlelinecheck=false}
\caption{Structure of the proposed DGCN.}
\label{bgcn}
\end{figure}

\subsubsection{Bipartite GCO}
Since the $\bm{\Dot{A}}_{dag}$ is a block-diagonal matrix, applying GCO  on $\bm{\Dot{A}}_{dag}$ can be regarded as applying GCO on each $\bm{A}_{dag}^k$. Due to the special topology of $\bm{A}_{dag}^k$ as a sparse bipartite graph, we design a bipartite GCO (B-GCO) based on the Laplace matrix $\bm{L}_{dag}^k$ of the mDAG according to (\ref{degree}) and (\ref{laplace}). The features of the mDAG form a structure in non-Euclidean space, hence the features need to be mapped from the time domain into the frequency domain to achieve the convolution operation. The Fourier transform in the time domain is defined by the eigenvalue decomposition of the Laplace matrix \cite{ft}, i.e., 
\begin{align}
    \bm{L}_{dag}^k=\bm{U}\bm{\Lambda}\bm{U}^\top,
\end{align}
where the eigenvalues $\lambda_j$ denote the frequency and the eigenvectors $\bm{u}_j$ denote the Fourier modes, respectively. 

Regarding $\bm{x}$ as a signal in the mDAG, we can define the Fourier transform as $\breve{\bm{x}}={\rm FT}(\bm{x})=\bm{U}^\top\bm{x}$ and the inverse Fourier transform as $\bm{x}={\rm IFT}(\breve{\bm{x}})=\bm{U}\breve{\bm{x}}$. Therefore, the convolution between $\bm{x}$ and the convolution kernel $g$ can be represented as
\begin{align}
    g\ast\bm{x}={\rm IFT}[{\rm FT}(g)\cdot{\rm FT}(x)]=\bm{U}(\bm{U}^\top g\cdot\bm{U}^\top\bm{x})
\end{align}
where $\ast$ is the convolutional operator. Determine $g$ as a function of $\bm{L}_{dag}^k$, we can regard $\bm{U}^\top g$ as a function of the eigenvalues $g_\theta(\bm{\Lambda})={\rm diag}(\theta)$ parameterized by $\theta\in \mathbb{R}^{|\bm{x}|}$. Then, the graph convolution is transformed as
\begin{align}
    g_\theta\ast\bm{x}=\bm{U}g_\theta\bm{U}^\top\bm{x}.
    \label{ftconv}
\end{align}

The complexity of the convolution kernel in (\ref{ftconv}) can be extremely high since the eigenvalue decomposition requires $O(n^3)$ computation overhead on global information. A typical approach to decrease the computation complexity is to approximate (\ref{ftconv}) by truncated Chebyshev polynomials of the first order according to \cite{gcn}, i.e., 
\begin{equation}
\begin{aligned}
    g_\theta\ast \bm{x}
    &\approx\bm{U}(\mathop{\sum}\limits_{c=0}^1\beta_cT_c(\tilde{\bm{\Lambda}}))\bm{U}^\top\bm{x}
    =\mathop{\sum}\limits_{c=0}^1\beta_cT_c(\bm{U}\tilde{\bm{\Lambda}}\bm{U}^\top)\bm{x}\\
    &=\beta_0T_0(\tilde{\bm{L}}_{dag}^k)\bm{x}+\beta_1T_1(\tilde{\bm{L}}_{dag}^k)\bm{x}\\
    &=\beta_0\bm{x}+\beta_1(\bm{L}_{dag}^k-\bm{I}_N)\bm{x},
\end{aligned}
\end{equation}
where $T_c$ denotes the $c$-th item in the Chebyshev polynomials with $T_0(x)=1$ and $T_1(x)=x$, $\beta_c$ is the $c$-th Chebyshev coefficient, and $\tilde{\bm{\Lambda}}_d^k=\frac{2}{\lambda_{max}}\bm{\Lambda}_d^k-\bm{I}_N$ is scaled by the largest eigenvalue of $\bm{L}_d^k$. Inspired by \cite{mgc}, we define the hyper-parameter $\epsilon=-\beta_1>0$ and let $\beta_0 = \beta_1+1$, then we have the B-GCO of signal $x$ in the mDAG as
\begin{align}
    g_\theta\ast \bm{x}=(\bm{I}_N-\epsilon\bm{L}_{dag}^k)\bm{x}.
\end{align}

Subsequently, we extend the $g_\theta$ into a trainable B-GCO layer. In each B-GCO layer, we introduce a weight matrix for feature linear transformation, which serves as the trainable parameter. Specifically, in the $q$-th B-GCO layer, the feature matrix is processed by the GCO as
\begin{align}
    \bm{\dot{X}}_{gco}^q={\rm GCO}(\bm{\dot{X}}_{gco}^{q-1},\bm{\dot{A}}_{dag})
    =(\bm{I}_{KN}-\epsilon\bm{\dot{L}}_{dag})\bm{\dot{X}}_{gco}^{q-1}\bm{W}^q,
    \label{w}
\end{align}
where the Laplace matrix $\bm{\dot{L}}_{dag}$ is computed based on $\bm{\dot{A}}_{dag}$, and $\bm{W}^q$ is a layer-specific trainable weight matrix.

\subsubsection{DGCN backbone}

As shown in the right part of Fig.\ref{bgcn}, a position normalization layer takes $\bm{\Dot{X}}_{in}$ as input and down-scales the features into the range of $(-1,1)$. Let $\bm{p}_c=\frac{1}{N}\sum_{i=1}^N\bm{p}_{i}(t_0)$ denote the center point of the USNET at time $t_0$, hence we can define the scale ratio $D=\mathop{\rm{max}}\limits_{i\in\mathcal{I}}\|\bm{p}_c-\bm{p}_i(t_0)\|$ is the maximum distance between nodes and $\bm{p}_c$. The normalized feature matrix as be calculated as
\begin{align}
    \bm{\Dot{X}}_{norm}=\frac{\bm{\Dot{X}}_{in}-\bm{p}_c^\top}{D+1}.
\end{align}

Next, the normalized feature matrix is sent into a single B-GCO layer, additionally with the ReLU activation function as the non-linear layer. The output feature matrix is 
\begin{align}
    \bm{\dot{X}}_{gco}^1={\rm ReLU}\left({\rm GCO}(\bm{\dot{X}}_{norm},\bm{\dot{A}}_{dag})\right).
\end{align}
Here, the feature dimension is extended from 2 to the hidden dimension $d_s$ by setting $\bm{W}^1$ as a 2-by-$d_s$ weight matrix.

Subsequently, the output feature matrix is processed by $L$ residual blocks. Each residual block consists of two B-GCO layers and two ReLU layers, plus a residual connection with $\bm{\dot{X}}_{gco}^1$ at the output. Therefore, the output feature matrix of the $l$-th residual block is
\begin{align}
    \bm{\dot{X}}_{block}^l=\left[{\rm ReLU}\left({\rm GCO}(\bm{\dot{X}}_{block}^{l-1},\bm{\dot{A}}_{dag})\right)\right]^2+\bm{\dot{X}}_{gco}^1.
\end{align}
The weight matrices in the residual block are all set as $d_s$-by-$d_s$ matrices. Particularly, we have $\bm{\dot{X}}_{gco}^1$ as the input of the first residual block. Note that dropouts \cite{dropout} can be added between two residual blocks
to increase the ability of generalization.

After $L$ residual blocks, the final B-GCO layer brings the feature dimension back to 2 with the weight matrix set as a $d_s$by-2 matrix. In addition, we introduce a tanh function to map the feature into the range of $(-1,1)$. Therefore, the DGCN has a total of $Q=2L+2$ GCO layers with the output
\begin{align}
    \bm{\dot{X}}_{gco}^Q={\rm tanh}\left({\rm GCO}(\bm{\dot{X}}_{block}^L,\bm{\dot{A}}_{dag})\right).
\end{align}

Finally, the output layer up-scales the feature matrix to the target position ranges. The final output position matrix of DGCN is calculated as
\begin{align}
    \hat{\bm{\Dot{X}}}_{gcn}=(D+1)\cdot(\bm{\dot{X}}_{gco}^Q+\bm{p}_c^\top).
\end{align}

\subsubsection{Loss function design}
Denote the loss function of the DGCN as $\mathcal{L}(\bm{\dot{X}}_{in},\mathcal{W})$, where $\bm{\dot{X}}_{in}$ is the input feature matrix and $\mathcal{W}=\{\bm{W}^1,\bm{W}^2,...,\bm{W}^Q\}$ is the set of layer weight matrices. 

Since the output of DGCN $\hat{\bm{\Dot{X}}}_{gcn}$ contains $K$ possible solutions according to (\ref{ksolution}), we can calculate a loss for each solution $\bm{\hat{X}}_{gcn}^k$ respectively. To transform the equality constraint (\ref{c2}) as a penalty component in the loss function, we rewrite the problem (P1) as
\begin{align}
    ({\rm P}1^\dagger):\quad \mathop{\rm min}\limits_{\bm{\hat{X}}_{gcn}^k}\quad & T_{rc}^k=\mathop{\rm max}\limits_{r_i\in\mathcal{I}_R}\frac{\|\bm{\hat{p}}_{r_i}^k-\bm{p}_{r_i}(t_0)\|}{v_{max}}
    \label{p2s}\\
    \quad {\rm s.t.}\quad & \hat{N}_S^k - 1 \leq 0,
\end{align}
where $T_{rc}$ is substituted by the recovery time $T_{rc}^k$ of the solution $\bm{\hat{X}}_{gcn}^k$, and $\hat{N}_S^k$ is the number of sub-nets in the remaining graph recovered by $\bm{\hat{X}}_{gcn}^k$. The equality constraint (\ref{c2}) is represented by the inequality $\hat{N}_S^k - 1 \leq 0$. Therefore, we can form a basic loss function of the $k$-th solution as
\begin{align}
    \mathcal{L}^k=T_{rc}^k+\lambda (\hat{N}_S^k - 1),
    \label{loss1}
\end{align}
where the Lagrange multiplier $\lambda$ is a positive constant.
Based on (\ref{loss1}), we define the total training loss of the DGCN as
\begin{align}
    \mathcal{L}_{total}=\mathop{\sum}\limits_{k=1}^K\mathcal{L}^k=\mathop{\sum}\limits_{k=1}^KT_{rc}^k+\lambda (\hat{N}_S^k - 1).
\end{align}

