\section{Proof of Proposition \ref{prop-c2}}
In the metric space of position matrices $\{\bm{X}_{gco}\}\subseteq\mathbb{R}^{N\times 2}$, we can represent the matrix form of B-GCO $\bm{X}_{gco}^{l+1}=g_\theta\ast \bm{X}_{gco}^l=(\bm{I}_N-\epsilon\bm{L}_{dag}^k)\bm{X}_{gco}^l$ as
\begin{align}
    \begin{pmatrix}
    x_{1}^{l+1} & y_{1}^{l+1} \\
    x_{2}^{l+1} & y_{2}^{l+1} \\
    \vdots & \vdots \\
    x_{N}^{l+1} & y_{N}^{l+1}
    \end{pmatrix}=\begin{pmatrix}
    l_{11}^k &\!\!\!\! l_{12}^k &\!\!\!\! \ldots &\!\!\!\! l_{1N}^k \\
    l_{21}^k &\!\!\!\! l_{22}^k &\!\!\!\! \ldots &\!\!\!\! l_{2N}^k \\
    \vdots &\!\!\!\! \vdots &\!\!\!\! \ddots &\!\!\!\! \vdots \\
    l_{N1}^k &\!\!\!\! l_{N2}^k &\!\!\!\! \ldots &\!\!\!\! l_{NN}^k
    \end{pmatrix}\begin{pmatrix}
    x_{1}^l & y_{1}^l \\
    x_{2}^l & y_{2}^l \\
    \vdots & \vdots \\
    x_{N}^l & y_{N}^l
    \end{pmatrix},
\end{align}
where $x_{i}$ and $y_{i}$ denote the coordinate component of $X$ and $Y$ axis from the position vector $\bm{p}_{i}$ of UAV $u_{i}$, and $l_{ij}^k$ is the element of $\bm{I}_N-\epsilon\bm{L}_{dag}^k$. Denote $d_{i}^k=\sum_{j=1}^Na_{ij}^k$ as the degree of node $u_{i}$ from the mDAG, we have
\begin{align}
\mathop{\sum}\limits_{i=1}^Nl_{ij}^k=1+\epsilon d_{i}^k-\epsilon\mathop{\sum}\limits_{j=1}^Na_{ij}^k=1.
\end{align}

The B-GCO can guarantee the invariance of column sums, i.e.,
\begin{align}
\mathop{\sum}\limits_{i=1}^Nx_{i}^{l+1}=\mathop{\sum}\limits_{i=1}^N\mathop{\sum}\limits_{j=1}^Nl_{ij}^kx_{j}^l=\mathop{\sum}\limits_{j=1}^N(x_{j}^l\mathop{\sum}\limits_{i=1}^Nl_{ij}^k)=\mathop{\sum}\limits_{j=1}^Nx_{j}^{l}\ ,
\end{align}
and the equality $\sum_{i=1}^Ny_{i}^{l+1}=\sum_{j=1}^Ny_{j}^l$ can be proved in the same manner.

Therefore, the B-GCO is closed for the metric space $\{\bm{X}_{gco}|\sum_{i=1}^Nx_{i}=X_{sum},\sum_{i=1}^Ny_{i}=Y_{sum}\}$, which means every position matrix $\bm{X}_{gco}^l$ share a same central location $\bm{p}_c=\frac{1}{N}\sum_{i=1}^N\bm{p}_{i}=[\frac{1}{N}X_{sum},\frac{1}{N}Y_{sum}]^\top$ from $\bm{X}_{gco}$.

Then we use the \textit{Contraction Mapping Principle} to prove the B-GCO is a contraction operation and the position matrix $\bm{X}_{gco}$ is convergent to a certain matrix $\bm{\bar{X}}_{gco}$. We first define the distance between two position matrices $\bm{X}_{gco}^a$ and $\bm{X}_{gco}^b$ as 
\begin{equation}
\begin{aligned}
    d(\bm{X}_{gco}^a,\bm{X}_{gco}^b)&=\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{|x_{i}^a-x_{i}^b|+|y_{i}^a-y_{i}^b|\}.
\end{aligned}
\end{equation}

The distance between the B-GCO of $\bm{X}_{gco}^a$ and $\bm{X}_{gco}^b$ is then calculated as
\begin{equation}
\begin{aligned}
    d(g_\theta\!\ast\!\bm{X}_{gco}^a,g_\theta\!\ast\!\bm{X}_{gco}^b)&=\|g_\theta\!\ast\!\bm{X}_{gco}^a-g_\theta\!\ast\!\bm{X}_{gco}^b\|_\infty\\
    &=\|(\bm{I}_N\!-\!\epsilon\bm{L}_{dag}^k)(\bm{X}_{gco}^a\!-\!\bm{X}_{gco}^b)\|_\infty.
\end{aligned}
\end{equation}

Since the infinity norm of matrix $\|\cdot\|\infty$ has the sub-multiplicative property, we can get
\begin{equation}
\begin{aligned}
    d(g_\theta\!\ast\!\bm{X}_{gco}^a,g_\theta\!\ast\!\bm{X}_{gco}^b)\leq \|\bm{I}_N\!-\!\epsilon\bm{L}_{dag}^k\|_\infty\|\bm{X}_{gco}^a\!-\!\bm{X}_{gco}^b\|_\infty&\\
    =\mathop{\rm max}\limits_{1\leq i\leq N}\{|1\!-\!\epsilon d_{i}^k|\!+\!\mathop{\sum}\limits_{j=1}^N\epsilon a_{ij}^k\}\|\bm{X}_{gco}^a\!-\!\bm{X}_{gco}^b\|_\infty&.
\end{aligned}
\end{equation}

Notice that $d_{ij}^k\leq\|\bm{A}_{dag}^k\|_\infty$, when $0<\epsilon\leq\frac{1}{\|\bm{A}_{dag}^k\|_\infty}$, there is
\begin{align}
    1-\epsilon d_{i}^k\geq1-\epsilon\|\bm{A}_{dag}^k\|_\infty\geq 1-\frac{1}{\|\bm{A}_{dag}^k\|_\infty}\|\bm{A}_{dag}^k\|_\infty=0,
\end{align}
hence we have
\begin{equation}
\begin{aligned}
    &d(g_\theta\ast \bm{X}_{gco}^a,g_\theta\ast \bm{X}_{gco}^b)\\
    &\leq\mathop{\rm max}\limits_{1\leq i\leq N}\{|1-\epsilon d_{i}^k|+\mathop{\sum}\limits_{j=1}^N\epsilon a_{ij}^k\}\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{1-\epsilon d_{i}^k+\mathop{\sum}\limits_{j=1}^N\epsilon a_{ij}^k\}\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{1-\epsilon \mathop{\sum}\limits_{j=1}^Na_{ij}^k+\mathop{\sum}\limits_{j=1}^N\epsilon a_{ij}^k\}\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{1\}\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty\\
    &=d(\bm{X}_{gco}^a,\bm{X}_{gco}^b).
    \label{dis}
\end{aligned}
\end{equation}

The condition for (\ref{dis}) to take the equal sign is
\begin{equation}
\begin{aligned}
    &\|(\bm{I}_N\!-\!\epsilon\bm{L}_{dag}^k)(\bm{X}_{gco}^a\!-\!\bm{X}_{gco}^b)\|_\infty\\=&
    \|\bm{I}_N\!-\!\epsilon\bm{L}_{dag}^k\|_\infty\|\bm{X}_{gco}^a\!-\!\bm{X}_{gco}^b\|_\infty.
\end{aligned}
\end{equation}
Given the proof of the sub-multiplicative property of $\|\cdot\|\infty$ as
\begin{equation}
\begin{aligned}
    &\|(\bm{I}_N-\epsilon\bm{L}_{dag}^k)(\bm{X}_{dag}^a-\bm{X}_{dag}^b)\|_\infty\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{|\mathop{\sum}\limits_{j=1}^Nl_{ij}^k(x_{j}^a-x_{j}^b)|+|\mathop{\sum}\limits_{j=1}^Nl_{ij}^k(y_{j}^a-y_{j}^b)|\}\\
    &\leq\mathop{\rm max}\limits_{1\leq i\leq N}\{\mathop{\sum}\limits_{j=1}^N|l_{ij}^k(x_{j}^a-x_{j}^b)|+\mathop{\sum}\limits_{j=1}^N|l_{ij}^k(y_{j}^a-y_{j}^b)|\}\\
    &=\mathop{\rm max}\limits_{1\leq i\leq N}\{\mathop{\sum}\limits_{j=1}^N|l_{ij}^k|\cdot(|x_{j}^a-x_{j}^b|+|y_{j}^a-y_{j}^b|)\}\\
    &\leq \mathop{\rm max}\limits_{1\leq i\leq N}\mathop{\sum}\limits_{j=1}^N|l_{ij}^k|\cdot(\mathop{\rm max}\limits_{1\leq j\leq N}\{|x_{j}^a-x_{j}^b|+|y_{j}^a-y_{j}^b|\})\\
    &=\|\bm{I}_N-\epsilon\bm{L}_{dag}^k\|_\infty\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty.
    \label{pf}
\end{aligned}
\end{equation}
we can see that inequality (\ref{pf}) is scaled for twice. The first scaling is based on the triangle inequality, hence the condition to take the equal sign is $l_{ij}^k(x_{j}^a-x_{j}^b)\geq0$ and $l_{ij}^k(y_{j}^a-y_{j}^b)\geq0$ for every $1\leq j\leq N$. Since $l_{ij}^k$ is always non-negative when $0<\epsilon\leq\frac{1}{\|\bm{A}_{dag}^k\|_\infty}$, i.e.,
\begin{equation}
\begin{aligned}
l_{ij}^k=
\left\{ 
    \begin{array}{lc}
    1-\epsilon d_{i}^k\geq 0,&i=j;\\
    \epsilon a_{ij}^k\geq 0,&i\neq j,
    \end{array}
\right.
\end{aligned}
\end{equation}
we can get the first scaling to be an equality requires
\begin{align}
\left\{ 
    \begin{array}{lc}
    x_{j}^a-x_{j}^b\geq0\\
    y_{j}^a-y_{j}^b\geq0
    \end{array}
\right.1\leq j\leq N.
\label{c1}
\end{align}

The condition for the second scaling to be equal is 
\begin{align}
    |x_{j}^a-x_{j}^b|+|y_{j}^a-y_{j}^b|=\|\bm{X}_{gco}^a-\bm{X}_{gco}^b\|_\infty=C\  \text{for}\  \forall j,
\end{align}
where $C\in\mathbb{R}$ is a constant.

Assuming that the two position matrices $\bm{X}_{gco}^a,\bm{X}_{gco}^b\in\{\bm{X}_{gco}|\sum_{i=1}^Nx_{i}=X_{sum},\sum_{i=1}^Ny_{i}=Y_{sum}\}$, we can derive that
\begin{equation}
\begin{aligned}
    C&=\frac{1}{N}\mathop{\sum}\limits_{j=1}^N|x_{j}^a-x_{j}^b|+|y_{dj}^a-y_{j}^b| \\
    &=\frac{1}{N}\mathop{\sum}\limits_{j=1}^N(x_{j}^a-x_{j}^b+y_{j}^a-y_{j}^b) \\
    &=\frac{1}{N}(\mathop{\sum}\limits_{j=1}^Nx_{j}^a-\mathop{\sum}\limits_{j=1}^Nx_{j}^b+\mathop{\sum}\limits_{j=1}^Ny_{j}^a-\mathop{\sum}\limits_{j=1}^Ny_{j}^b) \\
    &=\frac{1}{N}(X_{sum}-X_{sum}+Y_{sum}-Y_{sum})\\
    &=0.
\end{aligned}
\end{equation}
This indicates that $x_{j}^a-x_{j}^b=0$ and $y_{j}^a-y_{j}^b=0$ for every $1\leq j\leq N$. Hence, (\ref{dis}) is an equality if and only if $\bm{X}_{gco}^a=\bm{X}_{gco}^b$, and we have
\begin{align}
    d(g_\theta\ast \bm{X}_{gco}^a,g_\theta\ast \bm{X}_{gco}^b)=d(\bm{X}_{gco}^a,\bm{X}_{gco}^b)=0.
\end{align}

At this point, we have proved that for $\forall\bm{X}_{gco}^a,\bm{X}_{gco}^b\in\{\bm{X}_{gco}|\sum_{i=1}^Nx_{i}=X_{sum},\sum_{i=1}^Ny_{i}=Y_{sum}\}$, the condition
\begin{align}
    d(g_\theta\ast \bm{X}_{gco}^a,g_\theta\ast \bm{X}_{gco}^b)\leq\alpha d(\bm{X}_{gco}^a,\bm{X}_{gco}^b)
\end{align}
always holds for $\alpha\in(0,1)$. This indicates that the B-GCO is a contraction operation when $0<\epsilon\leq\frac{1}{\|\bm{A}_{dag}^k\|_\infty}$, and there exists and only exists one position matrix $\bm{\bar{X}}_{gco}=[\bm{\bar{p}}_{1},\bm{\bar{p}}_{r_{2}},...,\bm{\bar{p}}_{N}]^\top$ such that
\begin{align}
    \bm{\bar{X}}_{gco}=(\bm{I}_N-\epsilon\bm{L}_{dag}^k)\bm{\bar{X}}_{gco}=\mathop{\rm lim}\limits_{l\rightarrow\infty}(\bm{I}_N-\epsilon\bm{L}_{dag}^k)^l\bm{X}_{gco},
\end{align}
which is also called the \textit{Banach point}. 

By eliminating the $\bm{\bar{X}}_d$ on both side, we can derive
\begin{align}
    \bm{L}_{dag}^k\bm{\bar{X}}_{gco}=\bm{L}_{dag}^k[\bm{\bar{x}},\bm{\bar{y}}]=\bm{0},
\end{align}
where $\bm{\bar{x}}$ and $\bm{\bar{y}}$ are the column vectors in $\bm{\bar{X}}_{gco}$. This indicates that $\bm{\bar{x}}$ and $\bm{\bar{y}}$ are eigenvectors of $\bm{L}_{dag}^k$ corresponding to the zero eigenvalue. Note that the number of zero eigenvalues of $\bm{L}_{dag}^k$ equals the number of sub-nets in the mDAG, and $S$ zero eigenvalues $\lambda_1=0,\lambda_2=0,...,\lambda_S=0$ correspond to $S$ orthogonal eigenvectors $\{\bm{u}_1,\bm{u}_2,...,\bm{u}_S\}$. Thereby, we can represent $\bm{\bar{x}}$ and $\bm{\bar{y}}$ as the linear combinations of $\bm{u}_i$, i.e.,
\begin{equation}
\begin{aligned}
    \left\{ 
    \begin{array}{lc}
    \bm{\bar{x}}_d=\mathop{\sum}\limits_{i=1}^S\alpha_i\bm{u}_i;\\
    \bm{\bar{y}}_d=\mathop{\sum}\limits_{i=1}^S\beta_i\bm{u}_i,
    \end{array}
\right.
\label{cm}
\end{aligned}
\end{equation}
where $\alpha_i,\beta_i\in\mathbb{R}$ are coefficients of the combinations.

When the mDAG is connected, the number of zero eigenvalues of $\bm{L}_{dag}^k$ equals 1. Note that the vector $\bm{1}_N$ must be a eigenvector of $\bm{L}_{dag}^k$ corresponding to the zero eigenvalue, since
\begin{equation}
\begin{aligned}
    \bm{L}_{dag}^k\bm{1}_N=\begin{pmatrix}
    d_{1}-\sum_{j=1}^Na_{1j}\\
    d_{2}-\sum_{j=1}^Na_{2j}\\
    \vdots\\
    d_{N}-\sum_{j=1}^Na_{Nj}
    \end{pmatrix}=\bm{0}=0\cdot\bm{1}_N.
\end{aligned}
\end{equation}

Based on (\ref{cm}), we can get $\bm{\bar{x}}=\alpha_1\bm{1}_N$ and $\bm{\bar{y}}=\beta_1\bm{1}_N$ with $\alpha_1,\beta_1\neq0$. Since $\bm{\bar{X}}_{gco}\in\{\bm{X}_{gco}|\sum_{i=1}^Nx_{i}=X_{sum},\sum_{i=1}^Ny_{i}=Y_{sum}\}$, we have
\begin{align}
    \mathop{\sum}\limits_{i=1}^Nx_{i}=\mathop{\sum}\limits_{i=1}^N\alpha_1
    \Rightarrow\alpha_1=\frac{1}{N}X_{sum},\\
    \mathop{\sum}\limits_{i=1}^Ny_{i}=\mathop{\sum}\limits_{i=1}^N\beta_1
    \Rightarrow\beta_1=\frac{1}{N}Y_{sum}.
\end{align}
Therefore, when the input dilated graph is connected with the feature matrix as $\bm{X}_{in}$, $\bm{\bar{X}}_{gco}\equiv[\bm{p}_c,\bm{p}_c,...,\bm{p}_c]^\top$ holds. This completes the proof.

\section{Proof of Proposition \ref{prop-cp}}
The DGCN consists of an input normalization layer, $Q$ B-GCO layers, $Q-1$ nonlinear activation layers, and an output upscale layer. Compared to other operations, the graph convolution within the B-GCO layers takes the most computational complexity. For each B-GCO layer, the GCO applies matrix multiplications for two times in (\ref{w}). The computational complexity of a single B-GCO layer is the sum of the complexities of matrix multiplications.

For the $q$-th B-GCO layer, the first multiplication is the GCO kernel $g_\theta=\bm{I}_{KN}-\epsilon\bm{\dot{L}}_{dag}$, shaped ${KN\times KN}$, multiplying with the feature matrix $\bm{\dot{X}}_{gco}^{q-1}$ with shape of ${KN\times d_{in}^q}$, where $d_{in}^q$ is the input dimension of the $q$-th layer. Notice that the GCO kernel is a block-diagonal matrix calculated by $\bm{\dot{A}}_{dag}$, and each $\bm{A}_{dag}^k$ has at least $\frac{1}{2}N^2$ zero elements according to (\ref{Hadamard}). Therefore, the GCO kernel is a sparse matrix, as its ratio of the total number of non-zero elements to the total number of all elements in the matrix is
\begin{align}
    \eta \leq \frac{K\cdot\frac{1}{2}N^2}{KN\cdot KN}=\frac{1}{2K}.
\end{align}
Therefore, the computational complexity of the first multiplication is $\mathcal{O}\left(\text{nnz}(\bm{I}_{KN}\!-\!\epsilon\bm{\dot{L}}_{dag})\cdot d_{in}^q\right)$. 

The number of non-zero elements in the B-GCO kernel is the sum of the numbers of non-zero elements in each branch with $\bm{A}_{dag}^k$. Let's first analyze the 1-hop branch. The element $a_{r_id_j}^1=1$ in $\bm{A}_{dag}^1$ indicates that the remaining node $u_{r_i}$ and the destroyed nodes $u_{d_j}$ established a communication in the original USNET. Assuming that $N$ nodes are randomly distributed within a $D\times D$ area, the node degree follows a Poisson distribution with an average degree $\bar{d}$. Denote $p=N_D/N$ as the damage ratio, the number of communication links between the remaining nodes and destroyed nodes is represented as
\begin{equation}
\begin{aligned}
    \text{nnz}(\bm{A}_{in,r_id_j}^1)=&N_R\cdot \bar{d}_R\\=&(1-p)N\cdot p\bar{d}\\=&p(1-p)\pi d_{tr}^2\rho N,
\end{aligned}
\end{equation}
where $d_{tr}$ is the maximum communication range determined by (\ref{dtr}), $\rho=N/D^2$ is the node density. Therefore, the number of non-zero elements in $\bm{A}_{dag}^1$ is $\text{nnz}(\bm{A}_{dag}^k)=2p(1-p)\pi d_{tr}^2\rho N$ based on (\ref{Hadamard}). For the $k$-hop branch, the node degree still follows the Poisson distribution with the mean as $k\bar{d}$, hence we have $\text{nnz}(\bm{A}_{dag}^k)=k\cdot\text{nnz}(\bm{A}_{dag}^1)$. Since $\text{nnz}(\bm{I}_N\!-\!\epsilon\bm{L}_{dag}^k)=\text{nnz}(\bm{A}_{dag}^k)\!+\!N$, we have the number of non-zero elements in the B-GCO kernel as
\begin{equation}
\begin{aligned}
    \text{nnz}(\bm{I}_N\!-\!\epsilon\bm{\dot{L}}_{dag})=&\mathop{\sum}\limits_{k=1}^K\text{nnz}(\bm{A}_{dag}^k)+KN\\=&\mathop{\sum}\limits_{k=1}^K k\cdot 2p(1-p)\pi d_{tr}^2\rho N+KN\\
    =&p(1-p)\pi d_{tr}^2\rho K(K-1)N+KN.
\end{aligned}
\end{equation}

The second multiplication in the $q$-th layer is the middle matrix with shape $KN\times d_{in}^q$ multiplying with the weight matrix $\bm{W}^q$, shaped $d_{in}^q\times d_{out}^q$. The computational complexity of the second multiplication is $\mathcal{O}\left(KNd_{in}^qd_{out}^q\right)$. Therefore, the complexity of the $q$-th layer is $\mathcal{O}\left(\text{nnz}(\bm{I}_{KN}\!-\!\epsilon\bm{\dot{L}}_{dag})\!\cdot\! d_{in}^q\!+\!KNd_{in}^qd_{out}^q\right)$.

The total complexity of DGCN is the sum of the B-GCO layers, i.e.,
\begin{equation}
\begin{aligned}
&\mathcal{O}\left(\mathop{\sum}\limits_{q=1}^Q\text{nnz}(\bm{I}_{KN}\!-\!\epsilon\bm{\dot{L}}_{dag})\cdot d_{in}^q\!+\!KNd_{in}^qd_{out}^q\right)\\
=&\mathcal{O}\!\left(\mathop{\sum}\limits_{q=1}^Q[p(1\!-\!p)\pi d_{tr}^2\rho K(K\!-\!1)N\!+\!K\!N]d_{in}^q\!+\!K\!Nd_{in}^qd_{out}^q\!\right)\\
=&\mathcal{O}\left(KN\mathop{\sum}\limits_{q=1}^Q[p(1\!-\!p)\pi d_{tr}^2\rho(K\!-\!1)\!+\!1\!+\!d_{out}^q]d_{in}^q\right).
\end{aligned}
\end{equation}
This completes the proof.
