\section{Introduction}
Deploying \emph{deep neural networks} (DNNs) at the \emph{edge devices} demands high performance per watt under limited on-chip memory and power budgets. \emph{FPGAs} excel here by enabling customized parallelism, bitwidths, and memory hierarchies, achieving energy-efficient throughput compared to CPUs or GPUs~\cite{Umuroglu2017, Blott2018}. However, realizing these benefits requires \textbf{(1)~careful dataflow selection} to maximize on-chip reuse of weights and activations, and \textbf{(2)~optimal tiling/blocking} to match data shapes to limited BRAM/URAM/HBM.

In this paper, we:
\begin{enumerate}
    \item Present an expanded taxonomy of four \emph{canonical dataflow styles} for DNN accelerators on FPGAs (Section~\ref{sec:dataflow-taxonomy}).
    \item Compare \emph{analytical frameworks} (MAESTRO vs.~Timeloop) for data-centric modeling (Section~\ref{sec:frameworks}).
    \item Examine tiling, loop unrolling, pipelining, and multi-level buffering in detail (Section~\ref{sec:tiling}).
    \item Survey four case studies---FINN, FINN-R, FlightLLM, SSR---with a unified quantitative comparison (Section~\ref{sec:casestudies}).
    \item Assess design automation approaches (HLS vs.~DSL vs.~RTL) and highlight key productivity trade-offs (Section~\ref{sec:design-automation}).
    \item Conclude with \textbf{Future Directions} and a succinct \textbf{Conclusion} (Sections~\ref{sec:future}--\ref{sec:conclusion}).
\end{enumerate}

Readers seeking broad background on DNN architectures are referred to~\cite{Chen2016}. Our focus is on \emph{edge-tier FPGA} designs, from binarized CNNs to large language models.

%-------------------------------------------
\section{Dataflow Taxonomy}
\label{sec:dataflow-taxonomy}
Dataflow defines how the nested loops of a DNN layer (over input channels, output channels, spatial axes) are mapped onto hardware PEs and on-chip memory~\cite{Kwon2019}. We present four canonical styles below, each with a short pseudo-code or snippet, a small block diagram, and an example FPGA design.

%-------------------------------------------
\subsection{Weight-Stationary (WS)}
\label{sec:ws}
\textbf{Definition:} In Weight-Stationary dataflow, each \emph{PE} keeps its filter weights locally, and partial sums / activations stream through. Once weights are loaded, they remain `stationary` on-chip as inputs are cycled across them.

\begin{algorithm}
\caption{Weight-Stationary Dataflow}
\begin{algorithmic}[1]
\ForAll{tiles of input activations}
    \State Load tile into local buffer
    \ForAll{PE in array}
        \State \textit{partial\_sum} $\gets$ 0
        \ForAll{elements in tile}
            \State \textit{partial\_sum} $\gets$ \textit{partial\_sum} $+$ weight[PE] $\times$ activation[element]
        \EndFor
        \State output[PE] $\gets$ \textit{partial\_sum}
    \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

\textbf{Diagram:}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.6\linewidth]{ws.jpg}
    \caption{Weight-Stationary dataflow}
    \label{fig:enter-label}
\end{figure}

\textbf{Example FPGA Accelerator:}
Many systolic-array-like designs use WS. For instance, Google’s TPU v1 had a weight-stationary strategy in its 2D systolic array (though it is an ASIC). On FPGAs, some \emph{matrix-multiply} IP cores or HLS-based designs pin weights in BRAM to minimize re-fetching~\cite{Umuroglu2017}.

%-------------------------------------------
\subsection{Output-Stationary (OS)}
\label{sec:os}
\textbf{Definition:} In Output-Stationary, partial sums for a specific output element (or a small group of output channels) remain in local PE registers or buffers until all input channels are processed, after which the final result is written back to memory.

\begin{algorithm}[h]
\caption{Output Stationary GEMV-like Dataflow}
\begin{algorithmic}[1]
\For{$\text{out\_ch} \gets 0$ \textbf{to} Out}
    \State $\text{partial\_sum}[\text{out\_ch}] \gets 0$
\EndFor
\For{$\text{in\_ch} \gets 0$ \textbf{to} In}
    \For{$\text{out\_ch} \gets 0$ \textbf{to} Out}
        \State $\text{partial\_sum}[\text{out\_ch}] \gets \text{partial\_sum}[\text{out\_ch}] + \text{weight}[\text{out\_ch}, \text{in\_ch}] \times \text{input}[\text{in\_ch}]$
    \EndFor
\EndFor
\State \textbf{Write} $\text{partial\_sum}[]$ \textbf{to memory}
\end{algorithmic}
\end{algorithm}

\textbf{Diagram:}
\begin{figure}[h]
    \centering
    \includegraphics[width=0.6\linewidth]{os.jpg}
    \caption{Output-Stationary dataflow}
    \label{fig:enter-label}
\end{figure}

\textbf{Example FPGA Accelerator:}
Some earlier FPGA CNN pipelines used OS by accumulating the result of one output pixel in local registers. ShiDianNao (an ASIC) also exemplifies OS, streaming input data across PEs that keep partial sums in place. Eyeriss (v1) effectively uses an OS-like scheme for many conv layers~\cite{Chen2016}.

%-------------------------------------------
\newpage
\subsection{Row-Stationary (RS)}
\label{sec:rs}
\textbf{Definition:} Proposed in Eyeriss~\cite{Chen2016}, Row-Stationary keeps a \emph{strip} (or row) of activations and partial sums on each PE, so that all relevant filters can be reused across them. It balances weight and activation reuse.

\begin{algorithm}
\caption{Row-wise Tiled Convolution with PE-Level Accumulation}
\begin{algorithmic}[1]
\ForAll{rows $r$ in output}
    \State Load row $r$ of input tile into \textit{row\_buffer}
    \ForAll{filter sets}
        \ForAll{processing elements (PEs) in row $r$}
            \State $\text{partial\_sum}[PE] \gets \text{partial\_sum}[PE] + \text{MAC}(\text{row\_buffer}[PE], \text{filter\_chunk})$
        \EndFor
        \State \dots (e.g., update filter chunk or control)
    \EndFor
    \State Store completed row $r$ to output memory
\EndFor
\end{algorithmic}
\end{algorithm}

\textbf{Diagram:}
\begin{figure}[h]
    \centering
    \includegraphics[width=0.4\linewidth]{rs.jpg}
    \caption{Row-Stationary dataflow}
    \label{fig:enter-label}
\end{figure}

\textbf{Example FPGA Accelerator:}
Eyeriss was first demonstrated as an ASIC. On FPGAs, \emph{row-stationary} is less common but still relevant where the cost of local reuse for both weights and partial sums is balanced. Some HLS-based designs adapt RS to minimize DRAM access by storing partial sums row-by-row in BRAM.

%-------------------------------------------
\subsection{No-Local-Reuse (NLR)}
\label{sec:nlr}
\textbf{Definition:} Also called “global-buffer reuse.” PEs have minimal local storage; data (weights, activations, partial sums) is read from a large shared buffer (or high-bandwidth memory) each time. This simplifies control but increases buffer bandwidth demand.

\begin{algorithm}
\caption{Element-wise Output Dataflow with Global Buffer Access}
\begin{algorithmic}[1]
\ForAll{elements $e$ in output}
    \State $\text{partial\_sum} \gets 0$
    \For{$\text{in\_ch} \gets 0$ \textbf{to} $I$}
        \State $\text{partial\_sum} \gets \text{partial\_sum} + \text{global\_buffer.read}(\text{in\_ch}) \times \text{global\_buffer.read}(\text{weight\_idx})$
    \EndFor
    \State $\text{global\_buffer.write}(\text{output\_idx}, \text{partial\_sum})$
\EndFor
\end{algorithmic}
\end{algorithm}

\textbf{Diagram:}
\begin{figure}[h]
    \centering
    \includegraphics[width=0.4\linewidth]{nlr.jpg}
    \caption{No-Local-Reuse Dataflow}
    \label{fig:enter-label}
\end{figure}

\textbf{Example FPGA Accelerator:}
DianNao (ASIC) used a large eDRAM “global buffer,” with minimal caching in the PEs. On FPGAs, some streaming matrix-multiply cores adopt a “flat read” from HBM + immediate compute + write-back.

