\subsection{Proof of Theorem \ref{theorem:MRCapprox}} \label{theorem:MRCapprox_proof}

By applying the approximation $\mathbb{E} \left\{ \log_2 \left( 1 + {X}/{Y} \right) \right\} \approx \log_2 \left( 1 + {\mathbb{E} \{X\}}/{\mathbb{E} \{Y\}} \right)$ from \cite{YANG2020Uplink}, we can approximate $R_k^{\text{MR}}$ in \eqref{Eq:RateMR} $  \tilde{R}_k^{\text{MR}} =   \log_2\left(1+ \tilde{\gamma}_k^{\text{MR}}\right)$,
with
{\small
\begin{align} \label{Eq:SINRMR1}	 
	& \tilde{\gamma}_k^{\text{MR}} = \nonumber\\
	&\frac{\bar{P}_k \mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k}\right|^2\}}{\sum\limits_{\substack{i=1,\\i\neq k}}^K \bar{P}_i \rho_i\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{i}\right|^2\} + \mathbb{E}\{\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k}\}},
\end{align}}where $\mathbb{E}\{\alpha_i\} = \rho_i$. 
First, we derive the term $\mathbb{E} \{ \bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf T}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k} \}, \forall k$. 
It follows from  constraints \eqref{P0Cons2} and \eqref{P0Cons1} that 
$[\bm {\Phi}^{\sf H}\bm {\Phi}]_{jk} = \sum_{i = 1}^{N}[\bm {\Phi}]_{ij}[\bm {\Phi}]_{ik} = 0$, $\forall j, i, j \neq k$ and $[\bm {\Phi}^{\sf H}\bm {\Phi}]_{jj} = \sum_{i = 1}^{N}[\bm {\Phi}]_{ij} = [\bm{1}_N^{\sf T}\bm{\Phi}]_j, \forall j$, i.e.,
\begin{align} \label{Eq:proofA1}
    \bm {\Phi}^{\sf H}\bm {\Phi} = \text{diag}(\bm{1}_N^{\sf T}\bm{\Phi}).
\end{align}
By substituting \eqref{Eq:proofA1} into $\mathbb{E} \{ \bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf T}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k} \}$, it reduces to
\begin{align}\label{Eq:proofA3}
		\mathbb{E} \left\{ \bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf T}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k} \right\} = \sum_{\tilde{n} = 1}^{N_0} [\bm{1}_N^{\sf T}\bm{\Phi}]_{\tilde{n}} \mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^2 \}.
\end{align}
Then, we evaluate $\mathbb{E} \big\{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^2 \big\}$ in \eqref{Eq:proofA3}, which is given by
\begin{align} \label{Eq:proofA4}
  \mathbb{E} \big\{\| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}}) \|^2 \} 
  &\stackrel{(a)}{=} M \big(\xi_{\text{LoS},k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{LoS},k}(\mathbf{r}_{\tilde{n}}) + \beta_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}})\big) \nonumber\\
  &= M\beta_k(\mathbf{r}_{\tilde{n}}),
\end{align}
where $(a)$ holds due to the independence of the LoS and NLoS components, both of which have zero mean.
By substituting \eqref{Eq:proofA4} into \eqref{Eq:proofA3}, we obtain	
\begin{align} \label{Eq:eq:proofA10}
	\mathbb{E} \left\{ \bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf T}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k} \right\} =  M\bm{1}^{\sf T}_N\bm{\Phi}\bm{\bar{\beta}}_k.
\end{align}



Next, we derive the term $\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k}\right|^2\}$.
With \eqref{Eq:proofA1}, it reduces to
{\small
\begin{align}\label{Eq:proofA11}
    &\!\!\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k}\right|^2\} = 
	  \sum_{\tilde{n} = 1}^{N_0} [\bm{1}_N^{\sf T}\bm{\Phi}]_{\tilde{n}} \mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^4 \} \nonumber \\
    &\!\! + 2 \sum_{\tilde{n}=1}^{N_0} \sum_{\tilde{n}' > \tilde{n}}^{N_0}[\bm{1}_N^{\sf T}\bm{\Phi}]_{\tilde{n}}[\bm{1}_N^{\sf T}\bm{\Phi}]_{\tilde{n}'} \mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^2  \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'} )\|^2 \}.
\end{align}
}The term $\mathbb{E}\{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^2  \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'} )\|^2 \}$ in \eqref
{Eq:proofA11} is given by
\begin{align}\label{Eq:proofA12}
    \mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^2  \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'} )\|^2 \}
	& \stackrel{(b)}{=}  M^2\beta_k(\mathbf{r}_{\tilde{n}})\beta_k(\mathbf{r}_{\tilde{n}'}).
\end{align} 
where $(b)$ holds due to the independence of $\tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )$ and $\tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'} )$ for $\tilde{n} \neq \tilde{n}'$, as well as \eqref{Eq:proofA4}.
Moreover, the term $\mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^4 \}$ in \eqref{Eq:proofA11} is computed by expanding it as
{\small
\begin{align} \label{Eq:proofA13}
 &\mathbb{E} \{ \| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}} )\|^4 \} = M\beta^2_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}}) \nonumber\\
	& \hspace{2em}+ M^2 \beta^2_k(\mathbf{r}_{\tilde{n}}) + M2\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})\beta_{\text{LoS},k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}}).
\end{align} 
}
By substituting \eqref{Eq:proofA12} and \eqref{Eq:proofA13} into \eqref{Eq:proofA11}, $\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{k}\right|^2\}$ can be expressed as
\begin{align}\label{Eq:proofA21}
     M^2 \left( \bm{1}_N^{\sf T}\bm{\Phi} \bm{\bar \beta}_{k} \right)^2 + M \bm{1}_N^{\sf T}\bm{\Phi}(\bm{\bar{\beta}}_k^{\circ 2} \circ\bm{\bar{f}}_k),
\end{align}
where the auxiliary vector $\bm{\bar{f}}_k \in \mathbb{R}^{N_0}$ is defined as
\begin{align} \label{Eq:fdefine}
[\bm{\bar{f}}_k]_{\tilde{n}} &=  \frac{M(2[{\bar{\bm \kappa}_{k}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})+ 1)}{([{\bar{\bm \kappa}_{k}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})+1)^2}, \forall \tilde{n},
\end{align}
with 
$[{\bar{\bm \kappa}_{k}}]_{\tilde{n}} = \frac{\beta_{\text{LoS},k}(\mathbf{r}_{\tilde{n}})}{\beta_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}})}$, $1\leq \tilde{n}\leq N_0$.


Finally, we derive the term $\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{i}\right|^2\}$ for $i \neq k$, which is derived by substituting \eqref{Eq:proofA1} as
{\small 
\begin{align}\label{Eq:proofA22}
    \mathbb{E}\{|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{i}|^2\}& \stackrel{(c)}{=} \sum_{\tilde{n} = 1}^{N_0} [\bm{1}_N^{\sf T}\bm{\Phi}]_{\tilde{n}} \mathbb{E} \{ | \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}})^{\sf H} \tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}})|^2\},
\end{align}}where $(c)$ holds due to the independence of $\tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}})$ and $\tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}})$ for $k \neq i$, as well as their zero means,
resulting in  $\mathbb{E} \{ \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'})^{\sf H} \tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}'})\tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}'})^{\sf H} \tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}'})\} = 0$, $\forall \tilde{n}', \tilde{n}$, $\tilde{n}' \neq \tilde{n}$.
By expanding the squared norm of $\tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}})^{\sf H} \tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}})$ in \eqref{Eq:proofA22} and removing the terms with zero mean, we have
{\small
\begin{align}\label{Eq:proofA23}
	& \mathbb{E} \{| \tilde{\bm{h}}_{k}(\mathbf{r}_{\tilde{n}})^{\sf H} \tilde{\bm{h}}_{i}(\mathbf{r}_{\tilde{n}})|^2\} 
	 \!=\! \xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}}) \xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}})\beta_{\text{LoS},k}(\mathbf{r}_{\tilde{n}})\beta_{\text{LoS},i}(\mathbf{r}_{\tilde{n}})[\bm {\bar \varphi}_{k,i}]_{\tilde{n}} \nonumber\\
	& +  M \beta_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{NLoS},i}(\mathbf{r}_{\tilde{n}}) \! +\! M\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{LoS},k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{NLoS},i}(\mathbf{r}_{\tilde{n}}) \nonumber\\
	&+M\xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}}) \beta_{\text{NLoS},k}(\mathbf{r}_{\tilde{n}}) \beta_{\text{LoS},i}(\mathbf{r}_{\tilde{n}}) 
\end{align}
}By substituting \eqref{Eq:proofA23} into \eqref{Eq:proofA22}, the term $\mathbb{E}\{\left|\bm{\bar h}^{\sf H}_{k} (\bm {\Phi}^{\sf H}\bm {\Phi} \otimes \mathbf{I}_{M})\bm{\bar h}_{i}\right|^2\}$  can be expressed as
\begin{align}\label{Eq:proofA29}
	\bm{1}_N^{\sf T}\bm{\Phi} (\bm{\bar \beta}_{k}\circ\bm{\bar{\beta}}_i \circ (\bm{\bar{\varphi}}_{k,i}\circ \bm{\bar{g}}_{k,i} + \bm{\bar{q}}_{k,i})),
\end{align}
where the auxiliary vectors $\bm{\bar{g}}_{k,i} \in \mathbb{R}^{N_0}$ and $\bm{\bar{q}}_{k,i} \in \mathbb{R}^{N_0}$ are respectively defined as
\begin{align} 
&\!\!\![\bm{\bar{g}}_{k,i}]_{\tilde{n}} =  \frac{[{\bar{\bm \kappa}_{k}}]_{\tilde{n}}[{\bar{\bm \kappa}_{i}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})\xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}})}{([{\bar{\bm \kappa}_{k}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})+1)([{\bar{\bm \kappa}_{i}}]_{\tilde{n}}\xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}})+1)}, \forall \tilde{n}, \label{Eq:gdefine} \\
&\!\!\!	[\bm{\bar{q}}_{k,i}]_{\tilde{n}} =  \frac{ (1+[{\bar{\bm \kappa}_{k}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})+[{\bar{\bm \kappa}_{i}}]_{\tilde{n}}\xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}}))  M}{([{\bar{\bm \kappa}_{k}}]_{\tilde{n}}\xi_{\text{LoS}, k}(\mathbf{r}_{\tilde{n}})+1)([{\bar{\bm \kappa}_{i}}]_{\tilde{n}}\xi_{\text{LoS}, i}(\mathbf{r}_{\tilde{n}})+1)}, \forall \tilde{n}. \label{Eq:qdefine}
\end{align}


In summary, by substituting \eqref{Eq:eq:proofA10}, \eqref{Eq:proofA21}, and \eqref{Eq:proofA29} into \eqref{Eq:SINRMR1}, we obtain $\tilde{\gamma}_k^{\text{MR}}$ in \eqref{Neq:sinrMRapprox}.
This thus completes the proof.
