\section{Proof of Theorems} \label{sec:app_proof}

\subsection{Auxiliary lemmas}
Before stating the proofs of the mains theorems, here we state some lemmas that will be used later in the proofs.


\begin{lemma}\label{lemma:1}
Assume that $0<\alpha_m\leq \alpha_1,\alpha_2\leq \alpha_M<\infty$. Then, 
\[
({\alpha_m\over \alpha_M})^2 \frac{(\alpha_2-\alpha_1)^2}{2\alpha_1} \leq D_{\text{KL}}(\Poiss(\alpha_1)\|\Poiss(\alpha_2))\leq ({\alpha_M\over \alpha_m})^2 \frac{(\alpha_2-\alpha_1)^2}{2\alpha_1}.
\]
\end{lemma}

\begin{lemma}\label{lemma:chernoff}
Consider independent Poisson random variables $Y_1,\ldots,Y_n$, where $Y_i\sim\Poiss(\alpha_i)$. Consider $w_1,\ldots,w_n\in\R$. Let $\sigma_n^2=\sum_{i=1}^nw_i^2\alpha_i$ and $w_M \triangleq \max_{i\in\{1,\ldots,n\}} |w_i|$.
Then, for any $t \in [0, \frac{2 \sigma_n^2}{3w_M}]$,
\begin{align}
\P{\sum_{i=1}^nw_iY_i\geq \sum_{i=1}^nw_i\alpha_i+t}\leq  \exp(-{t^2\over 2(\sigma_n^2+w_Mt/3)}).
\end{align}
and
\begin{align}
\P{\sum_{i=1}^n w_i Y_i \leq \sum_{i=1}^n w_i \alpha_i - t}
\leq \exp(-\frac{t^2}{2(\sigma_n^2 + w_M t / 3)}).
\end{align}


\end{lemma}

\subsubsection{Proof of Lemma \ref{lemma:1}}
\begin{proof}
\begin{align}
D_{\text{KL}}(\Poiss(\alpha_1)\|\Poiss(\alpha_2))
&=  \alpha_2 - \alpha_1+ \alpha_1  \log \frac{\alpha_1}{\alpha_2}=   \alpha_2 - \alpha_1- \alpha_1  \log (1+\frac{\alpha_2-\alpha_1}{\alpha_1}).\label{eq:lemma-eq1}
\end{align}
Using the Taylor's theorem,
\begin{align}
\log(1+u)=u+f''(\alpha){u^2\over 2},\label{eq:lemma-eq2}
\end{align}
where $f(u)=\log(1+u)$ and $\alpha\in(0,u)$. Note that
\[
f''(u)=-{1\over (1+u)^2}.
\]
Letting $u=\frac{\alpha_2-\alpha_1}{\alpha_1}$, for $\alpha\in(0,u)$,
\begin{align}
-({\alpha_M\over \alpha_m})^2 \leq f''(\alpha)\leq -({\alpha_m\over \alpha_M})^2.\label{eq:lemma-eq3}
\end{align}
Combining \eqref{eq:lemma-eq1}, \eqref{eq:lemma-eq2} and \eqref{eq:lemma-eq3} yields the desired result. 

\end{proof}

\subsubsection{Proof of Lemma \ref{lemma:chernoff}}
\begin{proof}
Define 
\[
\mu_n = \E{\sum_{i=1}^nw_iY_i}=\sum_{i=1}^nw_i\alpha_i,
\]
and
\[
\sigma_n^2 = \E{(\sum_{i=1}^nw_i(Y_i-\alpha_i))^2}=\sum_{i=1}^nw_i^2\alpha_i.
\]

Consider $s>0$, then using the Chernoff bound, we have
\begin{align}
\P{\sum_{i=1}^nw_iY_i\geq \sum_{i=1}^nw_i\alpha_i+t}
&\leq \frac{\prod_{i=1}^n\E{\exp(sw_i(Y_i-\alpha_i))}}{\exp(st)}\nonumber\\
&= \exp(\sum_{i=1}^n(\alpha_i(\ex^{sw_i}-1-sw_i))-st).\label{eq:chernoff}
\end{align}
Note that for $u\in(-1,1)$, $\ex^u-1-u\leq {u^2\over 2(1-u/3)}$.  Assuming that $s\leq {1\over  w_M}$, then  $|sw_i|<1$, for all $i$. Therefore, 
\begin{align}
 \exp(\sum_{i=1}^n(\alpha_i(\ex^{sw_i}-1-sw_i))-st)
 &\leq \exp(\sum_{i=1}^n\alpha_i({(sw_i)^2\over 2(1-sw_i/3)})-st)\nonumber\\
 &\leq \exp(\sum_{i=1}^n\alpha_i({(sw_i)^2\over 2(1-sw_M/ 3)})-st)\nonumber\\
 &= \exp({s^2\sigma_n^2\over 2(1-sw_M/ 3)}-st).
\end{align}
Evaluating this bound at $s={t\over \sigma_n^2+w_Mt/3}$, since $1-sw_M/ 3={\sigma_n^2\over \sigma_n^2+w_Mt/3}$,   it follows that 
\begin{align}
{s^2\sigma_n^2\over 2(1-sw_M/ 3)}-st
&=-{st\over 2}= -{t^2\over 2(\sigma_n^2+w_Mt/3)}.
\end{align}

To derive the other bound, we can follow the same steps and apply Chernoff bound as done in \eqref{eq:chernoff} to get
\begin{align}
\P{\sum_{i=1}^n w_i Y_i \leq \mu_n - t}&\leq \exp(\sum_{i=1}^n \alpha_i (e^{-s w_i} - 1 + s w_i) - s t).
\end{align}
We now use the inequality for $u \in (-1, 1)$:
\[
e^{-u} - 1 + u \leq \frac{u^2}{2(1 + u/3)}.
\]
Assume $s \leq \frac{1}{w_M}$ so that $s |w_i| \leq 1$ for all $i$. Then:
\begin{align}
\sum_{i=1}^n \alpha_i (e^{-s w_i} - 1 + s w_i)
&\leq \sum_{i=1}^n \alpha_i \cdot \frac{(s w_i)^2}{2(1 + s w_i / 3)} \nonumber\\
&\leq \sum_{i=1}^n \alpha_i \cdot \frac{(s w_i)^2}{4/3} \nonumber\\
&= \frac{s^2 \sigma_n^2}{4/3}.
\end{align}
Hence,
\begin{align}
\P{\sum_{i=1}^n w_i Y_i \leq \mu_n - t}
&\leq \exp\left(\frac{s^2 \sigma_n^2}{4/3} - s t\right).
\end{align}
Setting \( s = \frac{3t}{2\sigma_n^2} \), which satisfies \( s \leq \frac{1}{w_M} \),
\begin{align}
\frac{s^2 \sigma_n^2}{4/3} - s t
= -\frac{3t^2}{4\sigma_n^2}
\le -{t^2\over 2(\sigma_n^2+w_Mt/3)}.
\end{align}
\end{proof}

