\subsection{Proof of Theorem \ref{thm:1}}\label{sec:additive-noise-recovery}
\begin{proof}


Recall that $\yv=\xv+\zv$, with $\zv$ is $\iid$ $\Nc(0,\sigma_z^2)$, and 
\[
   \xvh = \argmin_{\cv\in\Cc} \|\cv - \yv\|_2^2,\quad \quad  \xvt = \argmin_{\cv\in\Cc} \|\cv - \xv\|^2_2.
\]
Since both $\xvh,\xvt$ are in $\Cc$,
\begin{align}
    \|\hat{\xv} - \yv\|_2^2 &\leq \|\Tilde{\xv} - \yv\|_2^2 \\
    \|(\hat{\xv} - \xv) - \zv\|_2^2 &\leq \|(\Tilde{\xv} - \xv) - \zv\|_2^2 \\
    \|\hat{\xv} - \xv\|^2 - 2 \angles{\zv,\hat{\xv} - \xv} + \norm{\zv}^2 &\leq \|\Tilde{\xv} - \xv\|^2 - 2 \angles{\zv,\Tilde{\xv} - \xv} + \norm{\zv}^2 \\
    \|\hat{\xv} - \xv\|^2 &\leq \|\Tilde{\xv} - \xv\|^2 - 2 \angles{\zv,\Tilde{\xv} - \xv} + 2 \angles{\zv,\hat{\xv} - \xv} \\
    \|\hat{\xv} - \xv\|^2 &\leq \|\Tilde{\xv} - \xv\|^2 + 2 \abs*{\angles{\zv,\Tilde{\xv}-\xv}} + 2 \abs*{\angles{\zv,\hat{\xv}-\xv}}.
\end{align}
Let $\ev=\hat{\xv} - \xv$ denote the error of the compression-based estimate of ground truth $\xv$ from its noisy version $\yv$, and $\dv=\Tilde{\xv} - \xv$ denote the distortion from the compressing the ground truth $\xv$ with the compression code $\Cc$, then we have
\begin{align}
    \norm{\ev}^2 
    &\le \norm{\dv}^2 + 2\abs{\angles{\zv, \ev}} + 2\abs{\angles{\zv, \dv}}\\
    &=\norm{\dv}^2 + 2\norm{\ev}\abs*{\angles{\zv, \frac{\ev}{\norm{\ev}}}} + 2\norm{\dv}\abs*{\angles{\zv, \frac{\dv}{\norm{\dv}}}}\label{eq:error-bound-gaussian}.
\end{align}

For any possible reconstruction  $\cv\in\Cc$, we define error vector $\ev^{(\cv)}=\cv-\xv$. Given $t_1,t_2>0$, define event $\Ec_1$ and $\Ec_2$ as
\begin{align}
    \Ec_1 = \braces*{ \abs*{\sum^n_{i=1} z_i \frac{e_i^{(\cv)}}{\norm{\ev^{(\cv)}}}} \leq t_1:\; \cv\in\Cc}.
\end{align}
and 
\begin{align}
    \Ec_2 = \braces*{ \abs*{\sum^n_{i=1} z_i \frac{e_i^{(\xvt)}}{\norm{\ev^{(\xvt)}}}} \leq t_2},
\end{align}
respectively. 
Conditioned on $\Ec_1\cap\Ec_2$, it follows from \eqref{eq:error-bound-gaussian} that
\begin{align}\label{eq:error-bound-whp}
    \norm{\ev}^2 
    \leq \norm{\dv}^2 + 2t_1\norm{\ev} + 2t_2\norm{\dv}.
\end{align}
Therefore,
\begin{align}
    \norm{\ev}^2 - 2t_1\norm{\ev} + t_1^2
    &\le \norm{\dv}^2 + 2t_2\norm{\dv} + t_2^2 +(t_1^2-t_2^2),\\
    \abs*{\norm{\ev}-t_1}
    &\le \sqrt{(\norm{\dv}+ t_2)^2+(t_1^2-t_2^2)},
\end{align}
and finally,
\begin{align}
    \|\ev\|_2 &\le \|\dv\|_2+ t_1+t_2+\sqrt{t_1^2-t_2^2},\label{eq:bound-thm1-final}
\end{align}
where the last line follows because $\sqrt{a+b}\leq \sqrt{a}+\sqrt{b}$, for all $a,b>0$.
To finish the proof we need to bound $\P{(\Ec_1\cap\Ec_2)^c}$ and set parameters $t_1$ and $t_2$. 


Note that for each $\cv$, $\frac{\ev^{(\cv)}}{\norm{\ev^{(\cv)}}}$ is a unit vector in $\R^n$. Therefore,  $\sum^n_{i=1} z_i \frac{e_i^{(\cv)}}{\|\ev^{(\cv)}\|} \sim \mathcal{N}(0, \sigma^2_z)$. Hence, 
\begin{align}
    \P{\abs*{\sum^n_{i=1} z_i \frac{e_i^{(c)}}{\norm{\ev^{(c)}}}} \geq  t} 
    \leq 2\exp\parens*{-\frac{t^2}{2\sigma_z^2}}.
\end{align}

Therefore, applying the union bound and noting that $|\Cc|\leq 2^R$, 
\begin{align}
    \P{\Ec_1^c} \leq 2^{R+1}\exp\parens*{- \frac{t_1^2}{2\sigma_z^2}},
\end{align}
and 
\begin{align}
    \P{\Ec_2^c} \leq 2 \exp\parens*{- \frac{t_2^2}{2\sigma_z^2}}.
\end{align}
For  $\eta \in (0,1)$, set 
\[
t_1=  \sigma_z \sqrt{2 \ln2 R(1+\eta)},
\]
and 
\[
t_2= \sigma_z \sqrt{2 \ln2 R\eta}.
\]
Then,
\begin{align}
    \P{\Ec_1^c\cup\Ec_2^c}\leq 2^{-\eta R+2}.
\end{align}

Using the selected values of $t_1$ and $t_2$ in \eqref{eq:bound-thm1-final} yields the desired result, i.e.,
\begin{align*}
    {1\over \sqrt{n}}\|\xv-\xvh\|_2 &\le \sqrt{\delta}+ 2\sigma_z \sqrt{(2 \ln2) R\over n}(1+2\sqrt{\eta}),
\end{align*}
where we have used the fact that ${1\over n}\|\dv\|_2^2\leq \delta$.
\end{proof}







