\subsection{Proof of Theorem \ref{thm:2}}

\begin{proof}
Recall that $\xvh=\arg\min_{\cv \in \Cc} \Lc(\cv; \yv)$. Let
\[
\xvt=\arg\min_{\cv \in \Cc} \|\xv-\cv\|_2.
\]
Since both $\xvh$ and $\xvt$ are in $\Cc$, we have $ \Lc(\xvh; \yv) \leq  \Lc(\xvt; \yv)$, or
\begin{align}
 \sum_{i=1}^n \left( \alpha \xh_i - y_i \log \xh_i \right)\leq  \sum_{i=1}^n \left( \alpha \xt_i - y_i \log \xt_i \right). \label{eq:Poiss-proof-step1}
\end{align}
Given the input signal $\xv\in\R^n$ and $\cv\in\Cc$, let $\Poiss(\alpha x_i)$ and $\Poiss(\alpha c_i)$ denote  the distributions corresponding to independent Poisson random variables with respective means $\alpha x_i$ and $ \alpha c_i $. Note that with the chain rule for relative entropy we have
\begin{align}
D_{\text{KL}}(\Poiss(\alpha \xv)\|\Poiss(\alpha \cv))
&=\sum_{i=1}^n \Big( \alpha (c_i - x_i)+ \alpha x_i \log \frac{x_i}{c_i}  \Big).\label{eq:KL-Poiss}
\end{align}
Adding  $\sum_i(-\alpha x_i+\alpha x_i\log x_i)$ to the both sides of  \eqref{eq:Poiss-proof-step1}, it follows that
\begin{align}
 \sum_{i=1}^n \left( \alpha (\xh_i-x_i) - y_i \log \xh_i +\alpha x_i\log x_i \right)\leq  \sum_{i=1}^n \left( \alpha (\xt_i-x_i) - y_i \log \xt_i +\alpha x_i\log x_i\right), \label{eq:Poiss-proof-step2}
 \end{align}
 or 
 \begin{align}
&D_{\text{KL}}(\Poiss(\alpha \xv)\|\Poiss(\alpha \xvh)) +\sum_{i=1}^n (\alpha x_i - y_i) \log \xh_i \nonumber\\
&\leq D_{\text{KL}}(\Poiss(\alpha \xv)\|\Poiss(\alpha \xvt)) + \sum_{i=1}^n (\alpha x_i - y_i) \log \xt_i . \label{eq:Poiss-proof-step3}
 \end{align}
Given $t_1,t_2>0$, define events $\Ec_1$ and $\Ec_2$ as 
\begin{align}
\Ec_1=\left\{ \sum_{i=1}^n (y_i-\alpha x_i) \log c_i\leq t_1 : \forall \cv\in\Cc \right\}
\end{align}
and 
\begin{align}
\Ec_2=\left\{ \sum_{i=1}^n (y_i-\alpha x_i ) \log \xt_i \geq -t_2 \right\},
\end{align}
respectively.
Conditioned on $\Ec_1\cap\Ec_2$, 
\begin{align}
D_{\text{KL}}(\Poiss(\alpha \xv)\|\Poiss(\alpha \xvh))
&\leq D_{\text{KL}}(\Poiss(\alpha \xv)\|\Poiss(\alpha \xvt))+t_1+t_2,
\end{align}
and consequently from  Lemma \ref{lemma:1},  
\begin{align}
{x_{\min}^2\over  x_{\max}^3}\alpha\|\xv-\xvh\|_2^2 &\leq {x_{\max}^2\over  x_{\min}^3} \alpha\|\xv-\xvt\|_2^2+(t_1+t_2).
\end{align}
To finish the proof, we bound $\P{\Ec_1\cap\Ec_2}$ and set $t_1$ and $t_2$.




To bound $\P{\Ec_1^c}$, we apply  Lemma \ref{lemma:chernoff}, where for each $\cv$, we set $w_i(\cv)=\log{1\over c_i}$.  Then,
\[
\sigma^n(\cv)=\sum_{i=1}^n(\log{1\over c_i})^2\alpha x_i\leq \alpha \beta^2 \sum_{i=1}^n x_i,
\]
and
\[
w_M=\max_{i}|w_i|\leq \beta,
\]
where
\[
\beta = \log({1\over x_{\min}}).
\]
Therefore, using the union bound, it follows that 
\begin{align}
\P{\Ec_1^c}
&\leq 2^{R}\exp(-\frac{t_1^2}{2( \alpha \beta^2 \sum_{i=1}^n x_i +   \beta t_1 / 3)})\nonumber\\
&\leq 2^{R}\exp(-\frac{t_1^2}{2( n\alpha \beta^2 x_{\max} +   \beta t_1 / 3)}).
\end{align}
To bound $\P{\Ec_2^c}$, we again apply  Lemma \ref{lemma:chernoff}, with $w_i=\log{1\over \xt_i}$, and derive
\begin{align}
\P{\Ec_2^c}&\leq \exp(-\frac{t_2^2}{2( \alpha \beta^2 \sum_{i=1}^n x_i + \beta t_2 / 3)}) \nonumber\\
&\leq \exp(-\frac{t_2^2}{2( n\alpha \beta^2 x_{\max} +   \beta t_1 / 3)}).
\end{align}
Setting $t_1$ and $t_2$ such that they are both smaller than $3n\alpha \beta$, and noting that $x_{\max}<1$, we have 
\begin{align}
    \P{\Ec_1^c\cap \Ec_2^c}\leq 2^{R}\exp(-\frac{t_1^2}{4 n\alpha \beta^2    })+\exp(-\frac{t_2^2}{4 n\alpha \beta^2    }).
\end{align}
Choosing 
$t_1=\beta \sqrt{{4\over \ln 2} nR(1+\eta)\alpha }$ and $t_2=\beta \sqrt{{4\over \ln 2} nR \eta\alpha }$,
it follows that 
\begin{align}
    \P{\Ec_1^c\cap \Ec_2^c}\leq 2^{-\eta R}.
\end{align}

\end{proof}


\subsection{Proof of Theorem \ref{thm:4}}

\begin{proof}
Recall that 
\[
   \xvh = \argmin_{\cv\in\Cc} \|\cv - \yv/\alpha\|_2^2,\quad \quad  \xvt = \argmin_{\cv\in\Cc} \|\cv - \xv\|^2_2.
\]
Following the similar setup as in Section \ref{sec:additive-noise-recovery}, we get
\begin{align*}
    \|\hat{\xv} - \yv / \alpha \|^2 &\leq \|\Tilde{\xv} - \yv / \alpha \|^2 \\
    \|\hat{\xv} - \xv + \xv-\yv/ \alpha\|^2 &\leq \|\Tilde{\xv} -\xv + \xv-\yv/ \alpha\|^2 \\
    \|\hat{\xv} - \xv\|^2 - 2 \angles{\yv/ \alpha-\xv,\hat{\xv} - \xv} + \norm{\yv/ \alpha-\xv}^2 &\leq \|\Tilde{\xv} - \xv\|^2 - 2 \angles{\yv/ \alpha-\xv,\Tilde{\xv} - \xv} + \norm{\yv/ \alpha-\xv}^2 \\
    \|\hat{\xv} - \xv\|^2 &\leq \|\Tilde{\xv} - \xv\|^2 - 2 \angles{\yv/ \alpha-\xv,\Tilde{\xv} - \xv} + 2 \angles{\yv/ \alpha-\xv,\hat{\xv} - \xv} \\
    \|\hat{\xv} - \xv\|^2 &\leq \|\Tilde{\xv} - \xv\|^2 + 2 \abs*{\angles{\yv/ \alpha-\xv,\Tilde{\xv}-\xv}} + 2 \abs*{\angles{\yv/ \alpha-\xv,\hat{\xv}-\xv}}.
\end{align*}
Defining $\ev$, $\dv$ and $\ev^{(\cv)}$, $\cv\in\Cc$,  as done in the proof of Theorem \ref{thm:1}, we have
\begin{align}
    \norm{\ev}^2 
    &\le\norm{\dv}^2 + 2\abs*{\angles{\yv/ \alpha-\xv, \ev}} + 2\abs*{\angles{\yv/ \alpha-\xv, \dv}}.
\end{align}

Define events 
\begin{align}
    \Ec_1 = \braces*{ \abs*{\sum^n_{i=1} (y_i- \alpha x_i) e_i^{(\cv)}} \leq  t_1:\; \cv=1,\ldots,2^R},
\end{align}
and 
\begin{align}
    \Ec_2 = \braces*{ \abs*{\sum^n_{i=1} (y_i- \alpha x_i) e_i^{(\xvt)}} \leq t_2}.
\end{align}
Conditioned on $\Ec_1\cap\Ec_2$, it follows that 
\begin{align}
    \|\ev\|^2 &\leq \|\dv\|^2 + 2(t_1 + t_2)/\alpha,\label{eq:bound-E1-2}
\end{align}
Using  Lemma \ref{lemma:chernoff} with $y_i\sim\Poiss(\alpha x_i)$ and $w_i=e_i^{(\cv)}$, it follows that 
\begin{align}
    \P{\abs*{\sum^n_{i=1} (y_i -\alpha x_i) e_i^{(\cv)}} \geq  t} 
    \leq 2\exp\parens*{-\frac{t^2}{2(\sigma_n^2+ w_Mt/3)}},
\end{align}
where 
\begin{align}
\sigma_n^2
&=\sum_{i=1}^nw_i^2\alpha_i
= \alpha\sum_{i=1}^n (e_i^{(\cv)})^2x_i\leq n \alpha x_{\max}^3,
\end{align}
and 
\[
w_M = \max_{i\in\{1,\ldots,n\}} |w_i|\leq x_{\max}.
\]
Using the union bound and noting that $|\Cc|\leq 2^R$, we have
\begin{align}
    \P{\Ec_1^c}
    &\leq 2^{R+1} \exp\left(-\frac{t_1^2}{2(nx_{\max}^3\alpha+ t_1x_{\max}/3)}\right)
\end{align}
and 
\begin{align}
    \P{\Ec_2^c} \leq 2 \exp\left(-\frac{t_2^2}{2(nx_{\max}^3\alpha+ t_2x_{\max}/3)}\right).
\end{align}
Setting $t_1$ and $t_2$ such that they are both smaller than $3nx_{\max}^2\alpha$, and noting that $x_{\max}<1$, we have 
\begin{align}
    \P{\Ec_1^c\cap \Ec_2^c}\leq 2^{R+1}\exp(-\frac{ t_1^2}{4 n \alpha})+2\exp(-\frac{ t_2^2}{4 n\alpha}).
\end{align}

For  $\eta \in (0,1)$, set 
\[
t_1 = 2\sqrt{n(\ln 2)(1+\eta) \alpha R}, 
\]
and 
\[
t_2= 2\sqrt{n\eta(\ln2)\alpha R}.
\]
Then,
\begin{align}
    \P{\Ec_1^c\cup\Ec_2^c}\leq 2^{-\eta R+2}.
\end{align}
Using the selected values of $t_1$ and $t_2$ in \eqref{eq:bound-E1-2} yields the desired result, i.e.,
\begin{align*}
    \|\ev\|_2^2 &\le \|\dv\|_2^2 + 4\sqrt{n(\ln 2)(1+\eta) {R\over \alpha}}+4\sqrt{n\eta(\ln2){R\over \alpha}}\nonumber\\
    &\le \|\dv\|_2^2+ \sqrt{{nR\over \alpha}}\parens*{4\sqrt{\ln2}}\parens*{\sqrt{1+\eta}+\sqrt{\eta}+1}.
\end{align*}

\end{proof}


\subsection{Proof of Corollary \ref{cor:1}}
\begin{proof}
First we need to design a lossy compression for the set of signals in $\Qc_n$, defined as
\begin{align}
    \Qc_n=\braces*{\xv\in\R^n: \norm{\xv}_0\le k, \norm{\xv}_2\le1}.
\end{align}
For a $k$-sparse $\xv\in\Qc_n$, let $\xv^{(k)}\in\R^k$ denote  the $k$-dimensional vector derived from the non-zero coordinates of $\xv$. Let $\Bc^k_2=\braces*{\av\in\R^k: \|\av\|_2\leq 1}$, then $\xv^{(k)}\in\Bc^k_2$.
We define a lossy compression code with rate $R$ and distortion $\delta$ as follows:
\begin{enumerate}
    \item To encode the number of non-zero entries and their locations in $\xv\in\Qc_n$,  one spends at most $\log_2 k+k \log_2n$ bits.
    \item To encode the values of the non-zero coordinates, the number of balls of radius $\varepsilon$ required to cover  $\Bc^k_2$, $N(\Bc^k_2, \varepsilon)$ is bounded as
    \begin{align*}
        \parens*{\frac{1}{\varepsilon}}^k
        \le N(\Bc^k_2, \varepsilon)
        \le\parens*{\frac{2}{\varepsilon}+1}^k.
    \end{align*}
    This implies that at most by using 
    \begin{align}
        k\log_2 \frac{1}{\varepsilon} 
        \le \log_2 N(\Bc^k_2, \varepsilon)
        \leq k\log_2 \parens*{\frac{2}{\varepsilon}+1}   
    \end{align}
    bits, we can encode the values of the non-zero entries of $\xv\in\Qc_n$, or equivalently all the entries of $\xv^{(k)}\in\Bc^k_2$, with error less than $\varepsilon$.
\end{enumerate}
Note, as defined in Section \ref{sec:compression-denoising},  we measure the distortion of a lossy compression code as squared error. Therefore, to achieve the defined distortion $\delta$, we need to set $\varepsilon=\sqrt{\delta}$, which implies that the overall rate is bounded as
\begin{align}\label{eq:ksparse-rate-bound}
 \log_2 k+k \log_2n+k\log_2 \parens*{\frac{1}{\sqrt{\delta}}}
\le R\leq \log_2 k+k \log_2n+k\log_2 \parens*{\frac{2}{\sqrt{\delta}}+1}, 
\end{align}
using the upper bound on the rate as in \eqref{eq:ksparse-rate-bound} in combination with Theorem \ref{thm:1}, we have
\begin{align*}
    {1\over \sqrt{n}}\|\xv-\xvh\|_2 &\le \sqrt{\delta}+ 2\sigma_z \sqrt{(2 \ln2) \parens*{\log_2 k+k \log_2n+k\log_2 \parens*{\frac{2}{\sqrt{\delta}}+1}}\over n}(1+2\sqrt{\eta})\nonumber\\
    &\le \sqrt{\delta}+ 2\sigma_z \sqrt{(2 \ln2) \parens*{\log_2 k+k \log_2n+{k\over 2}\log_2({1\over \delta})+k\log_2 (2+\sqrt{\delta})\over n}}(1+2\sqrt{\eta}),
\end{align*}
setting $\delta={1\over n}$, with probability at least $1-2^{-\eta R+2}$ we have
\begin{align*}
    \frac{1}{\sqrt{n}}\norm{\hat{\xv}-\xv} 
    &\le \frac{1}{\sqrt{n}}+ \sigma_zC \sqrt{\log_2 k+{k\over 2}\log_2 n+k\log_2 (2+1/\sqrt{n})\over n}\\
    &= \frac{1}{\sqrt{n}}+ \sigma_zC \sqrt{\frac{k\log_2 n}{n}}\sqrt{1+\frac{2\log_2 k}{k\log_2 n}+\frac{2\log_2 (2+1/\sqrt{n})}{\log_2 n}}\\
    &\le \frac{1}{\sqrt{n}}+ \sigma_zC \sqrt{\frac{k\log_2 n}{n}}\parens*{1+\frac{\log_2 k}{k\log_2 n}+\frac{\log_2 (2+1/\sqrt{n})}{\log_2 n}}\\
    &= \sigma_zC \sqrt{\frac{k\log_2 n}{n}}+\parens*{\frac{1}{\sqrt{n}}+\frac{\sigma_zC\log_2 k}{2\sqrt{n}}+\frac{\sigma_zC\sqrt{k}\log_2 (2+1/\sqrt{n})}{\sqrt{n}}},
\end{align*}
where $C=2\sqrt{\ln2}(1+2\sqrt{\eta})$. Squaring both sides of the last inequality gives
\begin{align}
    \frac{1}{n}\norm{\hat{\xv}-\xv}^2
    \le \sigma_z^2C^2\frac{k\log_2 n}{n} +o(1),
\end{align}
which holds with probability at least $1-\frac{4}{\parens*{kn^{3k/2}}^\eta}$, using the lower bound on the rate in \eqref{eq:ksparse-rate-bound}.
\end{proof}





\section{Conclusions}
% \vspace{-0.1in}
We have studied  maximum likelihood compression-based denoising, and provided theoretical characterization of its performance under both AWGN and Poisson noise.  Furthermore, we introcued  ZS-NCD, a new zero-shot neural-compression-based denoising and demonstrated that it achieves state-of-the-art performance among zero-shot methods, in both AWGN and Poisson denoising. 



