  \UIC{\(\Gamma, \exists x p(x) \vdash \Delta\)}
  \DisplayProof

  \AXC{\(\Gamma \vdash p(e), \Delta\)}
  \LeftLabel{{\(\exists\)R}}
  \UIC{\(\Gamma \vdash \exists x p(x), \Delta\)}
  \DisplayProof

  \AXC{\(\Gamma, P \vdash Q, \Delta\)}
  \AXC{\(\Gamma, Q \vdash P, \Delta\)}
  \LeftLabel{{\(\leftrightarrow\)}}
  \BIC{\(\Gamma \vdash P \leftrightarrow Q, \Delta\)}
  \DisplayProof

  \AXC{\(\Gamma \vdash C, \Delta\)}
  \AXC{\(\Gamma, C \vdash \Delta\)}
  \LeftLabel{{cut}}
  \BIC{\(\Gamma \vdash \Delta\)}
  \DisplayProof
\end{mathpar}

\section{Proof Calculus Soundness} \label{sec:proofs}
In this section, we present the soundness proof for the calculus in \rref{thm:soundness} and some technical lemmas.
\begin{lemma}[Coincidence for terms and formulas] \label{lem:coincidence}
  The set of free variables of terms \(\FV{e}\) and formulas
  \(\FV{\phi}\) are defined in \cite{DBLP:journals/jar/Platzer17}.
  Coincidence property:
  \begin{enumerate}
    \item If states \(\omega, \nu\) agree on the free variables of
      \(e\), then \(\omega\sem{e}=\nu\sem{e}\)
    \item If states \(\omega, \nu\) agree on the free variables of
      \(\phi\), then \(\omega\sem{\phi}\) iff \(\nu\sem{\phi}\).
  \end{enumerate}
\end{lemma}

\begin{lemma}[Properties of Real-Analytic Functions] \label{lem:analytic}
  Let \( f \in C^{\omega}(U) \) and \( g \in C^{\omega}(V) \) be real-analtyic functions, where \( U, V \subseteq \mathbb{R}^n \) are open sets.
  Then the following hold:
  \begin{enumerate}
    \item \( f + g \in C^{\omega}(U \cap V) \),
    \item \( f \cdot g \in C^{\omega}(U \cap V) \),
    \item For any multi-index \( \gamma \), \(\frac{\partial^\gamma
      f}{\partial x^\gamma} \in C^{\omega}(U),\)
    \item If \( g: V \to U \) is a real-analytic function between
      open sets \( V \subseteq \mathbb{R}^m \) and \( U \subseteq
      \mathbb{R}^n \), with \( f: U \to \mathbb{R} \), then the
      composition \( f \circ g \) is in \( C^{\omega}(V) \).
  \end{enumerate}
\end{lemma}

\begin{proof}
  The proofs of 1 and 2 can be found in \cite[Proposition 1.1.4]{krantz_primer_2002}, that of 3 in \cite[Proposition 1.6.3]{krantz_primer_2002}, and that of 4 in \cite[Proposition 1.6.7]{krantz_primer_2002}.
\end{proof}
\begin{theorem}(Identity Theorem \cite[Cor.~1.2.6 p.~14]{krantz_primer_2002})
  \label{thm:identity_theorem}
  Let \(U\) be an open interval and let \(f,g \in C^{\omega}(U)\) be real analytic functions. Then, if
  there is a strictly monotone sequence \((x_k)_{k\in\N}\) in \(U\) with
  \(\lim_{n \rightarrow \infty}x_n \in U\) such that
  \begin{equation*}
    f(x_n) = g(x_n), \text{ for } n = 1,2,\dots
  \end{equation*}
  then
  \begin{equation*}
    f(x) = g(x) \text{ for all } x \in U.
  \end{equation*}
\end{theorem}
%\begin{proof}
%  The proof can be found in \cite[p.~14, Cor. 1.2.6]{krantz_primer_2002}.
%\end{proof}
\begin{lemma} \label{lem:zeros}
  Let \(U \subseteq \R\) be an open interval and \(f \in C^{\omega}(U)\) be a real-analytic function.
  If \(f\) is non-constant, then \(f\) has at most finitely many zeros in each closed interval \([a,b] \subset U\).
\end{lemma}
\begin{proof}
  Let \(f \in C^{\omega}(U)\) be a non-constant, real-analytic function. Define the zero set \(Z = \{t \in [a,b] \vl f(t) = 0\}\). Assume for a contradiction, that \(Z\) contains infinitely many elements. Fix any element \(t_1 \in Z\).
  Then, either \([a,t_1] \cap Z\) or \([t_1,b] \cap Z\) has an infinite set of elements. Without loss of generality, construct a strictly increasing sequence
  \((t_k)_{k \in \N}\) of elements of \([t_1,b] \cap Z\).
  By the monotone convergence theorem, this sequence has a limit \(\lim_{k
  \rightarrow \infty} t_k = t^*\), which is contained in \(t^* \in
  [a,b]\), because \([a,b]\) is a compact set.
  In summary, we have \(f(t_k) = 0 \) for \(k \in \N\) and \(
  \lim_{k \rightarrow \infty}t_k \in [0,T]\). By \rref{thm:identity_theorem}, this implies \(f(t) = 0\) for all \(t \in U\). This contradicts, the assumption that \(f\) is a non-constant function.
\end{proof}
\begin{remark} \label{rem:inf}
  Define the set \(\mathcal{T} = \{s \vl \varphi(s) \in \sem{F}\} \neq \varnothing\).
  For the infimum \(t = \inf \mathcal{T}\) we have \(t \leq s\) for all \(s \in [0,T]\) with \(\varphi(s) \in \sem{F}\).
  For all \(\tau \in (t,T]\) with \(\varphi(\tau) \in \sem{F}\) there exists an \(s \in [t,\tau)\) such that \(\varphi(s) \in \sem{F}\).
  If \(\varphi(t) \in \sem{\neg F}\), then there exists a \(T-t\geq \delta_0 > 0\) such that \(\varphi((t,t+\delta_0)) \subseteq \sem{F}\) by \rref{cor:zeros}.
\end{remark}
\begin{lemma} \label{lem:local_progress}
  We have \(\omega \in \sem{\progress{\daesys{\tuple{x}}{F}} \lor (\tuple{x}'=0 \land F)}\), if and only if, there
  exist \(\epsilon > 0, T > 0\) and a flow \(\varphi \in \analyticFlowsInterval\) such that \(\varphi((0,T]) \subseteq \sem{F}\) and \(\omega = \varphi(0)\).
\end{lemma}
\begin{proof}[of \rref{lem:local_progress}]
  Fix an arbitrary state with \begin{align*}
    \omega &\in \sem{\progress{\daesys{\tuple{x}}{F}}} \\
    &= \sem{\exists \tuple{y} \exists \tuple{y}' (\tuple{x} = \tuple{y} \land \tuple{x}' = \tuple{y}' \land \dia{\daesys{\tuple{x}}{F \lor (\tuple{x} = \tuple{y} \land \tuple{x}' = \tuple{y}')}}\tuple{x} \neq \tuple{y})}.
  \end{align*}
  Then, there exists a state \(\nu \in \states\) with \(\nu(\tuple{x}) = \nu(\tuple{y}) = \omega(\tuple{x})\) and \(\nu(\tuple{x}') = \nu(\tuple{y}') = \omega(\tuple{x}')\) and \(\nu \in \sem{\dia{\daesys{\tuple{x}}{F \lor (\tuple{x} = \tuple{y} \land \tuple{x}' = \tuple{y}')}}\tuple{x} \neq \tuple{y}}\).
  This implies that there exist \(T \geq 0, \epsilon > 0\) and a flow \(\varphi \in \analyticFlowsInterval\) with \(\varphi(0) = \nu\) such that \(\varphi([0,T]) \subseteq \sem{F \lor (\tuple{x} = \tuple{y} \land \tuple{x}' = \tuple{y}')}\) and \(\varphi(T) \in \sem{\tuple{x}\neq \tuple{y}}\).
  This implies \(\varphi(0) \in \sem{F \lor \tuple{x} = \tuple{y} \land \tuple{x}'=\tuple{z}}\). Assume for a contradiction that \(T = 0\).
  This implies \(\varphi(0)(\tuple{x}) \neq \varphi(0)(\tuple{y})\), which contradicts \(\nu(\tuple{x}) = \nu(\tuple{y})\).
  Therefore, we may assume \(T > 0\) in the following.

  Define \(t = \inf\{s \vl \varphi(s) \in \sem{\tuple{x} \neq \tuple{y}}\}\), which is well-defined by \(\varphi(T) \in \sem{\tuple{x} \neq \tuple{y}}\).
  We consider two cases for the infimum:
  \begin{enumerate}
    \item If \(t > 0\), then \(\varphi((0,t)) \subseteq \sem{\tuple{x}=\tuple{y}}\).
    This implies \(\varphi(\tau)(\tuple{x}) = \varphi(\tau)(\tuple{y})\) for all \(\tau \in (0, t)\).
    By \cite[Corollary 1.2.5]{krantz_primer_2002}, this implies \(\varphi(\tau)(\tuple{x}) = \varphi(\tau)(\tuple{y})\) on \((-\epsilon, T + \epsilon)\) contradicting \(\varphi(T)(\tuple{x}) \neq \varphi(T)(\tuple{y})\).
    \item If \(t = 0\), then by \(\varphi(0) \in \sem{\tuple{x} = \tuple{y}}\) and \rref{rem:inf},  there exists a \(\delta_0 >0 \) such that \(\varphi((0,\delta_0)) \subseteq \sem{\tuple{x}\neq \tuple{y}}\).
    This implies \(\varphi((0,\delta_0)) \subseteq \sem{F}\). In particular, for any \(0 < S < \delta_0\) we have \(\varphi((0,S]) \subseteq \sem{F}\).
  \end{enumerate}
  Now, we define a flow \(\psi \in \analyticFlows{\tuple{x}}{(-\epsilon, S + \epsilon)}\) with \(\psi(\tau)(r) = \varphi(\tau)(r)\) for all \(\tau \in (-\epsilon, S + \epsilon)\) and \(r \in \bar{x} \cup \bar{x}'\) and \(\psi(\tau)(r) = \omega\) for all \(\tau \in (-\epsilon,S+\epsilon)\) and \(r \in (\tuple{x} \cup \tuple{x}')^\complement\).
  By \rref{lem:coincidence}, because \(\tuple{y},\tuple{y}' \not\in \FV{F}\), we have \(\psi((0,S]) \subseteq \sem{F}\).
  Otherwise, we have \(\omega \in \sem{\tuple{x}'=0 \land F}\).
  In that case define \(\varphi(\tau) = \omega\) on \((\tuple{x}')^\complement\) and \(\varphi(\tau) = 0\) on \(\tuple{x}'\) for \(\tau \in [0,T]\).

  Conversely, suppose there are \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) with \(\varphi(0) = \omega\) and \(\varphi((0,T]) \subseteq \sem{F}\). Consider three disjoint cases:
  \begin{enumerate}
    \item If \(\omega \in \sem{\tuple{x}' = 0 \land F}\), then the statement immediately follows.
    \item If \(\omega \in \sem{\neg F \land \tuple{x}' = 0}\), we have \(\omega = \varphi(0) \in \sem{\neg F}\). By \(\varphi(0) = \omega \in \sem{\tuple{x}' = 0}\), we also have \(\varphi(0)(\tuple{x}) = \varphi(T)(\tuple{x})\). The previous two properties contradict the assumption that there exists a flow \(\varphi \in \analyticFlowsInterval\) with \(\varphi(T) \in \sem{F}\).
    \item If \(\omega \in \sem{\tuple{x}' \neq 0}\). Then, by the continuity of derivatives there exists a \(\delta > 0\) and a variable \(r' \in \tuple{x}'\) such that \(\varphi(\tau)(r') \neq 0 \) for all \(\tau \in [0,\delta)\). By applying the mean-value theorem we obtain:  \(\varphi(\delta)(r) - \varphi(0)(r) = \tau\frac{d\varphi(t)}{dt}(\xi) \neq 0\) for some \(\xi \in (0,\delta)\). Therefore, we have \(\varphi(\delta) \in \sem{\tuple{x} \neq \tuple{y}}\).
  \end{enumerate}
\end{proof}

\begin{proof}[of \rref{lem:seq}]
  For \(T \geq 0\) and \(\epsilon > 0\) let \(\varphi \in \analyticFlowsInterval\) be a flow. Because \(F\) is a semi-algebraic set,
  form, we can represent it by its disjunctive normal: \[
    F \equiv \bigvee_{i=1}^n\left(\bigwedge_{p \in
      \mathcal{P}_i} p \geq 0 \land \bigwedge_{q \in
    \mathcal{Q}_i} q > 0\right),
  \]
  where \(\mathcal{P}_i\) and
  \(\mathcal{Q}_i\) are finite sets of polynomials for \(i \in \N\). For the flow \(\varphi\) it is
  equivalent, to instead consider the reduced representation
  \[
    F_{\mathcal{I}} \equiv \bigvee_{i=1}^n\left(\bigwedge_{p \in
      \mathcal{P}_i \setminus \mathcal{I}} p \geq 0 \land
    \bigwedge_{q \in \mathcal{Q}_i\setminus \mathcal{I}} q > 0\right),
  \]
  where \(\mathcal{I} = \{p \in \Pi \vl \varphi(0)\sem{p} =
  \varphi(t)\sem{p} \text{ for all } 0 \leq t \leq T\}\) is set of
  all polynomials that remain constant along the flow. Without loss
  of generality assume that \((\tau_k)_{k \in \N}\) is strictly
  monotonically increasing. Suppose that for every \(k_0 \in \N\)
  there exists a \(t \geq \tau_{k_0}\) such that \(\varphi(t) \in
  \sem{\neg F_{\mathcal{I}}}\). We know that \(\varphi(\tau_{k_0+1})
  \in \sem{F_{\mathcal{I}}}\). By the continuity of the
  solution, the intermediate value theorem implies that exists an
  intermediate value with \(t
  \leq \xi_{k_0} \leq \tau_{k_0+1}\) and \(\varphi(\xi_{k_0})\sem{p(x,x')} =
  0\) for some \(p \in (\mathcal{P} \cup \mathcal{Q})\setminus
  \mathcal{I}\), where \(\mathcal{P} =
  \bigcup_{i=1}^n \mathcal{P}_i\) and \(\mathcal{Q} = \bigcup_{i=1}^n
  \mathcal{Q}_i\). By repeating this argument we can construct
  a strictly increasing sequence of intermediate values
  \((\xi_{k_0})_{k_0 \in \N}\) such that for every \(k_0 \in \N\)
  there exists a \(p \in (\mathcal{P} \cup \mathcal{Q})\setminus
  \mathcal{I}\) with \(\varphi(\xi_{k_0})\sem{p(x,x')} = 0\).
  Because the set of polynomials \((\mathcal{P} \cup
  \mathcal{Q})\setminus
  \mathcal{I}\) is finite, this implies that there is at least one
  element \(p \in (\mathcal{P} \cup \mathcal{Q})\setminus
  \mathcal{I}\) with an infinite set of zeros in \([0,T]\).
  The value of that polynomial along the flow is given by \(\varphi(\cdot)\sem{p(x,x')}:(-\epsilon,T+\epsilon) \rightarrow \R\) which is real-analytic on \((-\epsilon,T+\epsilon)\) by \rref{lem:analytic}. Because \(p \not\in \mathcal{I}\) is non-constant along the flow, the function \(\varphi(\cdot)\sem{p(x,x')}\) is non-constant. This contradicts \rref{cor:zeros}, because \(\varphi(\cdot)\sem{p(x,x')}\) has an infinite set of zeros in \([0,T]\).
  \qed
\end{proof}

\begin{corollary} \label{cor:zeros}
  Let \(T \geq 0, \epsilon > 0\), \(\varphi \in \analyticFlowsInterval\) be a flow and \(F\)
  be a semi-algebraic set. Then, if for all \(\delta \in (t,T]\)
  there exists a \(\tau \in (t,t+\delta)\) such that \(\varphi(\tau)
  \in \sem{F}\),
  then there exists a \(\delta_0  > 0\) such that for all \(\tau \in (t,t + \delta_0) \) we have \(\varphi(\tau) \in \sem{F}\).
\end{corollary}
\begin{proof}
  Let \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) be a flow. Construct a
  strictly deceasing sequence \((\tau_{k})_{k \in \N}\) such that
  \(\varphi(\tau_k) \in \sem{F}\) by \rref{lem:seq} there exists
  a \(k_0 \in \N\) such that \(\varphi(\tau) \in \sem{F}\) for all
  \(\tau \leq \tau_{k_0}\). \qed
\end{proof}
\begin{lemma} \label{lem:progress}
  Let \(T \geq 0, \epsilon > 0\), \(\varphi \in \analyticFlowsInterval\) be a flow and \(F\)
  be a semi-algebraic set. Then, if we have \(\varphi(0) \in \sem{\neg F}\) and \(\varphi(T) \in \sem{F}\), the following holds: The infimum \(t = \inf \{ \tau \vl \varphi(\tau) \in \sem{F}\}\) satisfies \(\varphi(t) \in \sem{\enter{\daesys{\tuple{x}}{F}}}\) and \(\varphi(t) \in \sem{\exit{\daesys{\tuple{x}}{\neg F}}}\).
\end{lemma}
\begin{proof}
  Let \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) be a flow with \(\varphi(0) \in\sem{\neg F}\) and \(\varphi(T) \in \sem{F}\). We have \(\varphi(\tau) \in \sem{\neg F}\) for \(\tau \in [0,t)\), by the definition of the infimum. First, we show \(\varphi(t) \in \sem{\enter{\daesys{\tuple{x}}{F}}}\), by splitting into two disjoint cases:
  \begin{enumerate}
    \item Suppose \(\varphi(t) \in \sem{F}\). Then show \(\varphi(t) \in \sem{\progress{\daesys{\tuple{x}}{\neg F^-}^-}}\). Construct \(\psi(\tau)(\tuple{x}) = \varphi(t - \tau)(\tuple{x})\) and \(\psi(\tau)(\tuple{x}') = - \varphi(t - \tau)(\tuple{x}')\) for \(\tau \in [0,t]\). Then we have \(\psi((0,\tau]) \subseteq \sem{\neg F^-}\). This implies \(\psi(0) \in \sem{\progress{\daesys{\tuple{x}}{\neg F^-}}}\), which implies \(
    \varphi(t) = \psi(0)_{\tuple{x}'}^{-\psi(0)(\tuple{x}')} \in \sem{\progress{\daesys{\tuple{x}}{\neg F^-}}^-}\).
    \item Otherwise, suppose \(\varphi(t) \in \sem{\neg F}\). We show \(\varphi(t) \in \sem{\progress{\daesys{\tuple{x}}{F}}}\): If there exists a \(\delta \in (0,T]\) such that for all \(\tau \in (t,t+\delta)\) we have \(\varphi(\tau) \in \sem{F}\), the flow satisfies \(\varphi((t,t+\delta_0]) \subseteq \sem{F}\) for some \(\delta_0 < \delta\). By \rref{lem:local_progress}, this implies the statement. Now, suppose for a contradiction that for every \(\delta \in (0,T]\), there exists a \(\tau \in (t,t+\delta)\) such that \(\varphi(\tau) \in \sem{\neg F}\). By \rref{cor:zeros}, this implies that there exists a \(\delta_0 \in (t,T]\) such that for all \(\tau \in (t,t+\delta_0)\) we have \(\varphi(\tau) \in \sem{\neg F}\). Together with \(\varphi(t) \in \sem{\neg F}\) this implies for all \(\tau \in [t,t+\delta)\) we have \(\varphi(\tau) \in \sem{\neg F}\), contradicting that \(t\) is the infimum of \(\{ \tau \vl \varphi(\tau) \in \sem{F}\}\).
  \end{enumerate}
  The two cases combined imply \(\varphi(t) \in \sem{\enter{\daesys{\tuple{x}}{F}}}\). By \rref{def:progress}, we have 
  \begin{align*}
    \sem{\enter{\daesys{\tuple{x}}{F}}} &= \sem{(\progress{\daesys{\tuple{x}}{
    F}} \land \neg F) \lor (\progress{\daesys{\tuple{x}}{\neg
    F^-}}^- \land F)} \\
    &= \sem{\exit{\daesys{\tuple{x}}{\neg F}}}.
  \end{align*}
  This implies the second statement.
\end{proof}
\begin{lemma} \label{lem:mode_consistency}
  Let \(T \geq 0, \epsilon > 0 \) and \(\varphi \in \analyticFlowsInterval\) be a flow with \(\varphi(0) \in
  \sem{F}\) and \(\varphi([0,T]) \subseteq \sem{F \lor G}\). If we have \(\varphi([0,T]) \subseteq
  \sem{\consis{F}{G}}\) and there exists a \(\xi \in [0,T]\) such that
  \(\varphi(\xi) \in \sem{G}\), then there a \(\tau \in [0,T]\) such that
  \(\varphi([0,\tau]) \subseteq \sem{F}\) and \(\varphi(\tau)
  \in \sem{F \land G}\).
\end{lemma}

\begin{proof}
  Fix \(T \geq 0, \epsilon > 0 \) and \(\varphi \in \analyticFlowsInterval\) with \(\varphi(0) \in
  \sem{F}\) and \(\varphi([0,T]) \subseteq \sem{F \lor G}\) and \(\varphi(\xi) \in \sem{G}\) for some \(\xi \in [0,T]\). If \(\varphi(0)
  \in \sem{G}\), the statement immediately follows. Otherwise,
  consider \(\varphi(0) \in \sem{\neg G}\).
  Define the set \(\mathcal{T} = \{t \vl \varphi(t) \in
  \sem{G}\}\). Choose \(t\) to be the infimum of
  \(\mathcal{T}\), which is well-defined because of \(\varphi(\xi) \in
  \sem{G}\). By the definition of the infimum, we have \(\varphi(\tau) \in
  \sem{\neg G}\) for all \(\tau \in [0,t)\). This implies
  \(\varphi(\tau) \in \sem{F}\) for all \(\tau \in [0,t)\) and
  \(\varphi (t) \in \enter{\daesys{x}{G}}\) by \rref{lem:progress}.
  We consider three separate cases:
  \begin{enumerate}
    \item \(\varphi(t) \in \sem{\exit{\daesys{\tuple{x}}{F}}}\): We show
      \(\varphi(t) \in \sem{F \land G}\): We have
      \(\varphi(t) \in \sem{\exit{\daesys{\tuple{x}}{F}} \land \enter{\daesys{\tuple{x}}{G}}}\).
      This implies \(\varphi(t) \in \sem{F \leftrightarrow
      G}\). By assumption, we have \(\varphi(t) \in
      \sem{F \lor G}\). Without loss of generality, we
      assume \(\varphi(t) \in \sem{F}\). This implies
      \(\varphi(t) \in \sem{F \land G}\).
    \item \(\varphi(t) \in \sem{\neg \exit{\daesys{\tuple{x}}{F}} \land
      F}\): This condition implies \(\varphi (t) \in \sem{\neg
      \progress{\daesys{\tuple{x}}{\neg F}}}\). If \(t = T\), then by assumption this implies \(\varphi(T) \in \sem{G}\) and also \(\varphi(T) \in \sem{F}\).
      Otherwise, consider \(t < T\). By \rref{lem:local_progress}, for all \(S
      > 0, \delta > 0\) and all flows \(\psi \in \analyticFlows{\tuple{x}}{(-\delta, S + \delta)}\) with \(\psi(0) = \varphi(t)\) there exists a \(\tau \in (0,S]\) such that \(\psi(\tau) \in \sem{F}\).
      In particular, this implies if that for all \(\delta \in (t,T]\) there exists a \(\tau \in (t, t + \delta)\) such that \(\varphi(\tau) \in \sem{F}\). By \rref{cor:zeros}, this implies
      that there exists a \(\delta_0 > 0\) such that \(\varphi((t, t +\delta_0)) \subseteq
      \sem{F}\). Similarly,
      there exists a \(t \leq \tau < t +
      \delta_0\) such that \(\varphi(\tau) \in \sem{G}\):
      assume for all \(t \leq \tau < t + \delta_0\) we have
      \(\varphi(\tau) \in \sem{\neg G}\). Then, \(t+\delta_0\)
      is a lower bound \(\mathcal{T}\), but \(t + \delta_0 > t\),
      which contradicts the assumption that \(t\) is the infimum of
      \(\mathcal{T}\). This implies \(\varphi(\tau) \in \sem{F}
      \cap \sem{G} = \sem{F \land G}\). 
    \item \(\varphi(t) \in \sem{\neg \exit{\daesys{\tuple{x}}{F}} \land
      \neg F}\): This condition implies \(\varphi(t) \in
      \sem{\neg\progress{\daesys{\tuple{x}}{F^-}}^-}\). We can easily see
      that this contradicts the existence of \(\varphi\) by
      constructing \(\psi \in \analyticFlowsInterval\) with
      \(\psi (\tau)(\tuple{x}) = \varphi(t-\tau)(\tuple{x})\) and
      \(\psi (\tau)(\tuple{x}') = -\varphi(t-\tau)(\tuple{x}')\)
      for \(\tau \in [0,t]\). For this flow we have \(\psi((0,t]) \subseteq \sem{F^-}\), which contradicts \(\varphi(t) = \psi(0)_{\tuple{x}'}^{-\psi(0)(\tuple{x}')}\in \sem{\neg\progress{\daesys{\tuple{x}}{F^-}}^-}\).
  \end{enumerate}
  In the first two cases, there exists a \(\tau \in [0,T]\) such that \(\varphi(\tau) \in \sem{F \land G}\) and the third case leads to a contradiction.
  \qed
\end{proof}

\begin{lemma}[Differential Lemma] \label{lem:diff}
  Let \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) be a flow and \(e\) be a term with \(\FV{e} \subseteq \tuple{x}\).
  Then we have
  \[
    \varphi(t)\sem{(e)'} = \frac{d \varphi(t)\sem{e}}{dt}
  \]
  for all \(t \in [0,T]\).
\end{lemma}
\begin{proof}
  Let \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) be a flow and \(e\) a term with \(x'
  \not\in e\). Then, for \(t \in [0,T]\) we have
    \[
    \varphi(t)\sem{(e)'} 
    = \sum_{r \in e} \varphi(t)(r') \frac{\partial \varphi(t)\sem{e}}{\partial r} 
    = \sum_{r \in e} \frac{d \varphi(t)(r)}{d t} \frac{\partial
    \varphi(t)\sem{e}}{\partial r} = \frac{d \varphi(t)\sem{e}}{d t},
    \]
    by differential consistency of \(\tuple{x}\) and \(\tuple{x}'\) and the chain rule.
    \qed
\end{proof}

\begin{proof}
  While some of the axioms in \rref{thm:soundness} resemble those
  in \dL, special care must be taken to ensure their soundness,
  particularly due to the non-uniqueness of solutions and the
  requirement to show that solutions are analytic.

  Key considerations are:
  \begin{enumerate}
    \item DW combines the behavior of \dL's DW and DE
      \cite{DBLP:journals/jar/Platzer17}, if the derivative of all state
      variables is explicit.
    \item DE encodes the differential consistency between \(x\) and
      \(x'\) and was not included in the original calculus of \dL
      \cite{DBLP:journals/jar/Platzer17} in this form.
    \item BDG Differential ghosts need a new argument, because we must
      show that the flow of the augmented system analytic.
    \item AG generalizes differential cuts of \dL \cite{DBLP:journals/jar/Platzer17}.
    \item GS is an entirely new axiom.
  \end{enumerate}
  \begin{itemize}
    \item[DW] Let \(\omega \in \states\) be an arbitrary state. Let \(T \geq 0 \), \(\epsilon > 0\) and 
      \(\varphi \in
      \analyticFlowsInterval\) be a fixed flow with \(\varphi([0,T]) \subseteq \sem{F}\) and
      \(\varphi(0) = \omega\). Then, by \rref{def:flow}, we
      have \(\varphi(t) \in \sem{F}\) for all \(t \in [0,T]\). In
      particular, this implies \(\varphi(T) \in \sem{F}\).
    \item[C] Let \(\omega \in \states\) be a fixed state.
    Assume \(\omega \in \sem{[\daesys{\tuple{x}}{F \land G}]P}\). 
    Then, for all flows \(\varphi \in \analyticFlows{\tuple{x}}{-\epsilon, T+\epsilon}\) with \(\varphi([0,T]) \in \sem{F \land G}\) and \(\varphi(0) = \omega\) we have \(\varphi(T) \in \sem{P}\). Let \(\tilde{\varphi} \in \analyticFlowsInterval\) be a second flow with \(\varphi(0) = \omega\) and \(\varphi([0,T]) \in \sem{G \land F}\).
    By \(\sem{G \land F} = \sem{F \land G}\) we have \(\varphi([0,T]) \in \sem{F \land G}\).
    This implies \(\varphi(T) \in \sem{P}\). This implies \(\omega \in \sem{[\daesys{\tuple{x}}{G \land F}]P}\).
    The converse follows by symmetry.
    \item[DE] Let \(\omega \in \states\) be a fixed state. We need to
      show that \(\omega \in \sem{[\daesys{\tuple{x}}{e = 0}](e)' = 0}\). Let \(T \geq 0 \), \(\epsilon > 0\) and 
      \(\varphi \in
      \analyticFlowsInterval\) be an arbitrary flow with \(\varphi([0,T]) \in \sem{e = 0}\).  By assumption, we have \(\varphi(t)\sem{e} =
      0\) for all \(t \in [0,T]\).
      This implies
      \[\varphi(t)\sem{(e)'} = \frac{d \varphi(t)\sem{e}}{d t} = 0,\]
      by \rref{lem:diff}.
    \item[DX] Let \(\omega \in \sem{[\daesys{\tuple{x}}{F}]P}\).
      Then, for all \(T
      \geq 0\), \(\epsilon > 0\) and flows \(\varphi \in \analyticFlowsInterval\) with \(\varphi([0,T])
      \subseteq \sem{F}\) and \(\varphi(0) = \omega\), we have \(\varphi(T) \in \sem{P}\). To show \(\omega \in
      [?F]P\), we need to show if \(\omega \in \sem{F}\), then
      \(\omega \in \sem{P}\).
      Suppose \(\omega \not\in \sem{F}\), then the formula is trivially true. Otherwise, suppose \(\omega \in \sem{F}\) and choose \(T = 0\).
      Then, by \rref{rem:duration_zero},
      there exists one flow \(\varphi \in \analyticFlows{\tuple{x}}{-\epsilon, \epsilon}\) with \(\varphi(0)
      = \omega\).
      By assumption, this implies \(\omega = \varphi(0)
      \in \sem{P}\).
    \item[BDG] First, we show the implication \(\rightarrow\). For this direction we do not need the assumption of bounded growth: Let
    \(\omega \in \sem{[\daesys{\tuple{x}}{F}]P}\). Assume that \(\omega
    \in \sem{F}\). Otherwise, there is no flow that satisfies the
    differential constraint \(F\). Also, fix arbitrary \(T
    \geq 0, \epsilon > 0\) and a flow \(\varphi \in \analyticFlows{\tuple{x},\tuple{y}}{-\epsilon, T + \epsilon}\) with \(\varphi([0,T])
    \in \sem{F \land \tuple{y}'=g(\tuple{x},\tuple{y})}\) and \(\varphi(0) = \omega\). We need
    to show \(\varphi(T) \in \sem{P}\). In particular, we have
    \(\varphi([0,T]) \subseteq \sem{F}\). By assumption, this implies
    \(\varphi(T) \in \sem{P}\).

    Conversely, we show the implication \(\leftarrow\): Fix an arbitrary state \(\omega \in \sem{[\daesys{x}{F \land y'=g(x,y)}]||y||^2 \leq h(x,x')}\) and \(\omega \in \sem{[\daesys{\tuple{x}}{F \land \tuple{y}'=g(\tuple{x},\tuple{y})}]P}\). If \(\omega \not \in \sem{F}\), there are no \(T \geq 0, \epsilon > 0\) and flow \(\varphi \in \analyticFlowsInterval\) such that \(\varphi([0,T]) \subseteq \sem{F}\) and \(\varphi(0) = \omega\) and there is nothing to show.

    Assuming \(\omega \in \sem{F}\), take an arbitrary \(\varphi \in \analyticFlowsInterval\) with \(\varphi([0,T]) \subseteq \sem{F}\) and \(\varphi(0) = \omega\).
    Now, the idea is to construct a solution of the augmented system out of \(\varphi\) that has an equal interval of existence, and to exploit that \(P\) always holds after running that system.
    Define \(y(\cdot) : (-\delta,T_y) \rightarrow \R^m\) to be the right-maximal solution \cite[\S10.XI]{walter_ordinary_1998} of
    \[
      \frac{d y(t)}{dt}=g(\varphi(t)(\tuple{x}), y(t)), \quad y(0) = \omega(y).
    \]
    Observe that \(g(\varphi(\cdot)(\tuple{x}), \cdot)\) is a real-analytic function on \((-\epsilon,T+\epsilon)\) by \rref{lem:analytic}.
    Then, by the Cauchy-Kowalewsky Theorem \cite[Theorem 1.7.1]{krantz_primer_2002}, the solution is a real-analytic function on \((-\delta,T_y) \subseteq (-\epsilon, T + \epsilon)\).
    Now, we construct the mapping \(\varphi_y : (-\delta,T_y) \rightarrow \states\) with \(\varphi_y(z)(t) = \varphi(z)(t)\) on \(z \in (\tuple{y}\cup \tuple{y}')^\complement\), \(\varphi_y(t)(\tuple{y}) = y(t)\) and for all \(t \in (-\delta,T_y)\) and  \(\varphi_y(t)(\tuple{y}') = \frac{d y(t)}{dt}\) for \(t \in (-\delta,T_y)\).


    Now, we show \(T_y = T\). By assumption, we have 
    \[
      ||\varphi_y(\tau)(\tuple{y})||^2 \leq h(\varphi(\tau)(\tuple{x}), \varphi(\tau)(\tuple{x}')),
    \]
    for \(\tau \in [0,T]\).
    By the continuity of \(\varphi(\cdot)(\tuple{x})\) and \(\varphi(\cdot)(\tuple{x}')\), this implies \(||\varphi_y(\cdot)(\tuple{y})||^2\) attains its maximum on \([0,T]\).
    Therefore, the solution exhibits no blow up in finite time and by \cite[Theorem 1.4]{chicone_ordinary_2024}, this implies the domain of the solution is equal to the domain of definition of \(g(\varphi_y(\cdot)(\tuple{x}),\cdot)\), meaning \(T = T_y\).
    By the construction, the flows \(\varphi_y\) and \(\varphi\) only differ on \(\tuple{y} \cup \tuple{y}'\). By \rref{lem:coincidence}, this implies \(\varphi_y([0,T]) \subseteq \sem{F}\), because \(\tuple{y},\tuple{y}' \not \in F\).
    Therefore, we have \(\varphi_y([0,T]) \subseteq \sem{F \land \tuple{y}'=g(\tuple{x},\tuple{y})}\).
    Finally, by the assumption \(\omega \in \sem{[\daesys{\tuple{x}}{F \land \tuple{y}'=g(\tuple{x},\tuple{y})}]P}\), we have \(\varphi_y(T) \in \sem{P}\). 
    Again, using \rref{lem:coincidence}, implies \(\varphi(T) \in \sem{P}\), because \(\tuple{y},\tuple{y}' \not\in P\).

    \item[AG] First, we show the implication \(\rightarrow\): Let \(\omega \in \sem{[\daesys{\tuple{x}}{F}]P}\).
      Assume that \(\omega \in \sem{F}\). 
      Otherwise, there is no flow that satisfies the differential constraint \(F\). 
      Also, fix arbitrary \(T \geq 0, \epsilon > 0\) and a flow \(\varphi \in \analyticFlows{\tuple{x},\tuple{y}}{-\epsilon, T + \epsilon}\) with \(\varphi([0,T]) \subseteq \sem{F \land G(\tuple{y})}\) and \(\varphi(0) = \omega\). 
      We need to show \(\varphi(T) \in \sem{P}\).
      In particular, we have \(\varphi \subseteq \sem{F}\). 
      By assumption, this implies \(\varphi(T) \in \sem{P}\).

      Conversely, we show the implication \(\leftarrow\):
      Fix an arbitrary initial state \(\omega\) with \(\omega \in
      \sem{[\daesys{\tuple{x}}{F}]G(h(\tuple{x},\tuple{x}'))}\) and \(\omega \in \sem{\forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F\land G(\tuple{y})}]P}\).
      Fix \(T \geq 0, \epsilon > 0\) and an arbitrary flow \(\varphi \in \analyticFlowsInterval\) with \(\varphi([0,T]) \subseteq \sem{F}\) and \(\omega = \varphi(0)\). 
      We need to show that \(\varphi(T) \in \sem{F}\).
      By assumption, we have \(\varphi([0,T]) \subseteq \sem{G(h(\tuple{x},\tuple{x}'))}\).
      Now, we construct a mapping \(\varphi_y :(-\epsilon, T + \epsilon) \rightarrow \states\) with \(\varphi_y(0) = \omega\) and satisfies \(\varphi_y \subseteq \sem{F \land G(\tuple{y})}\), for any fresh variable \(\tuple{y},\tuple{y}' \not \in F, G, h(\cdot,\cdot)\).
      The key idea is that \(h\) implicitly defines a possible \(\tuple{y}\) as a function of \(\tuple{x}\) and \(\tuple{x}'\).
      Note that since, the term language of \dAL consists only of
      polynomial terms, \(h : \R^{2n} \rightarrow \R\) is a globally
      defined, real analytic function.
      This allows us to define \(\varphi_y\) as follows:
      \begin{align*}
        \varphi_y(t)(\tuple{y}) &= h(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}')), \\
        \varphi_y(t)(\tuple{y}') &=
        \frac{\partial h}{\partial
        x}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\varphi(t)(\tuple{x}') +
        \frac{\partial h}{\partial
        x'}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\frac{d \varphi(t)(\tuple{x}')}{dt}, \\
        \varphi_y(t)(z) &= \varphi(t)(z) \text{ on } z \in (\tuple{y}
        \cup \tuple{y}')^\complement.
      \end{align*}

        By \rref{lem:analytic}, we see that \(\varphi_y(\cdot)(\tuple{x})\) is analytic on \((-\epsilon, T + \epsilon)\), because
        \(\varphi(\cdot)(\tuple{x})\) is analytic on \((-\epsilon, T + \epsilon)\).  Also, \(\varphi_y\) is differentially consistent in \(\tuple{y},\tuple{y}'\) by:
      \begin{align*}
        \frac{d \varphi_y(t)}{dt}(\tuple{y}) &= \frac{\partial
        h}{\partial x}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\frac{d
        \varphi(t)}{dt}(\tuple{x}) +
        \frac{\partial h}{\partial
        x'}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\frac{d \varphi(t)(\tuple{x}')}{dt}\\
        &= \frac{\partial h}{\partial
        x}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\varphi(t)(\tuple{x}') +
        \frac{\partial h}{\partial
        x'}(\varphi(t)(\tuple{x}),\varphi(t)(\tuple{x}'))\frac{d \varphi(t)(\tuple{x}')}{dt}\\
        &= \varphi_y(t)(\tuple{y}').
      \end{align*}
      This implies \(\varphi_y \in \analyticFlowsInterval[y]\).
      Then by construction we have \(\varphi_y([0,T]) \subseteq \sem{F}\), by \rref{lem:coincidence} \(\tuple{y},\tuple{y}' \not\in F\), because \(\varphi\) and \(\varphi_y\) only differ on \(\tuple{y}\cup \tuple{y}'\).
      Also, we have \(\varphi_y([0,T])\subseteq \sem{G(\tuple{y})}\). 
      Therefore, we have \(\varphi_y(T) \in \sem{P}\) by \(\omega \in \sem{\forall \tuple{y}\forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F\land G(\tuple{y})}]P}\).
      By construction of \(\varphi_y\), we have \(\varphi(T) =
      \varphi_y(T)\) on \((\tuple{y}\cup \tuple{y}')^\complement\) and
      therefore \(\varphi(T) \in \sem{P}\), because
      \(\tuple{y},\tuple{y}' \not\in P\) and \rref{lem:coincidence}.
      \item[DI] We assume, without loss of generality, that \(P
        \equiv e(\tuple{x}) \geq 0\), where \((P)' \equiv (e(\tuple{x}))' \geq 0\).
        All other cases follow analogously.
        Fix an arbitrary state \(\omega \in \sem{[?F]P}\) and
        \(\omega \in \sem{F \rightarrow [\daesys{\tuple{x}}{F}](P)'}\).
        If \(\omega \not\in \sem{F}\), then there are no \(T \geq 0, \epsilon > 0\) and \(\varphi \in
        \analyticFlowsInterval\) that satisfy \(F\) and there is
        nothing to show.
        Otherwise, we have \(\omega \in
      \sem{[\daesys{\tuple{x}}{F}](P)'}\) and \(\omega \in \sem{P}\) by \(\omega \in
        \sem{[?F]P}\).
        Now, let \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\)
      be a flow with \(\varphi([0,T]) \subseteq \sem{F}\) and \(\varphi(0) =
        \omega\). The case \(T = 0\) follows immediately, because
        \(\varphi(0) = \omega \in \sem{P}\).
        Now, assume
      \(T > 0\) this implies \(0 \leq \varphi(\xi)\sem{(e(\tuple{x}))'} =
      \frac{d \varphi(t)\sem{e(\tuple{x})}}{dt}(\tau)\) for all \(\tau \in
      [0,T]\), by \rref{lem:diff}.
      By the mean value theorem we have \(\varphi(T)\sem{e(\tuple{x})} - \varphi(0)\sem{e(\tuple{x})} = T \frac{d\varphi(t)\sem{e(\tuple{x})}}{dt}(\xi)\) for some \(\xi \in (0,T)\),
        since \(\varphi(\cdot)\sem{e(\tuple{x})}\) is analytic.
        Therefore, we have \(\varphi(T)\sem{e(\tuple{x})} - \varphi(0)\sem{e(\tuple{x})} \geq 0\).
        By \(\varphi(0) \in \sem{e(\tuple{x}) \geq 0}\), this implies \(\varphi(T)
        \in \sem{e(\tuple{x}) \geq 0}\).
      \item[GS] Fix an arbitrary state \(\omega\) with \(\omega \in \sem{[\daesys{\tuple{x}}{F \lor G}](\consis{F}{G} \land \consis{G}{F})}\) and \(\omega \in
        \sem{F \lor G \rightarrow [\{\daesys{\tuple{x}}{F} \cup
      \daesys{\tuple{x}}{G}\}^*]P}\).
      We need to show \(\omega \in \sem{[\daesys{\tuple{x}}{F \lor G}]P}\): Assume \(\omega \in \sem{F
      \lor G}\).
      Otherwise, there is no flow satisfying the
      differential constraint \(F \lor G\) and there is nothing to prove.
      Now, fix \(T \geq 0, \epsilon > 0\) and \(\varphi \in \analyticFlowsInterval\) such that \(\varphi([0,T]) \subseteq \sem{F \lor G}\) and \(\varphi(0) = \omega\).
      Without loss of generality assume \(\omega \in \sem{F}\); the case \(\omega \in \sem{G}\) is analogous.
      Suppose there exists a monotonically increasing sequence \((\tau_{k})_{k \in \N_0}\) starting in zero with \(\varphi(0) = \varphi(\tau_0) = \omega\), \(\varphi(\tau_k) \in \sem{F}\) and \(\varphi(\tau_{k+1}) \in \sem{G}\) for \(k \geq 1\).
      Because we have \(\varphi([0,T]) \subseteq \sem{\consis{F}{G}}\) and \(\varphi([0,T]) \subseteq \sem{\consis{G}{F}}\) by assumption, using \rref{lem:seq}, there is a \(k_0 \in
      \N\) such that \(\varphi(\tau) \in \sem{F}\) for all \(\tau_{k_0} \leq \tau \leq T\) or  \(\varphi(\tau) \in \sem{G}\) for all \(\tau_{k_0} \leq \tau \leq T\).
      By \rref{lem:mode_consistency}, there exists a sequence \((t_k)_{k
      =0}^{k_0-1}\) with \(\tau_k \leq t_k \leq \tau_{k+1}\) such
      that \(\varphi([\tau_k, t_k]) \subseteq \sem{F}\) and
      \(\varphi([t_k, \tau_{k+1}]) \subseteq \sem{G}\) for all \(k < k_0\)
      and either \(\varphi([\tau_{k_0},T]) \subseteq \sem{F}\) or
      \(\varphi([\tau_{k_0},T]) \subseteq \sem{G}\).
      Next, we transform the loop assumption to apply it to the flow \(\varphi\). By \rref{def:pro}, we have
      \begin{align*}
        \omega &\in \sem{[\{\daesys{x}{F} \cup
        \daesys{\tuple{x}}{G}\}^*]P} = \bigcup_{k\in\N} \sem{[\{\daesys{\tuple{x}}{F} \cup
        \daesys{\tuple{x}}{G}\}^k]P}.
      \end{align*}
      In particular, this implies \(\omega \in \sem{[\{\daesys{\tuple{x}}{F} \cup
      \daesys{\tuple{x}}{G}\}^{k_0 + 1}]P}\).
      Unrolling the loop one step, we have \(\omega \in \sem{[\daesys{\tuple{x}}{F} \cup
      \daesys{\tuple{x}}{G}][\{\daesys{\tuple{x}}{F} \cup
      \daesys{\tuple{x}}{G}\}^{k_0}]P}\).
      By \rref{def:pro}, we have \(\omega \in \sem{[\daesys{\tuple{x}}{F}][\{\daesys{x}{F} \cup
      \daesys{\tuple{x}}{G}\}^{k_0}]P}\).
      We can inductively repeat this argument to obtain \(\omega \in \sem{[\daesys{\tuple{x}}{F}][\daesys{\tuple{x}}{G}]\dots[\daesys{\tuple{x}}{F}]P}\) and \(\omega \in \sem{[\daesys{\tuple{x}}{F}][\daesys{\tuple{x}}{G}]\dots[\daesys{\tuple{x}}{G}]P}\).
      By the construction of \(\varphi\), this implies \(\varphi([t_k, \tau_{k+1}])\subseteq \sem{P}\) for all \(k = 1,\dots, k_0-1\) or \(\varphi([\tau_{k_0}, T]) \subseteq \sem{P}\).
      This implies
      \[
        \varphi([0,T]) = \varphi([\tau_{k_0}, T]) \cup \bigcup_{k=0}^{k_0}\varphi([t_k, \tau_{k+1}])\subseteq \sem{P}.
      \]
      \qed
  \end{itemize}
\end{proof}

\subsection{Derived Rules}

\begin{proof}
  We derive the rules from the base axioms and proof rules:
  \begin{enumerate}
    \item[AR] We start the proof by using an algebraic ghost on the box in the consequent:
      \begin{prooftree}
              \AX$\fCenter [\daesys{\tuple{x}}{G}]P  \vdash  \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F\land G}]P$
              \AX$\fCenter \forall \tuple{x} \forall \tuple{x}'(F \rightarrow G) \vdash
              [\daesys{\tuple{x}}{F}]G$
              \def\defaultHypSeparation{\hskip 1pt}
        \LeftLabel{WL,AR}
              \BI$\fCenter \forall \tuple{x} \forall \tuple{x}'(F \rightarrow
            G),[\daesys{\tuple{x}}{G}]P
              \vdash  [\daesys{\tuple{x}}{F}]P$
        \LeftLabel{\impliesright}
              \UI$\fCenter \vdash \forall \tuple{x} \forall \tuple{x}' (F \rightarrow G) \rightarrow
              ([\daesys{\tuple{x}}{G}]P \rightarrow [\daesys{\tuple{x}}{F}]P)$
      \end{prooftree}
      Note that we have the side condition \(\tuple{y},\tuple{y}' \not \in F,G\). This can be enforced by using fresh variables \(\tuple{y},\tuple{y}'\).
      We use the derived axiom \[\gray{\text{DW}\rightarrow} \quad [\daesys{\tuple{x}}{F}]G \leftrightarrow [\daesys{\tuple{x}}{F}](F \rightarrow G),\] which can be derived from K, DW and G.
      Using this axiom and the G rule, we can use
      the algebraic condition to close the right goal:
      \begin{prooftree}
              \AX$\fCenter *$
        \LeftLabel{\(\R\)}
              \UI$\forall \tuple{x} \forall \tuple{x}'(F \rightarrow G)\fCenter\,\vdash F \rightarrow G$
        \LeftLabel{\g}
              \UI$\forall \tuple{x} \forall \tuple{x}'(F \rightarrow G)\fCenter\,\vdash [\daesys{\tuple{x}}{F}](F \rightarrow G)$
        \LeftLabel{\dwimplies}
              \UI$\forall \tuple{x} \forall \tuple{x}'(F \rightarrow G)\fCenter\,\vdash [\daesys{\tuple{x}}{F}]G$
      \end{prooftree}
      The application of the G rule is sound, because we have \[\BV{\daesys{\tuple{x}}{F}} \cap \FV{\forall x \forall x'(F \rightarrow G)} = \varnothing.\]
      Finally, we use the C and DR axioms, to remove \(F\)
      from the box in the goal to finish the proof:
      \begin{prooftree}
        \AX$\fCenter \quad \quad \quad \quad \;\;*$
        \LeftLabel{id}
        \UI$\fCenter[\daesys{\tuple{x}}{G}]P  \vdash  [\daesys{\tuple{x}}{G}]P$
        \LeftLabel{DR}
        \UI$\fCenter[\daesys{\tuple{x}}{G}]P  \vdash  \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{G\land F}]P$
        \LeftLabel{C}
        \UI$\fCenter[\daesys{\tuple{x}}{G}]P  \vdash  \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F\land G}]P$
      \end{prooftree}
      \item[DC] We derive the differential cut axiom. First, use the implies right rule:
      \begin{prooftree}
        \AX$\fCenter [\daesys{\tuple{x}}{F}]G \vdash [\daesys{\tuple{x}}{F \land G}]P \leftrightarrow[\daesys{\tuple{x}}{F}]P$
        \LeftLabel{\(\rightarrow\)R}
        \UI$\fCenter \vdash [\daesys{\tuple{x}}{F}]G \rightarrow \left([\daesys{\tuple{x}}{F \land G}]P \leftrightarrow[\daesys{\tuple{x}}{F}]P\right)$
      \end{prooftree}
      We split the equivalence into two goals:
      \begin{prooftree}
        \AX$\fCenter [\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F}]P \vdash [\daesys{\tuple{x}}{F \land G}]P$
        \AX$\fCenter [\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F \land G}]P \vdash [\daesys{\tuple{x}}{F}]P$
        \LeftLabel{\(\leftrightarrow\)}
        \BI$\fCenter [\daesys{\tuple{x}}{F}]G \vdash [\daesys{\tuple{x}}{F \land G}]P \leftrightarrow[\daesys{\tuple{x}}{F}]P$
      \end{prooftree}
      For the first goal, we use the AG axiom to augment the system with the ghost variable \(y\) using the formula \(\top \equiv x^2 \geq 0\), which holds in all states. This augmentation does not change the behavior of the systems but allows us to add the unrestricted ghost variable \(y\).
      \begin{prooftree}
        \AX$\fCenter  \; *$
        \LeftLabel{\(\R\)}
        \UI$\fCenter  \; \vdash \top$
        \LeftLabel{G}
        \UI$ \fCenter \; \vdash [\daesys{\tuple{x}}{F \land G}]\top$
        \AX$[\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F}]P \fCenter \;\vdash \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F \land G \land \top}]P$
        \LeftLabel{AG}
        \BI$[\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F}]P \fCenter \;\vdash [\daesys{\tuple{x}}{F \land G}]P$
      \end{prooftree}
      Now, we use the AR to get rid of the additional formula and close the remaining goal:
      \begin{prooftree}
        \AX$\fCenter *$
        \LeftLabel{id}
        \UI$[\daesys{\tuple{x}}{F}]P \fCenter \;\vdash [\daesys{\tuple{x}}{F}]P$
        \LeftLabel{DR}
        \UI$[\daesys{\tuple{x}}{F}]P \fCenter \;\vdash \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F \land G}]P$
        \LeftLabel{AR}
        \UI$[\daesys{\tuple{x}}{F}]P \fCenter \;\vdash \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F \land G \land \top}]P$
      \end{prooftree}
      The second goal can be derived analogously.
      \begin{prooftree}
        \AX$\fCenter *$
        \LeftLabel{id}
        \UI$[\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F \land G}]P \; \fCenter \vdash [\daesys{\tuple{x}}{F \land G}]P$
        \LeftLabel{R,AR}
        \UI$[\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F \land G}]P \; \fCenter \vdash \forall \tuple{y} \forall \tuple{y}'[\daesys{\tuple{x},\tuple{y}}{F \land G}]P$
        \LeftLabel{AG}
        \UI$[\daesys{\tuple{x}}{F}]G, [\daesys{\tuple{x}}{F \land G}]P \; \fCenter \vdash [\daesys{\tuple{x}}{F}]P$
      \end{prooftree}
      \item[\(\land\)DE] Splitting the equivalence, we have:
      \begin{prooftree}
        \AX$\fCenter [\daesys{\tuple{x}}{F \land e =
        0}]P\vdash  [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P$
        \noLine
        \UI$\fCenter [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P\vdash [\daesys{\tuple{x}}{F \land e =
        0}]P$
        \LeftLabel{\(\leftrightarrow\)}
        \UI$\fCenter \vdash [\daesys{\tuple{x}}{F \land e =
        0}]P \leftrightarrow [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P$
      \end{prooftree}
      The first proof goal follows from R. We transform the second goal using DC:
      \begin{prooftree}
        \AX$\fCenter [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P\vdash [\daesys{\tuple{x}}{F \land e =
        0 \land (e)' = 0}]P$
        \noLine
        \UI$\fCenter [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P\vdash [\daesys{\tuple{x}}{F \land e =
        0}](e)'= 0$
        \LeftLabel{DC}
        \UI$\fCenter [\daesys{\tuple{x}}{F \land e = 0 \land (e)' = 0}]P\vdash [\daesys{\tuple{x}}{F \land e =
        0}]P$
      \end{prooftree}
      Finally, the first goal closes by id and the second goal by AR and DE.
  \end{enumerate}
  \qed
\end{proof}

\section{Extended Example Proofs} \label{sec:examples}
In this section, we show the detailed proof to close the goal involving the mode consistency formula. Using the \(G\) rule we get rid of the box modality we obtain
\begin{prooftree}
  \AX$\fCenter \vdash \consisxy{G(x,y)}{F(x,y)}$
  \AX$\fCenter \vdash \consisxy{F(x,y)}{G(x,y)}$
  \LeftLabel{\(\land\)R}
  \BI$\fCenter \vdash \consisxy{F(x,y)}{G(x,y)} \land \consisxy{G(x,y)}{F(x,y)}$
  \LeftLabel{G}
  \UI$\fCenter \vdash [\{\daesys{x}{F(x,y) \lor G(x,y)}\}](\consisxy{F(x,y)}{G(x,y)} \land \consisxy{G(x,y)}{F(x,y)})$
\end{prooftree}
This leaves two open goal to prove. We proceed by computing the entry and exit formulas of $F(x,y)$ and $G(x,y)$.
The exit formula of $F(x,y)$ is given by:
\begin{align*}
    &\exit{\daesys{x}{F(x,y)}} \equiv \\
    &\quad (x' = 0 \land x^2=1 \land y = 0) \land \progress{\daesys{x,y}{x' \neq 0 \lor x^2 \neq 1 \lor y \neq 0}}\\
    &\quad\quad\lor (x' \neq 0 \lor x^2 \neq 1 \lor y \neq 0) \land \progress{\daesys{x,y}{x' = 0 \land x^2=1 \land y = 0}}^- \\
\end{align*}
This implies \(\exit{\daesys{x}{F(x,y)}} \equiv x' = 0 \land x^2=1 \land y = 0\).
Its entry formula is given by:
\begin{align*}
  &\enter{\daesys{x}{F(x,y)}} \equiv \\
  &\quad \progress{\daesys{x,y}{x' = 0 \land x^2=1 \land y = 0}} \land (x' \neq 0 \lor x^2 \neq 1 \lor y \neq 0)\\
  &\quad\quad\lor \progress{\daesys{x,y}{x' \neq 0 \lor x^2 \neq 1 \lor y \neq 0}}^- \land (x' = 0 \land x^2=1 \land y = 0) \\
\end{align*}
This also simplifies to \(\enter{\daesys{x}{F(x,y)}} \equiv x' = 0 \land x^2=1 \land y = 0\).

The exit formula of $G(x,y)$ is given by:
\begin{align*}
  &\exit{\daesys{x,y}{G(x,y)}} \equiv \\
  &\progress{\daesys{x,y}{x' \neq y \lor x^2 + y^2 \neq 1  \lor y'\neq -x}} \land (x' = y \land x^2 + y^2 = 1  \land y'=-x)\\
  &\quad \lor \progress{\daesys{x,y}{x' = -y \land x^2 + y^2 = 1  \land y'=x}}^- \land x' \neq y \lor x^2 + y^2 \neq 1  \lor y'\neq -x\\
\end{align*}
This simplifies to \(\exit{\daesys{x,y}{G(x,y)}} \equiv x' = y \land x^2 + y^2 = 1  \land y'=-x\).
Finally, the entry formula of G(x,y) is given by:
\begin{align*}
  &\enter{\daesys{x,y}{G(x,y)}} \equiv \\
  &\progress{\daesys{x,y}{x' = y \land x^2 + y^2 = 1  \land y'=-x}} \land x' \neq y \lor x^2 + y^2 \neq 1  \lor y'\neq -x\\
  &\quad\lor \progress{\daesys{x,y}{x' \neq -y \lor x^2 + y^2 \neq 1  \lor y'\neq x}}^- \land (x' = y \land x^2 + y^2 = 1  \land y'=-x)\\
\end{align*}
Which also simplifies to \(\enter{\daesys{x,y}{G(x,y)}} \equiv x' = y \land x^2 + y^2 = 1  \land y'=-x\).
Now, using the computed formulas, we can easily verify using real arithmetic reasoning that both 
\begin{align*}
  \exit{\daesys{x}{F(x,y)}} \land  \enter{\daesys{x,y}{G(x,y)}} &\vdash F(x,y) \leftrightarrow G(x,y),\\
  \exit{\daesys{x}{G(x,y)}} \land  \enter{\daesys{x,y}{F(x,y)}} &\vdash F(x,y) \leftrightarrow G(x,y).
\end{align*}
This finishes the proof.
