\begin{algorithm}[h]
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\caption{The Pseudo-code of CLUE with $n$-level Label, $n-1$ Stages and $M$ Voters}
\label{algorithm: iterative_category_assignment}
\begin{algorithmic}[1]
\REQUIRE \textbf{The query $q$, clicked documents set $\{d : d \in D_c\}$, user behavior context information set $\{i : i \in I\}$}\\
\STATE  $X \leftarrow \{x : x \text{ is initialized as } (q, d, i)\}$
\STATE  $Y \leftarrow \{y : y \text{ is initialized as } 0\}$
\FOR{stage $k = n, n-1, \ldots, 2$}
    \FORALL{voters $j$ in $\{1, \ldots, M\}$} 
        \FORALL{\( x \) in \( X \)}
            \IF{$LLM(Prompt_k^j(x))$ is True}
                    \STATE $\text{VoteCount}_k (x) \gets \text{VoteCount}_k(x) + 1$
            \ENDIF
        \ENDFOR
    \ENDFOR
    \FORALL{\( x \) in \( X \)}
        \IF{$\text{VoteCount}_k(x) > \frac{M}{2}$}
            \STATE Assign $y = C_k$
            \STATE \( X \leftarrow X \setminus \{x\} \)
        \ENDIF
    \ENDFOR
\ENDFOR
\FORALL{\( x \) in \( X \)}
    \STATE Assign $y = C_1$
\ENDFOR
\ENSURE \textbf{$n$-level usefulness judgment $\{y : y \in Y\}$ of all clicked document $\{d : d \in D_c\}$}
\end{algorithmic}
\end{algorithm}
