\begin{algorithm}[t]
    \caption{SAC-DARTS}
    \label{alg:pcb}
    \begin{algorithmic}[1]
	\State Initialize architecture parameter $\alpha$; edge weights $\gamma$; Network weights $w$; Number of search epochs $E$;
	\State Construct a supernet and initialize architecture parameters $\alpha$, edge weights $\gamma$, and supernet weights $w$;
	\State Create a mixed operation $\Bar{o}^{i,j}$ parameterized by $\alpha^{(i,j)}$ for each edge $(i,j)$
	\For{each epoch $e \in [1, E]$} 
		\State 
		\State Update architecture parameters $\alpha$ by descending first-order $\triangledown_{\alpha} L_{val}(w,\alpha) + \lambda_e L_{SA}$
		\State Update network weights $w$ by descending $\triangledown_{w}L_{train}$ 
	\EndFor
	\State Finally, DERIVE() the final architecture.
	\State
	\Function{Derive}{$\alpha$, $\gamma$, $OPS$}
		\State For each edge between nodes, calculate the selection value $v = \alpha * \gamma$, and keep the operation with the $\argmax_{op \in OPS}(\alpha_{op} * \gamma_{op})$, and delete the rest operations.
		\State For each node in cell, keep 2 incoming edges: $ o^{(i,j)} = \argmax_{o \in O}(\alpha_o^{(i,j)})$
		\State \Return structure list
	\EndFunction
	\State
	\Function{Mixed Operation}{$x$, $OPS$, $\beta$, $k$}
		\State Shuffle channels then divide input $x$ to $x_1$ and $x_2$ according to partial channel ratio $k$.
		\State Apply all operations $OPS$ on $x_1$ with weights $\beta$:  $x_1' = \sum_{op \in OPS}(\beta_{op} * op(x_1))$
		\State \Return Concate($x_1'$, $x_2$)
	\EndFunction
	\end{algorithmic}
\end{algorithm}



