\subsection{More analysis on Equation~\ref{eqn:alpha_conv}}\label{sec:app_skip_dom}

The objective can be formulated as: 
$\text{min}_{\beta_{conv}, \beta_{skip}, \beta_{avg}} Var(\overline{m} (x) - m^*)$, such that $\beta_{conv} + \beta_{skip} + \beta_{avg} = 1$.


This constraint optimization problem can be solved with Lagrangian multipliers:
\begin{multline}
    {\cal L}(\beta_{conv}, \beta_{skip}, \beta_{avg},\lambda)=Var(\overline{m}(x)-m^*)- \\ \lambda(\beta_{conv} + \beta_{skip} + \beta_{avg}-1)\\
    =Var(\beta_{conv}o_c(x) + \beta_{skip} x + \beta_{avg} o_a(x)-m^*)- \\ \lambda(\beta_{conv} + \beta_{skip} + \beta_{avg}-1)\\
     =Var(\beta_{conv}(o_c(x)-m^*) + \beta_{skip}(x-m^*) + \beta_{avg} (o_a(x)-m^*)) \\ -\lambda(\beta_{conv} + \beta_{skip} + \beta_{avg}-1)\\
\end{multline}

Expanding Variance term and introducing covariance:
\begin{multline}
    =Var(\beta_{conv}(o_c(x)-m^*) + Var(\beta_{skip}(x-m^*)) + \\ Var(\beta_{avg} (o_a(x)-m^*)) + \\
    2Cov(\beta_{skip}(x-m^*),\beta_{avg} (o_a(x)-m^*))+\\
    2Cov(\beta_{conv}(o_c(x)-m^*),\beta_{avg} (o_a(x)-m^*))+\\
    2Cov(\beta_{conv}(o_c(x)-m^*),\beta_{skip}(x-m^*)) - \\ \lambda(\beta_{conv} +     \beta_{skip} + \beta_{avg}-1)\\  
\end{multline}

\begin{multline}
    =\beta_{conv}^2Var(o_c(x)-m^*) + \beta_{skip}^2Var(x-m^*) + \\ \beta_{avg}^2 Var(o_a(x)-m^*) + \\
    2\beta_{skip}\beta_{avg}Cov((x-m^*), (o_a(x)-m^*))+\\
    2\beta_{conv}\beta_{avg}Cov((o_c(x)-m^*), (o_a(x)-m^*))+\\
    2\beta_{conv}\beta_{skip}Cov((o_c(x)-m^*),(x-m^*)) - \\ \lambda(\beta_{conv} +     \beta_{skip} + \beta_{avg}-1)\\  
\end{multline}



Setting:
$\frac{\partial L}{\partial\lambda}, \frac{\partial L}{\partial\beta_{c o n v}}, \frac{\partial L}{\partial\beta_{s k i p}}, \frac{\partial L}{\partial\beta_{avg}}$ all to be 0.


\begin{multline}
    \frac{\partial L}{\partial\lambda}=\beta_{conv} +     \beta_{skip} + \beta_{avg}-1=0\\
    \frac{\partial L}{\partial\beta_{c o n v}}=2\beta_{c o n v}V a r(o_{c}(x)-m^{*})+ \\
2\beta_{avg}Cov((o_c(x)-m^*), (o_a(x)-m^*)) + \\
2\beta_{skip}Cov((o_c(x)-m^*),(x-m^*)) -\lambda = 0
\end{multline}

\begin{multline}
    \frac{\partial L}{\partial\beta_{skip}}=2\beta_{skip}V a r(x-m^{*})+\\
2\beta_{avg}Cov((x-m^*), (o_a(x)-m^*)) + \\
2\beta_{conv}Cov((o_c(x)-m^*),(x-m^*)) -\lambda = 0
\end{multline}

\begin{multline}
    \frac{\partial L}{\partial\beta_{avg}}=2\beta_{avg}V a r(o_{a}(x)-m^{*})+\\
2\beta_{skip}Cov((x-m^*), (o_a(x)-m^*)) + \\
2\beta_{conv}Cov((o_c(x)-m^*),(o_a(x)-m^*)) -\lambda = 0
\end{multline}

Following the 2 operator case in \cite{wang2021rethinking}, we can solve the above equations by recursion.

From the Equation~\ref{eqn:alphaconv} - \ref{eqn:alphaavg}, it is clear that the relative magnitudes of $\alpha_{conv}^*$, $\alpha_{skip}^*$, and $\alpha_{skip}^*$ greatly depend on whether an operation being applied takes it closer to the optimal feature map. 
While $x$ comes from the mixed output of the previous edge, it will naturally be closer to $m^*$, $O_a(x)$ is an average pooling, which will be slightly off but very consistent, and $O_c(x)$ is the output of a single convolution operation, which is inconsistent during training, becoming the furthest.
% Therefore, a better supernet will introduce a larger gap between $\beta_{conv}$ and $\beta_{skip}$ because $x_e$ gets closer and closer to $m*$ as the supernet is optimized.
% As a result, it introduces the operations with better initial performance are more likely to maintain higher coefficients

Following the simplified search space in Section~\ref{sec:peformancecollapse}, it can be easily inferred that $\alpha_{skip}$, $\alpha_{conv}$, and $\alpha_{avg}$:

\begin{multline}\label{eqn:alpha_convapp}
    \exp(\alpha_{conv}) = \text{Var}(x-\overline{m} (x))+\text{Var}(o_a(x)-\overline{m} (x)) - \\ \text{Cov}(x-\overline{m} (x), o_c(x)-\overline{m} (x), o_a(x)-\overline{m} (x)) + C
\end{multline}

\begin{multline}\label{eqn:alpha_skip}
    \exp(\alpha_{skip}) = \text{Var}(o_c(x)-\overline{m} (x))+  \text{Var}(o_a(x)-\overline{m} (x)) - \\  \text{Cov}(x-m^*, o_c(x)-m^*, o_a(x)-m^*) + C
\end{multline}

\begin{multline}\label{eqn:alpha_avg}
    \exp(\alpha_{avg}) = \text{Var}(x-\overline{m} (x))+\text{Var}(o_c(x)-\overline{m} (x)) - \\ \text{Cov}(x-\overline{m} (x), o_c(x)-\overline{m} (x), o_a(x)-\overline{m} (x)) + C
\end{multline}


Therefore, to reduce the value of $\text{Var}(o_c(x)-\overline{m} (x))+\text{Var}(x-\overline{m} (x))+\text{Var}(o_a(x)-\overline{m} (x))$, we can choose a smaller value for $\alpha$, such that $\exp(\alpha)$ is small.

