    \end{equation}
    \vspace*{-1mm}
    {Further, for any $\lambda\in\mathcal{X}^*$, let each of the sets}
    {\begin{equation}\label{eq:subset}
        \{h_i(P_i)+\mathcal{A}^*_{P_i}\lambda : P_i\in\mathcal{P}_i\}
    \end{equation}}
    {be totally ordered by $\mathcal{X}^*$.}
\end{assumption}

\begin{remark}
    {While the number of partitions $n$ is in general unrelated to the dimension of the state, choosing these to coincide is often a convenient way to ensure that the sets \eqref{eq:subset} satisfy Assumption \ref{as:1}. In the examples of SSP and LDP, this corresponds to a coordinate-wise decomposition of the optimization problem, while in the case of LQR it is shown below that this condition is fulfilled by a rank-1 decomposition of the Bellman equation.}
\end{remark}

\begin{remark}
    Notably, while \eqref{eq:optprob} is limited to linear operators $\mathcal{A}_P$, the requirements on $\mathcal{P}$ and $h(P)$ allow for the modeling of systems with input nonlinearities. This is illustrated in the case of LDP in Section V.
