\section{Proofs of Intermediate Lemmas}
\label{sec:lemmas_pfs}

We now prove the intermediate lemmas.

\begin{proof}[Proof of \cref{lastLemma}]
We define the following empirical risk functions:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \hat{R}_P(p_\vw)&=\frac{1}{N_r}\sum_{i=1}^{N_r}\left(\partial_tp_\vw(\vx_{ri}, t_{ti})-\nabla^2p_\vw(\vx_{ri}, t_{ti})+\norm{\nabla p_\vw(\vx_{ri}, t_{ti})}_2^2\right)^2 \\
		&\quad+ \frac{\lambda_0}{N_0}\sum_{j=1}^{N_0}\left(p_\vw(\vx_{0j},0)-g(\vx_{0j})\right)^2\\
    \hat{R}_S(p_\vw)&=\frac{1}{N_s}\sum_{k=1}^{N_s}(p_\vw(\vx_{sk},t_{sk})-y_{sk})^2.
\end{align*}
Recalling the expression from \cref{def:hjbloss}, we obtain $\hat{R}(p_\vw)=\hat{R}_P(p_\vw)+\lambda_s\hat{R}_S(p_\vw)$.


Let $\phi_i=\E[y_{si}|(\vx_{si},t_{si})]$, $z_i = y_{si} - \phi_i$, and 
$\sigma^2=\frac{1}{N_s}\sum_{i=1}^{N_s}\E[z_i^2]$.
For a given $p_\vw$, define
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
Z=\frac{1}{\sqrt{N_s}}(z_1,z_2,...,z_{N_s}), ~G=\frac{1}{\sqrt{N_s}}(\phi_1,\phi_2,...,\phi_{N_s}),
$$
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
F=\frac{1}{\sqrt{N_s}}(p_\vw(\vx_1,t_1),p_\vw(\vx_2,t_2),...,p_\vw(\vx_{N_s},t_{N_s})).
$$
Thus we have, $\norm{G+Z-F}^2=\hat{R}(p_\vw) - \hat{R}_P(p_\vw)$. Further suppose $\norm{Z}^2\geq\sigma^2-\frac{\eta}{6}$ and $\ip{Z}{G}\geq-\frac{\eta}{6}$. Then
\begin{align*}
\norm{Z+G-F}^2&=\norm{Z}^2+2\ip{Z}{G-F} + \norm{G-F}^2=\norm{Z}^2+2\ip{Z}{G}-2\ip{Z}{F}+\norm{G-F}^2\\
&\geq\sigma^2-\frac{\eta}{2}-2\ip{Z}{F}.
\end{align*}
The above assumptions imply that
\begin{align}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber \hat{R}(p_\vw)=\lambda_s\norm{Z+G+F}^2 + \hat{R}_P(p_\vw)\geq\lambda_s(\sigma^2-\frac{\eta}{2}-2\ip{Z}{F}) + \hat{R}_P(p_\vw).
\end{align}
Define the following events:
\begin{align}\label{eq:E1-3def}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber \mE_1 = \left\{\norm{Z}^2\geq\sigma^2-\frac{\eta}{6}\right\}&,\mE_2 = \left\{\ip{Z}{G}\geq-\frac{\eta}{6}\right\},\mE_3 = \left\{\exists ~p_\vw\in\gH|\hat{R}(p_\vw)\leq\sigma^2-\mu\eta\right\}\\
    \mE_4=&\left\{\exists ~p_\vw\in\gH|\ip{F}{Z}\geq\frac{1}{2\lambda_s}\left(\mu\eta - \sigma^2\right) + \left(\frac{1}{2}\sigma^2 - \frac{1}{4}\eta\right)\right\}.
\end{align}
If $\mE_1,\mE_2,$ and $\mE_3$ hold, then $\mE_4$ holds. Hence, $\Pr(\mE_1 \cap \mE_2 \cap \mE_3)\leq\Pr(\mE_4) $ implies that $  \Pr(\mE_4)\geq 1-\Pr((\mE_1 \cap \mE_2 \cap \mE_3)^c)$. Since $\Pr(\mE_1^c \cup \mE_2^c \cup \mE_3^c)\leq\Pr(\mE_1^c)+\Pr(\mE_2^c)+\Pr(\mE_3^c)\leq 3 - (\Pr(\mE_1)+\Pr(\mE_2)+\Pr(\mE_3))$, this can be combined with the previous bound to get $\Pr(\mE_4)\geq-2+(\Pr(\mE_1)+\Pr(\mE_2)+\Pr(\mE_3))$ and hence
\begin{align}\label{eq:prob}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr(\mE_3)\leq 2-\Pr(\mE_1)-\Pr(\mE_2)+\Pr(\mE_4).
\end{align}
From the assumptions on the labels given in \cref{lossfunction}, the bound of the labels is $|y_{si}|<M$, which implies that $\abs{z_i}=\abs{y_{si}-\E[y_{si}|(\vx_{si},t_{si})]}\leq2M$. This also means $\E[z_{i}|(\vx_{si},t_{si})]=0$ and that $0\leq z_i^2\leq4M^2$.

By Hoeffding's inequality \cite{hoeffding1963probability} \footnote{\begin{theorem}[Hoeffding's Inequality]\label{lem:hoeff}    Let $Z_1$,\ldots,$Z_n$ be independent bounded random variables with $Z_i\in[a,b]$ for all $i$, where $-\infty<a\leq b<\infty$. Then, for all $t\geq0$,
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr(\frac{1}{n}\sum_{i=1}^n(Z_i-\E[Z_i])\geq t)\leq\exp{-\frac{2nt^2}{(b-a)^2}},\quad \Pr(\frac{1}{n}\sum_{i=1}^n(Z_i-\E[Z_i])\leq -t)\leq\exp{-\frac{2nt^2}{(b-a)^2}}.
$$
\end{theorem}} (with $a=0,b=4M^2,n=N_s,t=\eta/6,Z_i=z_i^2$ in \cref{lem:hoeff}),
\begin{align}\label{eq:E1bound}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \Pr\left(\frac{1}{N_s}\sum_{i=1}^{N_s}z_i^2\leq\sigma^2-\frac{\eta}{6}\right)\leq\exp\left(-\frac{N_s\eta^2}{288M^4}\right) \text{ hence } 1-\Pr(\mE_1)\leq\exp\left(-\frac{N_s\eta^2}{288M^4}\right).
\end{align}
In the above, we have used the definition of $\mE_1$ from \cref{eq:E1-3def}. The expectation of $z_i\E[y_{si}|(\vx_{si},t_{si})]=\E[z_i]$ since $\E[y_{si}|(\vx_{si},t_{si})]$ is constant with respect to $(\vx_{si},t_{si})$, so $\E[z_i\mE[y_{si}|(x_{si},t_{si})]=0$. The bound on $z_i\E[y_{si}|(\vx_{si},t_{si})]$ would use the bound of $\abs{z_i}\leq2M$ and $\abs{\E[y_{si}|(\vx_{si},t_{si})]}\leq M$.
Therefore Hoeffding's inequality (with $a=-2M^2,b=2M^2,n=N_s,t=\eta/6,Z_i=z_i\E[y_{si}|(\vx_{si},t_{si})]$ in \cref{lem:hoeff}) can be used again to show that

\begin{align}\label{eq:E2bound}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \Pr\left(\frac{1}{N_s}\sum_{i=1}^{N_s}z_i\E[y_{si}|(\vx_{si},t_{si})]\leq-\frac{\eta}{6}\right)\leq\exp\left(-\frac{N_s\eta^2}{288M^4}\right)\text{ hence }1-\Pr(\mE_2)\leq\exp\left(-\frac{N_s\eta^2}{288M^4}\right).
\end{align}
Here, we used the definition of $\mE_2$ from \cref{eq:E1-3def} above. Substituting \cref{eq:E1bound,eq:E2bound} into \cref{eq:prob}, we see that
\begin{align}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber \Pr(\mE_3)\leq2\exp\left(-\frac{N_s\eta^2}{288M^4}\right)+\Pr(\mE_4).
\end{align}
We can rewrite this using the definitions of $\mE_3$ and $\mE_4$ from \cref{eq:E1-3def} to obtain,
\begin{align}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber &\Pr\left(\exists ~p_\vw\in\gH|\hat{R}(p_\vw)\leq\sigma^2-\mu\eta\right)\\
    &\leq2\exp\left(-\frac{N_s\eta^2}{288M^4}\right)+\Pr\left(\exists ~p_\vw\in\gH|\frac{1}{N_s}\sum_{i=1}^{N_s}p_\vw(\vx_{si},t_{si})z_i\geq\frac{1}{2\lambda_s}\left(\mu\eta - \sigma^2\right) + \left(\frac{1}{2}\sigma^2 - \frac{1}{4}\eta\right)\right),
\end{align}
which finishes the proof.
\end{proof}

\begin{proof}[Proof of \cref{secondLemma}]
Recalling the definition of $z_i$ from \cref{thm:main}, let $S=\frac{1}{2\lambda_s}\left(\mu\eta - \sigma^2\right) + \left(\frac{1}{2}\sigma^2 - \frac{1}{4}\eta\right)$ and let the events $\mE_5$ and $\mE_6$ be
\begin{align}\label{def:E5E6}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \mE_5=\left\{\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}z_i}\geq\frac{S}{2C_1}\right\}, \quad\mE_6=\left\{\exists h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}\E[h_{\vw_{\frac{\eta}{2}}}]z_i>\frac{S}{2}\right\}.
\end{align}
Since $\frac{1}{C_1}|\E[h_{\vw_{\frac{\eta}{2}}}]|\in[0,1]$, if $\mE_5^c$ happens then for such a sample of $\left\{z_i,i=1,...,n\right\}$,
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\frac{S}{2C_1}>\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}z_i}\geq\frac{1}{C_1}\abs{\E[h_{\vw_{\frac{\eta}{2}}}]}\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}z_i}\geq\frac{1}{N_sC_1}\sum_{i=1}^{N_s}\E[h_{\vw_{\frac{\eta}{2}}}]z_i\quad\forall h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta.
$$
Hence,  $\mE_5^c$ implies $\mE_6^c$ and 
\begin{align}\label{eq:E6<E5}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr(\mE_6)\leq\Pr(\mE_5).
\end{align}
We recall the calculation done in \cref{lastLemma} that $|z_i|\leq2M$ and that $\E[z_i|(\vx_{si},t_{si})]=0$.
By Hoeffding's inequality (setting $a=-2M,b=2M,n=N_s,t=S/2C_1,Z_i=z_i$ in \cref{lem:hoeff}), 
\begin{align}\label{eq:E5bound}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \Pr(\mE_5)=\Pr \left (\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}z_i}\geq\frac{S}{2C_1} \right )\leq2\exp{\frac{-N_sS^2}{32M^2C_1^2}}.
\end{align}
Further, Define the following three events:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\mE_7&=\left\{\forall h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i\leq\frac{S}{2}\right\},\\
\mE_8&=\left\{\forall h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}\E[h_{\vw_{\frac{\eta}{2}}}]z_i\leq\frac{S}{2}\right\},\\
\mE_9&=\left\{\forall h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})z_i\leq S\right\}.
\end{align*}
Since $\mE_9$ holds if $\mE_7$ and $\mE_8$ hold so that $\Pr(\mE_7\cap\mE_8)\leq\Pr(\mE_9)$, we have
\begin{align}\label{baseineq}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr(\mE_9^c)\leq\Pr(\mE_7^c)+\Pr(\mE_8^c).
\end{align}
Considering $\Pr(\mE_8^c)$ and using the definition of $\mE_6$ from \cref{def:E5E6}, and the inequalities from \cref{eq:E6<E5,eq:E5bound}, we see that
\begin{align}\label{e8}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \Pr(\mE_8^c)&=\Pr\left(\exists h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}\E[h_{\vw_{\frac{\eta}{2}}}]z_i>\frac{S}{2}\right)=\Pr(\mE_6)\leq\Pr(\mE_5)\leq2\exp{\frac{-N_sS^2}{32M^2C_1^2}}.
\end{align}

Upper-bounding $\Pr(\mE_7^c)$ shows that
\begin{align}\label{e7}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber \Pr(\mE_7^c)&=\Pr\left(\exists h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i>\frac{S}{2}\right)\\
    \nonumber &\leq\Pr\left(\bigcup_{h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta}\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i}\geq\frac{S}{2}\right)\\
    &\leq\sum_{h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta}\Pr\left(\abs{\frac{1}{N_s}\sum_{i=1}^{N_s}\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i}\geq\frac{S}{2}\right).
\end{align}
Again, using Hoeffding’s inequality (with $a=-4MC_1,b=4MC_1,n=N_s,t=S/2,Z_i=\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i$ in \cref{lem:hoeff}),
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr\left(\frac{1}{N_s}\sum_{i=1}^{N_s}\abs{\left(h_{\vw_{\frac{\eta}{2}}}(\vx_{si},t_{si})-\E[h_{\vw_{\frac{\eta}{2}}}]\right)z_i}\geq\frac{S}{2}\right)\leq2\exp{\frac{-2N_sS^2}{4\cdot(8MC_1)^2}}.
$$
The number of elements in $\gH_\eta$ can be upper-bounded as $N(\eta,W)\leq\left(\frac{2W\sqrt{d_N}}{\eta}\right)^{d_N}$ \cite[Example 27.1]{Shalev-Shwartz_Ben-David_2014},
 where $N(\eta,W)$ is the number of elements in $\gH_\eta$ given $\eta$ and $W$. This results in the bound
\begin{align}\label{eq:E7bound}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\Pr(E_7^c)\leq\left(\frac{2W\sqrt{d_N}}{\eta}\right)^{d_N}2\exp{\frac{-2N_sS^2}{4\cdot(8MC_1)^2}}.
\end{align}
Substituting the bounds from \cref{e8,eq:E7bound} into \cref{baseineq}, we obtain
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
&\Pr\left(\exists ~h_{\vw_{\frac{\eta}{2}}}\in\gH_\eta|\frac{1}{N_s}\sum_{i=1}^{N_s}h_\vw(\vx_{si},t_{si})z_i\geq S\right)\\
&\quad\leq2\left(\frac{2W\sqrt{d_N}}{\eta}\right)^{d_N}\exp{\frac{-N_sS^2}{2\cdot(8MC_1)^2}} + 2\exp{\frac{-N_sS^2}{32M^2C_1^2}},
\end{align*}
which finishes the proof.
\end{proof}

\begin{proof}[Proof of \cref{lem:perturb}]
The proof proceeds by separately computing the variation in each term of the loss in \cref{def:hjbloss} under perturbation of the weights. 

\paragraph{Initial Condition Loss:} 
The variation of the initial condition loss term at any specific collocation point $\vx_{0j}$ in \cref{def:hjbloss} is given by:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
&\left(h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0)-g(\vx_{0j})\right)^2-\left(h_{\vw}(\vx_{0j}, 0)-g(\vx_{0j})\right)^2\\
&=\left(h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0)-h_{\vw}(\vx_{0j}, 0)\right)\left( h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0)+h_{\vw}(\vx_{0j}, 0) - 2g(\vx_{0j})\right).
\end{align*}
Invoking the conditions in \cref{def:nets}, we get $h_{\vw_\frac{\eta}{2}}(\vx,t)= f(\mW_{1_{\frac{\eta}{2}}} \vx + \vw_{2_{\frac{\eta}{2}}} t)$, where $W_{1_{\frac{\eta}{2}}}$ and $\vw_{2_{\frac{\eta}{2}}}$ are the $\frac{\eta}{2}-$perturbed weights. Hence,
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0) - h_{\vw}(\vx_{0j}, 0)&=f(\mW_{1_{\frac{\eta}{2}}} \vx_{0j}) - f(\mW_1 \vx_{0j}) \leq L_1\norm{(\mW_{1_{\frac{\eta}{2}}}-\mW_1)\vx_{0j}}\\
   &\leq L_1\norm{(\mW_{1_{\frac{\eta}{2}}}-\mW_1)}_F\norm{\vx_{0j}}\leq L_1\frac{\eta}{2}\sqrt{n}B.
\end{align*}
Recalling the bound on the predictor, we obtain
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0)+h_{\vw}(\vx_{0j}, 0)=f(\mW_{1_{\frac{\eta}{2}}} \vx_{0j}) + f(\mW_1 \vx_{0j}) \leq2C_1.
$$
Thus, the total variation in the initial condition loss is
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \left(h_{\vw_\frac{\eta}{2}}(\vx_{0j}, 0)-g(\vx_{0j})\right)^2-\left(h_{\vw}(\vx_{0j}, 0)-g(\vx_{0j})\right)^2\leq L_1\eta\sqrt{n}B\left(C_1+G\right).
$$

\textbf{Supervised Loss:}
The perturbation bound on the supervised loss follows similarly to the above bound, recalling from \cref{lossfunction} that the labels are bounded in magnitude by $M$, and noting that $\norm{\vx} + \abs{t} \leq \sqrt{n}B + T$:
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \left(h_{\vw_\frac{\eta}{2}}(\vx_{si}, t_{si})-y_{si}\right)^2-\left(h_{\vw}(\vx_{si}, t_{si})-y_{si}\right)^2\leq L_1\eta(\sqrt{n}B+T)\left(C_1+M\right).
$$

\paragraph{PDE Residual Loss:} From \cref{def:nets}, we recall that $\nabla f \in \R^k$ and obtain:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}  
&\partial_t h_{\vw}(\vx,t) =\partial_t f(\mW_1\vx + \vw_2t) =\ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t)}\\
&\nabla h_{\vw}(\vx,t) =\nabla f(\mW_1\vx + \vw_2t) =\mW_1^\top\nabla f(\mW_1\vx + \vw_2t)\\
&\nabla^2 h_{\vw}(\vx,t) =\nabla^2 f(\mW_1\vx + \vw_2t) =\sum_{i=1}^n\partial_{x_i}[\mW_1^\top\nabla f(\mW_1\vx + \vw_2t)]_i\\
&=\sum_{i=1}^n\partial_{x_i}(\sum_{p=1}^kW_{1,pi}[\nabla f(\mW_1\vx+\vw_2t)]_p)=\sum_{i=1}^n\sum_{p=1}^kW_{1,pi}\partial_{x_i}((\partial_p f)(\mW_1\vx+\vw_2t))\\ 
&=\sum_{i=1}^n\sum_{p=1}^kW_{1,pi}\ip{\mW_{1,col(i)}}{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}.
\end{align*}
In the final term above, $\mW_{1,col(i)}$ is the $i^{th}$column of $\mW_1$ and $\partial_p f : \R^k \rightarrow \R$ is the partial derivative of $f$ with respect to its $p^{th}$ input coordinate. Thus, we are led to the following bounds on the variation of the HJB residual loss under the considered weight perturbation:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\left(\partial_t h_{\vw}(\vx,t) - \nabla^2 h_{\vw}(\vx,t) + \norm{\nabla h_{\vw}(\vx,t)}^2\right)^2 - \left(\partial_t h_{\vw_\frac{\eta}{2}}(\vx,t) - \nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t) + \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2\right)^2\\
    =& \left((\partial_t h_{\vw}(\vx,t) + \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)) - (\nabla^2 h_{\vw}(\vx,t) + \nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t)) + \left(\norm{\nabla h_{\vw}(\vx,t)}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2\right)\right)\\
    &\times\left((\partial_t h_{\vw}(\vx,t) - \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)) + (\nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t) - \nabla^2 h_{\vw}(\vx,t)) + \left(\norm{\nabla h_{\vw}(\vx,t)}^2 - \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2\right)\right)\\
    \leq& \left(\norm{\partial_t h_{\vw}(\vx,t) + \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)} + \norm{\nabla^2 h_{\vw}(\vx,t) + \nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t)} + \left \vert\norm{\nabla h_{\vw}(\vx,t)}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2\right \vert \right )\\
    &\times\left(\norm{\partial_t h_{\vw}(\vx,t) - \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)} + \norm{\nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t) - \nabla^2 h_{\vw}(\vx,t)} + \left \vert \norm{\nabla h_{\vw}(\vx,t)}^2 - \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2 \right \vert \right).
\end{align*}
Substituting in the above the bounds from \cref{p1,p2,p3,p4,p5,p6} we get
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
&\left(\norm{\partial_t h_{\vw}(\vx,t) + \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)} + \norm{\nabla^2 h_{\vw}(\vx,t) + \nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t)} + \left \vert \norm{\nabla h_{\vw}(\vx,t)}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2 \right \vert \right)\\
&\times\left(\norm{\partial_t h_{\vw}(\vx,t) - \partial_t h_{\vw_\frac{\eta}{2}}(\vx,t)} + \norm{\nabla^2 h_{\vw_\frac{\eta}{2}}(\vx,t) - \nabla^2 h_{\vw}(\vx,t)} + \left \vert \norm{\nabla h_{\vw}(\vx,t)}^2 - \norm{\nabla h_{\vw_\frac{\eta}{2}}(\vx,t)}^2 \right \vert \right)\\
&\leq \biggl(\frac{\eta}{2}\left(C_2 + WL_2\left(\norm{\vx}+\abs{t}\right)\right) + 2WC_2+C_3nk\left(2W^2 + \eta W + \left(\frac{\eta}{2}\right)^2\right)+WC_2\eta(WL_2\left(\norm{\vx}+\abs{t}\right)+C_2)\\
&+ 2(WC_2)^2 + \frac{\eta}{2}(WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2))\biggr)\\
&\times\Bigg(\frac{\eta}{2}(C_2 + WL_2(\norm{\vx}+\abs{t}))+C_3nk\left(\eta W + \left(\frac{\eta}{2}\right)^2\right)\\
&+\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t})+C_2)\left(\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t}) + C_2)+2WC_2\right)\Bigg)\\
&=a_4\eta^4+a_3\eta^3+a_2\eta^2+b_1\eta,
\end{align*}
where, using that $\norm{\vx}+\abs{t}\leq\sqrt{n}B+T= V$ and the bounds $L_1\leq C_2$ and $L_2\leq C_3$,
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    a_4&=\frac{1}{16}\left(C_3nk+WC_3V+C_2\right)\left(C_3nk+\left(WC_3V+C_2\right)^2\right)\\
    a_3&=\frac{1}{4}\left(C_3nk+WC_3V+C_2\right)\left((WC_3V+C_2)\left(\frac{1}{2}+WC_2\right)+C_3nkW\right)\\
    &+\frac{1}{4}\left(C_3nk+(WC_3V+C_2)^2\right)\left(C_2\left(\frac{1}{2}+W\left(C_3V+C_2^2+1\right)\right)+W\left(\frac{1}{2}C_3V+C_3nk\right)\right)\\
    \nonumber a_2&=\frac{1}{4}\left(C_3nk+(WC_3V+C_2)^2\right)\left(WC_2(1+WC_2)+C_3nkW^2\right)\\
    &+\left((WC_3V+C_2)\left(\frac{1}{2}+WC_2\right)+C_3nkW\right)\left(C_2\left(\frac{1}{2}+W\left(C_3V+C_2^2+1\right)\right)+W\left(\frac{1}{2}C_3V+C_3nk\right)\right)\\
b_1&=2\left((WC_3V+C_2)\left(1+2WC_2\right)+C_3nkW\right)\left(WC_2(1+WC_2)+C_3nkW^2\right).
\end{align*}
Combining the results from all three loss components, we arrive at 
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\hat{R}(h_{\vw_{\frac{\eta}{2}}})\leq\hat{R}(h_\vw) + \lambda_sC_2\eta V\left(C_1+M\right) + \lambda_0C_2\eta\sqrt{n}B\left(C_1+G\right) + a_4\eta^4+a_3\eta^3+a_2\eta^2+b_1\eta,
$$
which proves the result.
\end{proof}

\section{Deriving the HJB PDE from Optimal Stochastic Control}\label{sec:control}

We follow the presentation in works like \citep{HJBviscosity} and \citep{wang2022}, to review how the HJB equations emerge from optimal stochastic control. In stochastic control theory, the state function $\{X_t\}_{0\leq t\leq T}$ is a stochastic process, where $T$ is the time horizon. The evolution of the state function by
\[\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}\left\{\begin{aligned}
    &dX_s=m(s,X_s)ds + \sigma dW_s\quad s\in[t,T]\\
    &X_t=x,
\end{aligned}\right. \]
where $m:[t,T]\times\R^n\rightarrow\R^n$ is the control function and $\{W_s\}$ is a standard $n$-dimensional Brownian motion. The total cost is defined as
$$
J_{x,t}(m)=\E\left[\int_t^Tr(X_s,m,s)ds+g(X_T)\right],
$$
where $r:\R^n\times\R^n\times[0,T]\rightarrow\R$ measures the cost rate during the process and $g:\R^n\rightarrow\R$ measures the final cost at the terminal state. The goal is then to find the value function of the control problem, $u(x,t)=\min_{m\in\gM}J_{x,t}(m)$, where $\gM$ is the set of possible control functions being taken into consideration. It can be shown that the value function $u$ satisfies the HJB Equation
\[\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}\left\{\begin{aligned}
    &\partial_tu(x,t) + \frac{1}{2}\sigma^2\nabla^2u(x,t)+\min_{m\in\gM}[r(x,m(t,x),t)+\ip{\nabla u}{m_t}]=0\\
    &u(x,T)=g(x).
\end{aligned}\right.\]
Denote $m(x,t)=(m_1(x,t),m_2(x,t),\ldots,m_n(x,t))$ as $\vy\in\R^n$ and set $r(x,y,t)=\frac{1}{4}\norm{y}^2_2$. The third term in the HJB Equation becomes
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\min_{\vy\in\R^n} \left ( \frac{1}{4}\norm{\vy}_2^2+\ip{\nabla u}{\vy} \right ) =\sum_{i=1}^n\min_{y_i\in\R} \left ( \frac{1}{4}y_i^2+y_i\partial_{x_i}u] \right ).
$$
It can be shown that $\min_{y_i\in\R}[\frac{1}{4}y_i^2+y_i\partial_{x_i}u]=-(\partial_{x_i}u)^2$ by setting $y_i=2\partial_{x_i}u$, which results in the following class of HJB equations:
\[\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}\left\{\begin{aligned}
    &\partial_tu(x,t) + \frac{1}{2}\sigma^2\nabla^2u(x,t)-\norm{\nabla u}_2^2=0 \text{ in $\R^n\times[0,T]$}\\
    &u(x,T)=g(x).
\end{aligned}\right.\]
Taking the transformation $v(x,t)=u(x,T-t)$ and setting $\sigma=\sqrt{2}$ the equation becomes
\[\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}\left\{\begin{aligned}
    &\partial_tv(x,t) - \nabla^2v(x,t) + \norm{\nabla v }_2^2=0 \text{ in $\R^n\times[0,T]$}\\
    &v(x,0)=g(x).
\end{aligned}\right.\]

\section{Depth 2 Sigmoid Activation NN Bounds}\label{sec:depth2}
Let $f:\R^k\rightarrow\R$ be defined as $f(\vz)=\ip{\va}{\sigma(\vz)}$ for $\va\in\R^k$ where $\sigma$ is the sigmoid function acting component-wise. Using the fact that $\abs{\sigma(x)}\leq1$ for all $x\in\R$, the $C_1$ bound can be derived as follows
\begin{equation}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \nonumber \norm{f}=\norm{\ip{\va}{\sigma(\vz)}}=\abs{\sum_{i=1}^ka_i\sigma(z_i)}\leq\abs{\sum_{i=1}^ka_i}=\norm{\va}_1=C_1.
\end{equation}
The derivative of sigmoid is
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\sigma'(x)=\frac{e^x}{(1+e^x)^2},
$$
which has the property $\abs{\sigma'(x)}\leq\frac{1}{4}$ for all $x\in\R$. The gradient of $f$ is $\nabla f_i=a_i\sigma'(z_i)$ so the $C_2$ bound can be derived as follows
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\norm{\nabla f}=\sqrt{\sum_{i=1}^k(\nabla f_i)^2}=\sqrt{\sum_{i=1}^k(a_i\sigma'(z_i))^2}\leq\sqrt{\sum_{i=1}^k\left(\frac{a_i}{4}\right)^2}=\frac{1}{4}\sqrt{\sum_{i=1}^k(a_i^2)}=\frac{1}{4}\norm{\va}=C_2.
$$
The second derivative of sigmoid is,
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\sigma''(x)=-\frac{e^x(e^x-1)}{(1+e^x)^3},
$$
which also has the property that $\sigma''(x)\leq\frac{1}{4}$ for all $x\in\R$. The elements of the Hessian of $f$ are given by $Hf_{i,j}=\partial_{z_i}\partial_{z_j}f=\partial_{z_i}a_j\sigma'(z_j)$, which is only non-zero when $i=j$, where it becomes $Hf_{i,i}=a_i\sigma''(z_i)$. The $C_3$ bound is therefore
$$\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\norm{Hf}_F=\sqrt{\sum_{i=1}^k\sum_{j=1}^k(\partial_{z_i}\partial_{z_j}f)^2}=\sqrt{\sum_{i=1}^k(a_i\sigma''(z_i))^2}\leq\sqrt{\sum_{i=1}^k\left(\frac{a_i}{6\sqrt{3}}\right)^2}=\frac{1}{6\sqrt{3}}\norm{\va}=C_3.
$$




\section{Intermediate Results on Bounds on Derivatives of the Predictor and Its Perturbations}

In this Appendix in the six lemmas given below, we compute the upper bound on the following $6$ terms, $\partial_t h_\vw - \partial_t h_{\vw_\frac{\eta}{2}}$, $\partial_t h_\vw + \partial_t h_{\vw_\frac{\eta}{2}}$, $\|{\nabla h_\vw}\|^2 - \|{\nabla h_{\vw_\frac{\eta}{2}}}\|^2$, $\|{\nabla h_\vw}\|^2 - \|{\nabla h_{\vw_\frac{\eta}{2}}}\|^2$, $\|{\nabla h_\vw}\|^2 + \|{\nabla h_{\vw_\frac{\eta}{2}}}\|^2$, $\nabla^2 h_{\vw_\frac{\eta}{2}} - \nabla^2 h_\vw$ and $\nabla^2 h_\vw + \nabla^2 h_{\vw_\frac{\eta}{2}}$.


\begin{lemma}[Upper bound on $\partial_t h_\vw - \partial_t h_{\vw_\frac{\eta}{2}}$]\label{p1}
The following bound holds:
$$
\partial_t h_\vw - \partial_t h_{\vw_\frac{\eta}{2}} \leq\frac{\eta}{2}(C_2 + WL_2(\norm{\vx}+\abs{t})).
$$
\end{lemma}

\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\partial_t h_\vw - \partial_t h_{\vw_\frac{\eta}{2}}\\
    &= \ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t)} - \ip{\vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &= \ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t)} - \ip{\vw_2}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &+ \ip{\vw_2}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} -  \ip{\vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &=\ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} + \ip{\vw_2 - \vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}.
\end{align*}
Because of the bound $\|{\vw-\vw_{\frac{\eta}{2}}}\|\leq\frac{\eta}{2}$ and \cref{def:nets}, $\|{\nabla f(\vz_1)-\nabla f(\vz_2)}\|\leq L_2\|{\vz_1-\vz_2}\|$, we have
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \ip{\vw_2 - \vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}&\leq\norm{\vw_2 - \vw_{2_{\frac{\eta}{2}}}}\norm{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &\leq\frac{\eta}{2}\norm{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\leq\frac{\eta}{2}C_2
		\end{align*}
		and
		\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} &\leq\norm{\vw_2}\norm{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &\leq W\cdot L_2\norm{(\mW_1-\mW_{1_{\frac{\eta}{2}}})\vx + (\vw_2-\vw_{2_{\frac{\eta}{2}}})t}\\
    &\leq WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}).
\end{align*}
Combining the two completes the proof.
\end{proof}


\begin{lemma}[Upper bound on $\partial_t h_\vw + \partial_t h_{\vw_\frac{\eta}{2}}$]\label{p2}
The following bound holds:
$$
\partial_t h_\vw + \partial_t h_{\vw_\frac{\eta}{2}} \leq\frac{\eta}{2}(C_2 + WL_2(\norm{\vx}+\abs{t})) + 2WC_2.
$$
\end{lemma}

\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\partial_t h_\vw + \partial_t h_{\vw_\frac{\eta}{2}}\\
    &= \ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t)} + \ip{\vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &= \ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t)} - \ip{\vw_2}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &+ \ip{\vw_2}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} +  \ip{\vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &=\ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} + \ip{\vw_2 + \vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}.
\end{align*}
Recalling that $\|{\vw-\vw_{\frac{\eta}{2}}}\|\leq\frac{\eta}{2}$ and $\norm{\nabla f(\vz_1)-\nabla f(\vz_2)}\leq L_2\|{\vz_1-\vz_2}\|$, we have 
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    \ip{\vw_2 + \vw_{2_{\frac{\eta}{2}}}}{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}&\leq\norm{\vw_2 + \vw_{2_{\frac{\eta}{2}}}}\norm{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &\leq\left(\frac{\eta}{2}+2W\right)\norm{\nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\leq\left(\frac{\eta}{2}+2W\right)C_2
		\end{align*}
		and
		\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\ip{\vw_2}{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)} \\
		&\quad\quad\quad\leq\norm{\vw_2}\norm{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1_{\frac{\eta}{2}}}\vx + \vw_{2_{\frac{\eta}{2}}}t)}\\
    &\quad\quad\quad\leq W\cdot L_2\norm{(\mW_1-\mW_{1_{\frac{\eta}{2}}})\vx + (\vw_2-\vw_{2_{\frac{\eta}{2}}})t}\leq WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t})
\end{align*}
Combining the two completes the proof.
\end{proof}

\begin{lemma}[Upperbound on $\|{\nabla h_\vw}\|^2 - \|{\nabla h_{\vw_\frac{\eta}{2}}}\|^2$]\label{p3}
The following bound holds:
$$
\norm{\nabla h_\vw}^2 - \norm{\nabla h_{\vw_\frac{\eta}{2}}}^2\leq\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t})+C_2)\left(\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t}) + C_2)+2WC_2\right).
$$
\end{lemma}

\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\norm{\nabla h_\vw}^2 - \norm{\nabla h_{\vw_\frac{\eta}{2}}}^2\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw} - \ip{\nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw} - \ip{\nabla h_\vw}{\nabla h_{\vw_\frac{\eta}{2}}} + \ip{\nabla h_\vw}{\nabla h_{\vw_\frac{\eta}{2}}} - \ip{\nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}} + \ip{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &\leq \norm{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}\norm{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}}
\end{align*}
Looking specifically at $\|{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}}\|$,
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\norm{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \norm{\mW_1^\top\nabla f(\mW_1\vx + \vw_2t) - \mW_{1,\frac{\eta}{2}}^\top\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &= \norm{\mW_1^\top(\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)) + (\mW_1^\top - \mW_{1,\frac{\eta}{2}}^\top)\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &\leq \norm{\mW_1^\top}_F\norm{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t))} + \norm{\mW_1^\top - \mW_{1,\frac{\eta}{2}}^\top}F\norm{\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &\leq WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + \frac{\eta}{2}C_2 = \frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t})+C_2).
\end{align*}
Then looking at $\|{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}\|$,
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\norm{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \norm{\mW_1^\top\nabla f(\mW_1\vx + \vw_2t) + \mW_{1,\frac{\eta}{2}}^\top\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &= \norm{\mW_1^\top(\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)) + (\mW_1^\top + \mW_{1,\frac{\eta}{2}}^\top)\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &\leq \norm{\mW_1^\top}_F\norm{\nabla f(\mW_1\vx + \vw_2t) - \nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t))} + \norm{\mW_1^\top + \mW_{1,\frac{\eta}{2}}^\top}_F\norm{\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\\
    &\leq WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2.
\end{align*}
Combining these two completes the proof.
\end{proof}

\begin{lemma}[Upper bound on $\|{\nabla h_\vw}\|^2 + \|{\nabla h_{\vw_\frac{\eta}{2}}}\|^2$]\label{p4}
The following bound holds:
$$
\norm{\nabla h_\vw}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}}^2\leq WC_2\eta(WL_2(\norm{\vx}+\abs{t})+C_2) + 2(WC_2)^2 + \frac{\eta}{2}(WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2)).
$$
\end{lemma}

\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\norm{\nabla h_\vw}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}}^2\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw} + \ip{\nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw} - \ip{\nabla h_\vw}{\nabla h_{\vw_\frac{\eta}{2}}} + \ip{\nabla h_\vw}{\nabla h_{\vw_\frac{\eta}{2}}} + \ip{\nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &= \ip{\nabla h_\vw}{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}} + \ip{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}{\nabla h_{\vw_\frac{\eta}{2}}}\\
    &\leq\norm{\nabla h_\vw}\norm{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}} + \norm{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}\norm{\nabla h_{\vw_\frac{\eta}{2}}}.
\end{align*}
Using the bounds on $\|{\nabla h_\vw - \nabla h_{\vw_\frac{\eta}{2}}}\|$ and $\|{\nabla h_\vw + \nabla h_{\vw_\frac{\eta}{2}}}\|$ derived above, we can bound this by
$$
\norm{\nabla h_\vw}(\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t})+C_2)) + (WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2))\norm{\nabla h_{\vw_\frac{\eta}{2}}}.
$$
The following two bounds hold:
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
\norm{\nabla h_\vw} &= \norm{\mW_1^\top\nabla f(\mW_1\vx + \vw_2t)}\leq\norm{\mW_1^\top}_F\norm{\nabla f(\mW_1\vx + \vw_2t)}\leq WC_2,\\
\norm{\nabla h_{\vw_\frac{\eta}{2}}} &= \norm{\mW_1^\top\nabla f(\mW_1\vx + \vw_2t)}\leq\norm{\mW_{1,\frac{\eta}{2}}^\top}_F\norm{\nabla f(\mW_{1,\frac{\eta}{2}}\vx + \vw_{2,\frac{\eta}{2}}t)}\leq (W+\frac{\eta}{2})C_2.
\end{align*}
Hence,
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\norm{\nabla h_\vw}^2 + \norm{\nabla h_{\vw_\frac{\eta}{2}}}^2\\
    &\leq WC_2\left(\frac{\eta}{2}(WL_2(\norm{\vx}+\abs{t})+C_2)\right) + \left(W+\frac{\eta}{2}\right)C_2\left(WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2\right)\\
    &=WC_2\eta\left(WL_2(\norm{\vx}+\abs{t})+C_2\right) + 2(WC_2)^2 + \frac{\eta}{2}\left(WL_2\frac{\eta}{2}(\norm{\vx}+\abs{t}) + (2W+\frac{\eta}{2})C_2\right),
\end{align*}
which proves the result.
\end{proof}

\begin{lemma}[Upper bound on $\nabla^2 h_{\vw_\frac{\eta}{2}} - \nabla^2 h_\vw$]\label{p5}
The following bound holds:
$$
\nabla^2 h_{\vw_\frac{\eta}{2}} - \nabla^2 h_\vw\leq C_3nk\left(\eta W + \left(\frac{\eta}{2}\right)^2\right).
$$
\end{lemma}
\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\nabla^2 h_{\vw_\frac{\eta}{2}} - \nabla^2 h_\vw\\
    &= \sum_{i=1}^n\sum_{p=1}^kW_{1,\frac{\eta}{2},pi}\ip{\mW_{1,\frac{\eta}{2},col(i)}}{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} - \sum_{i=1}^n\sum_{p=1}^kW_{1,pi}\ip{\mW_{1,col(i)}}{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\\
    &= \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\ip{\mW_{1,\frac{\eta}{2},col(i)}}{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} - W_{1,pi}\ip{\mW_{1,col(i)}}{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\right)\\
    &\leq \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\norm{\mW_{1,\frac{\eta}{2},col(i)}}\norm{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} - W_{1,pi}\norm{\mW_{1,col(i)}}\norm{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\right)
\end{align*}
Using the property of $f$ that $\norm{Hf(\vz)}_F\leq C_3$, we can bound this by
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\norm{\mW_{1,\frac{\eta}{2},col(i)}}C_3 - W_{1,pi}\norm{\mW_{1,col(i)}}C_3\right)\leq \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}(W+\frac{\eta}{2})C_3 - W_{1,pi}WC_3\right)\\
    &= C_3\sum_{i=1}^n\sum_{p=1}^k\left((W_{1,\frac{\eta}{2},pi} - W_{1,pi})W + \frac{\eta}{2}W_{1,\frac{\eta}{2},pi}\right)\leq C_3\sum_{i=1}^n\sum_{p=1}^k\left(\frac{\eta}{2}W + \frac{\eta}{2}(W+\frac{\eta}{2}))\right)\\
    &= C_3\sum_{i=1}^n\sum_{p=1}^k\left(\eta W + \left(\frac{\eta}{2}\right)^2\right)= C_3nk\left(\eta W + \left(\frac{\eta}{2}\right)^2\right).
\end{align*}
The result now follows.
\end{proof}

\begin{lemma}[Upper bound on $\nabla^2 h_{\vw_\frac{\eta}{2}} + \nabla^2 h_\vw$]\label{p6}
The following bound holds:
$$\nabla^2 h_{\vw_\frac{\eta}{2}} + \nabla^2 h_\vw\leq C_3nk\left(2W^2 + \eta W + \left(\frac{\eta}{2}\right)^2\right).
$$
\end{lemma}
\begin{proof}We first write
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\nabla^2 h_{\vw_\frac{\eta}{2}} + \nabla^2 h_\vw\\
    &= \sum_{i=1}^n\sum_{p=1}^kW_{1,\frac{\eta}{2},pi}\ip{\mW_{1,\frac{\eta}{2},col(i)}}{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} + \sum_{i=1}^n\sum_{p=1}^kW_{1,pi}\ip{\mW_{1,col(i)}}{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\\
    &= \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\ip{\mW_{1,\frac{\eta}{2},col(i)}}{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} + W_{1,pi}\ip{\mW_{1,col(i)}}{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\right)\\
    &\leq \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\norm{\mW_{1,\frac{\eta}{2},col(i)}}\norm{(\grad\partial_pf)(\mW_{1,\frac{\eta}{2}}\vx+\vw_{2,\frac{\eta}{2}}t)} + W_{1,pi}\norm{\mW_{1,col(i)}}\norm{(\grad\partial_pf)(\mW_1\vx+\vw_2t)}\right)
\end{align*}
Using the property of $f$ that $\norm{Hf(\vz)}_F\leq C_3$, we can bound this by
\begin{align*}\setlength\abovedisplayskip{6pt}\setlength\belowdisplayskip{6pt}
    &\sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}\norm{\mW_{1,\frac{\eta}{2},col(i)}}C_3 + W_{1,pi}\norm{\mW_{1,col(i)}}C_3\right)\leq \sum_{i=1}^n\sum_{p=1}^k\left(W_{1,\frac{\eta}{2},pi}(W+\frac{\eta}{2})C_3 + W_{1,pi}WC_3\right)\\
    &= C_3\sum_{i=1}^n\sum_{p=1}^k\left((W_{1,\frac{\eta}{2},pi} + W_{1,pi})W + \frac{\eta}{2}W_{1,\frac{\eta}{2},pi}\right)\leq C_3\sum_{i=1}^n\sum_{p=1}^k\left((2W + \frac{\eta}{2})W + \frac{\eta}{2}(W+\frac{\eta}{2}))\right)\\
    &= C_3\sum_{i=1}^n\sum_{p=1}^k\left(2W^2 + \eta W + \left(\frac{\eta}{2}\right)^2\right)= C_3nk\left(2W^2 + \eta W + \left(\frac{\eta}{2}\right)^2\right).
\end{align*}
The result now follows.
\end{proof}



