\section{Adiabatic Quantum Computing} \label{sec:qat}

In \Crefitem{thm:main}{itm:thm:main_2} and \Crefitem{thm:qhd}{itm:thm:qhd_2}, we used the following lemmas:
\begin{lemma} \label{lem:qatsim}
	Let \( H(t) \) be an explicitly \( s \)-sparse \apath\ for \( t \in [0,1] \). Suppose that $\|H(t)\|$, \( \|\dot{H}(t)\| \), and \( \|\ddot{H}(t)\| \) are all upper bounded by \( M \) and that the spectral gap of \( H(t) \) is at least \( \delta \) for all \( t \). Furthermore, assume that the ground state of \( H(0) \) is \(\eta\)-close to an efficiently preparable state \(\ket{\phi}\). Then, there is a quantum algorithm, given oracle access to $H(t)$, that simulates the \sdg\  dynamics
	\begin{equation} \label{eq:a1-sdg}
		i \frac{\dee}{\dee t} \ket{\psi(t)} = T H(t) \ket{\psi(t)}, \quad \ket{\psi(0)} = \ket{\phi}, \quad T = \Theta\left(\frac{M^2}{\delta^3 \eta}\right),
	\end{equation}
	producing a final state \(\ket{\psi(1)}\) that is \(2\eta\)-close to the ground state of \( H(1) \) with query and gate complexity
	$
		(n s T M)^{1+o(1)}
	$.
\end{lemma}

\begin{lemma} \label{lem:qatsim2}
	Let \( H(t) = -\Delta + V(t,x) \) be a \apath\ for \( t \in [0,\tend] \). Suppose that $ |V(t,x)|$, \( \|\dot{H}(t)\| \leq \max_x | \dot{V}(t,x) | \), and \( \|\ddot{H}(t)\| \leq \max_x | \ddot{V}(t,x) | \) are all upper bounded by \( M \) and that the spectral gap of \( H(t) \) is at least \( \delta \) for all \( t \). Furthermore, assume that the ground state of \( H(0) \) is \(\eta\)-close to an efficiently preparable state \(\ket{\phi}\). Then, there is a quantum algorithm, given oracle access to $V(t,x)$, that simulates the \sdg\  dynamics
	\begin{equation} \label{eq:a2-sdg}
		i \frac{\dee}{\dee t} \ket{\psi(t)} = T H(t) \ket{\psi(t)}, \quad \ket{\psi(0)} = \ket{\phi}, \quad T = \Theta\left(\frac{M^2}{\delta^3 \eta}\right),
	\end{equation}
	producing a final state \(\ket{\psi(\tend)}\) that is \(2\eta\)-close to the ground state of \( H(\tend) \) with query and gate complexity
	$
		(n T M)^{1+o(1)}
	$.
\end{lemma}

The correctness of \Cref{lem:qatsim} directly follows from combining the \emph{quantum adiabatic theorem} (\Cref{thm:adiabatic}) and the rescaled Dyson-series algorithm~\cite{berry2020time} that simulates \Cref{eq:a1-sdg} with query and gate complexity \( (nsTM)^{1+o(1)}\).

Similarly, The correctness of \Cref{lem:qatsim2} follows from \Cref{thm:adiabatic} and an algorithm~\cite[Theorem 3]{Childs2022} that simulates \Cref{eq:a2-sdg} with query and gate complexity \( (nTM)^{1+o(1)}\).

\subsection{Quantum Adiabatic Theorem}

Given a time-dependent Hamiltonian \( H(t) \) for \( t \in [0,1] \), denote by \( \ket{\phi(t)} \) the ground state of \( H(t) \).
The \emph{quantum adiabatic theorems} provide conditions under which the evolution remains close to \( \ket{\phi(t)} \).
Specifically, consider the following Schr\"odinger equation:
\begin{equation} \label{eq:adiabatic}
	i \frac{\dee}{\dee t} \ket{\psi(t)} = T H(t) \ket{\psi(t)}, \quad t \in [0,1],
\end{equation}
with an initial state \( \ket{\psi(0)} \coloneqq \ket{\phi(0)} \) and a sufficiently large evolution time \( T \).
This dynamics is considered adiabatic because it can be rewritten via the change of variable \( s \coloneqq tT \), often referred to as a \emph{time dilation} argument:
\begin{equation}
	i \frac{\dee}{\dee s} \ket{{\psi}(s/T)} = \tilde{H}(s) \ket{{\psi}(s/T)}, \quad s \in [0,T],
\end{equation}
where \( \tilde{H}(s) \coloneqq H(s/T) \). In this formulation, \( \tilde{H}(s) \) varies infinitesimally slowly as \( T \to \infty \), ensuring adiabatic evolution.
Below, we introduce a version of the theorem that establishes a sufficient bound on \( T \) based on the operator norm of \( \dot{H}(t) \) and \( \ddot{H}(t) \) and the spectral gap of \( H(t) \), following a standard operator-theoretic approach.
For an elementary proof with slightly weaker bounds but offering more intuition, we refer the reader to~\cite{ambainis2004elementary}.

\begin{theorem}[\cite{Teufel2003,jansen2007bounds,childs2025lecture}] \label{thm:adiabatic}
	Suppose \( H(t) \) is piecewise twice differentiable and has a nondegenerate ground state for all \( t \in [0,1] \).
	Furthermore, \( \|\dot{H}(t)\| \) and \( \|\ddot{H}(t)\| \) are upper bounded by $M$ and the spectral gap of $H(t)$ is at least $\delta$ for all $t$.
	Then \Cref{eq:adiabatic} produces a final state \( \ket{\psi(1)} \) satisfying
	\begin{equation}
		\|\ket{\psi(1)} - \ket{\phi(1)}\| \leq \epsilon,
	\end{equation}
	provided that
	\begin{equation}
		T \geq \frac{1}{\epsilon} \cdot  O\left( \frac{M^2}{\delta^3} \right).
	\end{equation}
\end{theorem}
\begin{remark}
	Note that $H(t)$ itself can be unbounded in \Cref{thm:adiabatic}.
\end{remark}

\section{Explicit Technical Building Blocks}\label{sec:intro_merit}

We present clean statements of the main technical building blocks employed impiclitly in the proofs of \Cref{thm:main}.
These results have been modified to meet the specific requirements of our approach and are therefore (re)stated here for clarity and potential reuse.

\medskip

The following proposition reduces any stoquastic sparse Hamiltonian to a TFD Hamiltonian.
Its proof is implicit in those of \Cref{lem:pathA} and \ref{lem:pathB}.

\begin{proposition} \label{prop:merit_sparse}
	Let \( n, s, M \) be sufficiently large, and let \( \eta, \epsilon > 0 \) be sufficiently small.
	Then, there exist some $a>0$ and a mapping that transforms any \( n \)-qubit $s$-sparse stoquastic Hamiltonian \( H \) satisfying \( \|H\| \leq M \) into a \((6n+4s)\)-qubit stoquastic TFD Hamiltonian
	\begin{equation}
		K = -a \sum_{i\in[6n+4s]} X_i + D
	\end{equation}
	with $D$ diagonal, such that the following holds.

	\begin{enumerate}[label=(\roman*)]
		\item $(K,\calE)$ simulates $H$ with error $(\eta,\epsilon)$, where $\calE \colon \ket{x} \mapsto \ket{x,x,0^s,0^s,0^n,x,x,0^s,0^s,0^n}$ is the encoding isometry.
		\item $\norm{K} \leq \poly(1/\eta,1/\epsilon,n,s,M)$.
		\item An oracle for \( K \) can be efficiently implemented: a query to this oracle can be simulated using \( O(ns + s^2) \) queries to an oracle for \( H \), with gate complexity \( \poly(n, s) \).
	\end{enumerate}
\end{proposition}

The following proposition linearizes a Hamiltonian $K(t)$ to a Hamiltonian $H(t)$ that is linear in $t$. Note that the reduction \emph{preserves stoquasticity}. Its proof is implicit in those of \Cref{lem:pathB2}, \ref{lem:linearTFI}, and \ref{lem:pathC}.

\begin{proposition} \label{prop:merit_linearize}
	Let $K(t)$ be a $n$-qubit \apath\ that is explicitly $s$-sparse.
	Assume that for any $t\in[0,1]$, $K(t)$ has norm $\norm{K(t)}\le M$ and spectral gap at least $\delta$.
	Assume in addition that $K(t)$ is $L$-Lipschitz in $t$.

	Let $\lambda\le O(\delta/M)$ be arbitrary.
	For some $\ell=\Theta(L/\delta)$ and $\Delta\ge\poly(\ell,1/\lambda)$, define
	\begin{align}
		H(t)=\frac{\Delta}{\lambda}\left(\sum_{i=0}^\ell i(i+1-2t)\ketbra{i}{i}-\lambda\sum_{i=0}^{\ell-1}\left(\ketbra{i}{i+1}+\ketbra{i+1}{i}\right)\right) + \sum_{i=0}^\ell K(i/\ell)\tensor\ketbra{i}{i}.
	\end{align}
	Then the following holds.
	\begin{enumerate}[label=(\roman*)]
		\item For $t\in[0,1]$, $H(t)$ has spectral gap $\delta/4$, norm $\poly(1/\lambda,\ell)$, and sparsity at most $s+2$.
		\item Let $\ket{\psi}$ be a ground state of $K(0)$. Then $\ket{\psi} \tensor \ket{0}$ is $O(\lambda)$-close to a ground state of $H(0)$.
		\item Let $\ket{\psi'}$ be a ground state of $K(1)$. Then $\ket{\psi'}\tensor\ket{\ell}$ is $O(\lambda)$-close to a ground state of $H(1)$.
		\item An oracle for $H(t)$ can be efficiently implemented: a query to this oracle can be simulated using $O(1)$ queries to an oracle for $K(t)$, with gate complexity $\poly(n,s)$.
	\end{enumerate}
\end{proposition}
\begin{remark}
	We note that the statement can be strengthened such that $H(t)$ simulates $K(\tau)$ for some monotonically increasing function $\tau = \tau(t)$ satisfying $\tau(0)=0$ and $\tau(1)=1$, although certain parameter dependencies need to be adjusted.
\end{remark}

The following proposition transforms any hard instances exhibiting quantum advantage via adiabatic quantum optimization to hard instances exhibiting quantum advantage via Quantum Hamiltonian Descent (with the help of a quick-vanishing term $\nu(t)g(x)$).
Its proof is implicit in that of \Cref{thm:qhd}.

\begin{proposition} \label{prop:merit_dtc}
	Let $n,M,q$ be sufficiently large and $\epsilon,\delta>0$ be sufficiently small.
	Let $H_{\rm TFD}$ be an $n$-qubit TFD Hamiltonian such that $\norm{H_{\rm TFD}} \leq M$, and that all coefficients of $X_i$ in $H_{\rm TFD}$ are no more than $-1$.
	Let $D$ be an $n$-qubit diagonal Hamiltonian such that its eigenvalues lie in $[-1,0)$.
	Suppose that the \apath\ $H(t)$ of the form
	\begin{equation}
		H_{\rm TFD} \pathto D
	\end{equation}
	has quantum advantage given oracle access to $D$:
	\begin{enumerate}[label=(\roman*)]
		\item Any classical algorithm requires at least $q$ queries to find $u \in \binary^n$ that minimizes $\mel{u}{D}{u}$, with success probability greater than $1/q$.
		\item $H(t)$ has spectral gap $\delta$, norm $M$, and the ground state of $H(0) = H_{\rm TFD}$ is $\epsilon$-close to a product state.
	\end{enumerate}
	Then, there exist functions $g(x)$ and $\nu(t)$, and a family of functions $f \colon \mathcal{X} \to \mathbb{R}$ with a fixed box domain $\mathcal{X} \subset \mathbb{R}^n$ where the diameter of $\mathcal{X}$ is at most $\poly(M)$, such that the \apath\ $\hatH(t)$ of the form
	\begin{equation}
		\hatH(t) \coloneqq -\Delta + V(t,x),\quad V(t,x) \coloneqq \nu(t)g(x) + t f(x), \quad \forall t \geq 0, x \in \mathcal{X}
	\end{equation}
	has quantum advantage given oracle access to $f(\cdot)$:
	\begin{enumerate}[label=(\roman*)]
		\item Any classical algorithm requires at least $q$ queries to find an $x$ such that $f(x) - f(x^\ast) \leq \delta$, with success probability greater than $1/q$.
		\item $\hatH(t)$ has spectral gap at least $\frac{1}{\poly(n,1/\epsilon,1/\delta)}$, and the ground state of $\hatH(0)$ is $2\epsilon$-close to a product state.
		      Moreover, for any $\eta > 0$, there exists $\tend = \poly(M,1/\eta)$ such that $\langle \phi(\tend) |f|\phi(\tend)\rangle - f(x^\ast) \leq \eta$, where $\ket{\phi(t)}$ is the ground state of $\hatH(t)$.
		\item $f(x)$, $g(x)$, and $\nu(t)$ satisfy the following:
		      \begin{itemize}
			      \item $f(x)$ is bounded within $\pm \poly(n,M)$ and it is $\poly(n,M)$-Lipschitz. Moreover, $f(x)$ has $2^n$ local minima, and the function values at these minima correspond to the diagonal entries of the diagonal matrix $D$.
			      \item $g(x)$ is bounded within $\pm \poly(n,M, \log \frac{1}{\epsilon},\log \frac{1}{\delta})$ and it is $\poly(n,M, \log \frac{1}{\epsilon},\log \frac{1}{\delta})$-Lipschitz.
			      \item $\dfrac{\dee^k \nu}{\dee t^k} = e^{-\Theta(\sqrt{t})}$ for any $k$.
		      \end{itemize}
	\end{enumerate}

\end{proposition}
\begin{remark}
	The functions $f(x)$ and $g(x)$ can be made smooth (i.e., infinitely differentiable) by a more sophisticated construction of $\hatD$ in \Cref{def:hatD}, for example by convolving a mollifier with a more carefully designed base function.
	We chose not to present this approach formally, as the benefits are minimal and proofs of certain claims, e.g., \Crefitem{fct:hatD}{itm:fct:hatD_1}, would be more complicated.
\end{remark}
